insert into leaders (id, name, country, dynasty, role, start_year, end_year, summary, scored_at) values
('geunchogo', '근초고왕', '한국', '삼국', '군주', 346, 375, '백제의 영역을 크게 넓히고 대외 교류를 활발히 하여 4세기 백제의 전성기를 이끌었다.', '2026-10-14'),
('gwanggaeto', '광개토대왕', '한국', '삼국', '군주', 391, 412, '활발한 정복 활동으로 고구려의 영토를 크게 넓히고 동북아시아의 강국으로 만들었다.', '2026-10-14'),
('jangsu', '장수왕', '한국', '삼국', '군주', 413, 491, '평양 천도와 남진 정책으로 한강 유역을 차지하며 고구려의 최대 전성기를 이루었다.', '2026-10-14'),
('jinheung', '진흥왕', '한국', '삼국', '군주', 540, 576, '한강 유역 확보와 가야 정복으로 신라의 영토를 크게 넓히고 삼국 통일의 기반을 놓았다.', '2026-10-14'),
('uija', '의자왕', '한국', '삼국', '군주', 641, 660, '즉위 초 신라를 크게 몰아붙였으나 말년의 실정과 나당 연합군의 침공으로 백제의 마지막 왕이 되었다.', '2026-10-14'),
('muyeol', '무열왕 김춘추', '한국', '삼국', '군주', 654, 661, '외교로 당과의 동맹을 이끌어 내고 최초의 진골 출신 왕으로서 백제를 멸망시켜 삼국 통일의 길을 열었다.', '2026-10-14'),
('munmu', '문무왕', '한국', '삼국', '군주', 661, 681, '고구려를 멸망시키고 나당 전쟁에서 당군을 몰아내 삼국 통일을 완성했다.', '2026-10-14'),
('yeon-gaesomun', '연개소문', '한국', '삼국', '실권자', 642, 665, '정변으로 권력을 잡아 당의 거듭된 침입을 막아냈으나 강경 일변도 외교와 독재로 고구려 말기의 고립을 심화시켰다.', '2026-10-14'),
('eulji-mundeok', '을지문덕', '한국', '삼국', '장군', 612, 612, '수 양제의 대군을 유인·기만 전술로 지치게 한 뒤 살수에서 섬멸해 고구려를 지켜 냈다.', '2026-10-14'),
('kim-yusin', '김유신', '한국', '삼국', '장군', 629, 673, '가야계 출신으로 신라의 대표 장군이 되어 내란 진압과 백제·고구려 정벌을 이끌며 삼국 통일에 핵심 역할을 했다.', '2026-10-14'),
('dae-joyeong', '대조영', '한국', '남북국', '군주', 698, 719, '고구려 유민과 말갈인을 이끌고 발해를 세워 고구려를 계승한 국가를 다시 일으켰다.', '2026-10-14'),
('sinmun', '신문왕', '한국', '남북국', '군주', 681, 692, '귀족 세력을 누르고 중앙·지방 제도를 정비해 통일신라의 전제 왕권 체제를 완성했다.', '2026-10-14'),
('taejo-wanggeon', '태조 왕건', '한국', '고려', '군주', 918, 943, '고려를 세우고 후삼국을 통일했으며 호족 포용과 북진 정책으로 새 왕조의 기틀을 닦았다.', '2026-10-14'),
('gwangjong', '광종', '한국', '고려', '군주', 949, 975, '노비안검법과 과거제로 호족 세력을 누르고 왕권을 크게 강화했으나 그 과정에서 대규모 숙청을 벌였다.', '2026-10-14'),
('seongjong-goryeo', '성종', '한국', '고려', '군주', 981, 997, '최승로의 시무 28조를 받아들여 유교 정치 이념에 따른 중앙·지방 통치 체제를 정비했다.', '2026-10-14'),
('hyeonjong-goryeo', '현종', '한국', '고려', '군주', 1009, 1031, '거란의 두 차례 침입을 견뎌 내고 지방 제도와 국가 기록을 정비해 고려 전기 체제를 안정시켰다.', '2026-10-14'),
('seohui', '서희', '한국', '고려', '관료', 972, 998, '거란 1차 침입 때 외교 담판으로 전쟁을 끝내고 오히려 강동 6주를 얻어 낸 외교가이다.', '2026-10-14'),
('gang-gamchan', '강감찬', '한국', '고려', '장군', 1010, 1031, '거란의 침입 때 항복론을 물리치고 귀주대첩을 승리로 이끌어 고려를 지켜 낸 명장이다.', '2026-10-14'),
('choe-chungheon', '최충헌', '한국', '고려', '실권자', 1196, 1219, '이의민을 제거하고 집권해 60여 년 이어지는 최씨 무신 정권을 세웠으며 왕을 마음대로 세우고 폐했다.', '2026-10-14'),
('gongmin', '공민왕', '한국', '고려', '군주', 1351, 1374, '원의 간섭에서 벗어나기 위한 반원 개혁과 권문세족 견제에 힘썼으나 외침과 말년의 혼란으로 개혁을 완수하지 못했다.', '2026-10-14'),
('taejo-joseon', '태조', '한국', '조선', '군주', 1392, 1398, '위화도 회군으로 실권을 잡고 조선을 건국해 한양을 도읍으로 정했다. 고려 왕족 처형과 세자 책봉 문제로 왕실 내 유혈 분쟁의 씨앗을 남겼다.', '2026-10-14'),
('jeong-dojeon', '정도전', '한국', '조선', '재상', 1392, 1398, '조선 건국을 설계하고 통치 체제와 도읍의 골격을 만든 개국 공신이다. 요동 정벌 추진으로 명과 긴장을 빚다가 제1차 왕자의 난 때 살해되었다.', '2026-10-14'),
('taejong-joseon', '태종', '한국', '조선', '군주', 1400, 1418, '왕자의 난으로 권력을 잡은 뒤 사병 혁파와 6조 직계제로 왕권을 강화해 조선의 통치 체제를 안정시켰다. 그 과정에서 정적과 외척을 가차 없이 제거했다.', '2026-10-14'),
('sejong', '세종', '한국', '조선', '군주', 1418, 1450, '훈민정음 창제와 과학·농업·국방의 성과로 조선 전기의 전성기를 이끌었다. 노비종모법 환원처럼 신분제를 강화한 조치도 있었다.', '2026-10-14'),
('sejo-joseon', '세조', '한국', '조선', '군주', 1455, 1468, '계유정난으로 권력을 빼앗고 조카 단종을 몰아내 즉위했으며 반대 세력을 대거 숙청했다. 재위 중 『경국대전』 편찬 착수와 군사·토지 제도 정비로 왕권을 강화했다.', '2026-10-14'),
('seongjong-joseon', '성종', '한국', '조선', '군주', 1469, 1494, '『경국대전』을 완성·반포하고 홍문관 설치와 각종 편찬 사업으로 유교적 통치 체제를 완성했다. 폐비 윤씨 사사는 훗날 갑자사화의 원인이 되었다.', '2026-10-14'),
('yeonsangun', '연산군', '한국', '조선', '군주', 1494, 1506, '두 차례 사화로 많은 관료와 선비를 죽이고 언론 기관과 경연을 없애 폭정을 펼쳤다. 결국 중종반정으로 폐위되어 왕자 신분인 군으로 강등되었다.', '2026-10-14'),
('jungjong-joseon', '중종', '한국', '조선', '군주', 1506, 1544, '반정으로 즉위해 조광조를 등용하며 개혁을 시도했으나 기묘사화로 스스로 개혁 세력을 꺾었다. 재위 내내 공신과 척신 세력에 휘둘렸다.', '2026-10-14'),
('seonjo-joseon', '선조', '한국', '조선', '군주', 1567, 1608, '이순신을 발탁하고 명의 원군을 끌어내 임진왜란에서 나라를 지켰지만 전쟁 대비에 소홀했고 전란 중 이순신을 하옥하는 실책을 저질렀다. 기축옥사로 많은 선비가 희생되었다.', '2026-10-14'),
('yi-sunsin', '이순신', '한국', '조선', '장군', 1591, 1598, '임진왜란과 정유재란에서 수군을 이끌고 연전연승해 일본군의 서해 진출을 막았다. 노량해전에서 전사할 때까지 나라를 지킨 대표적 명장이다.', '2026-10-14'),
('gwanghaegun', '광해군', '한국', '조선', '군주', 1608, 1623, '대동법 시행과 명·후금 사이 실리 외교로 전후 복구에 힘썼다. 그러나 영창대군 살해와 인목대비 유폐, 무리한 궁궐 공사로 반정을 맞아 폐위되었다.', '2026-10-14'),
('injo-joseon', '인조', '한국', '조선', '군주', 1623, 1649, '반정으로 광해군을 몰아내고 즉위했으나 친명배금 정책으로 두 차례 호란을 겪고 삼전도에서 청에 항복했다. 영정법 등 수취 제도 개편도 이루어졌다.', '2026-10-14'),
('hyojong-joseon', '효종', '한국', '조선', '군주', 1649, 1659, '북벌을 내세워 군비를 확충했으나 실행하지는 못했고 오히려 청의 요청으로 나선 정벌에 나섰다. 대동법 확대와 시헌력 채택 등 민생과 제도 정비에도 힘썼다.', '2026-10-14'),
('sukjong-joseon', '숙종', '한국', '조선', '군주', 1674, 1720, '대동법의 전국 확대와 상평통보 유통, 울릉도 영유권 확인 등 경제·국방 정비를 이루었다. 잦은 환국으로 붕당 간 보복과 숙청이 반복되었다.', '2026-10-14'),
('yeongjo-joseon', '영조', '한국', '조선', '군주', 1724, 1776, '탕평책과 균역법으로 정국을 안정시키고 백성의 부담을 덜어 조선 후기 중흥을 이끌었다. 아들 사도세자를 뒤주에 가두어 죽게 한 비극을 남겼다.', '2026-10-14'),
('jeongjo-joseon', '정조', '한국', '조선', '군주', 1776, 1800, '규장각 설치, 신해통공, 수원 화성 건설로 개혁 정치와 문화 부흥을 이끌었다. 천주교 탄압과 문체반정으로 사상 통제를 강화하기도 했다.', '2026-10-14'),
('heungseon-daewongun', '흥선대원군', '한국', '조선', '섭정', 1863, 1873, '세도 정치를 끊고 서원 철폐와 호포제 등으로 왕권과 국가 재정을 바로 세우려 했다. 경복궁 중건과 당백전 발행으로 민생을 어렵게 했고 천주교 박해와 통상 거부로 근대화 대응이 늦어졌다.', '2026-10-14'),
('gojong', '고종', '한국', '대한제국', '황제', 1863, 1907, '개항과 개화 정책, 대한제국 선포로 근대 국가 수립을 시도했으나 외세 의존과 전제권 강화로 국권 상실을 막지 못했다.', '2026-10-14'),
('sunjong', '순종', '한국', '대한제국', '황제', 1907, 1910, '일본의 강요로 즉위해 실권 없이 재위한 대한제국의 마지막 황제로, 재위 중 행정·군사·사법·경찰권이 차례로 넘어가고 국권을 잃었다.', '2026-10-14'),
('leewanyong', '이완용', '한국', '대한제국', '총리대신', 1905, 1910, '을사늑약 찬성과 한일병합조약 체결을 주도해 대한제국의 국권을 일본에 넘긴 핵심 인물이다.', '2026-10-14'),
('kimgu', '김구', '한국', '임시정부', '주석', 1940, 1947, '대한민국 임시정부를 이끌며 의열 투쟁과 한국광복군 창설로 무장 독립운동을 주도했다.', '2026-10-14'),
('leeseungman', '이승만', '한국', '대한민국', '대통령', 1948, 1960, '정부 수립과 농지개혁, 한미상호방위조약으로 국가의 기틀을 마련했으나 거듭된 개헌과 부정선거로 장기 집권을 꾀하다 4·19 혁명으로 물러났다.', '2026-10-14'),
('yunboseon', '윤보선', '한국', '대한민국', '대통령', 1960, 1962, '내각책임제 아래 국가원수를 지냈으며, 5·16 군사정변 이후 군정 아래 유임하다 사임하고 야당 지도자가 됐다.', '2026-10-14'),
('parkchunghee', '박정희', '한국', '대한민국', '대통령', 1963, 1979, '군사정변으로 집권해 경제개발계획과 중화학공업화로 고도성장을 이끌었으나 3선 개헌과 유신체제로 헌정을 훼손하고 인권을 탄압했다.', '2026-10-14'),
('choikyuhah', '최규하', '한국', '대한민국', '대통령', 1979, 1980, '10·26 사건 이후 대통령이 되어 긴급조치 해제 등을 시행했으나 신군부의 권력 장악을 막지 못하고 8개월 만에 물러났다.', '2026-10-14'),
('chundoohwan', '전두환', '한국', '대한민국', '대통령', 1980, 1988, '군사반란과 광주 유혈 진압으로 집권해 인권과 언론을 탄압했으며, 재임 중 물가 안정을 이루었으나 반란·내란·뇌물죄로 유죄가 확정됐다.', '2026-10-14'),
('rohtaewoo', '노태우', '한국', '대한민국', '대통령', 1988, 1993, '군사반란에 가담한 뒤 직선제로 당선되어 북방정책으로 소련·중국과 수교했으나 반란·내란·뇌물죄로 유죄가 확정됐다.', '2026-10-14'),
('kimyoungsam', '김영삼', '한국', '대한민국', '대통령', 1993, 1998, '하나회 해체와 금융실명제, 지방자치 전면 실시 등 제도 개혁을 단행했으나 임기 말 외환위기를 맞았다.', '2026-10-14'),
('kimdaejung', '김대중', '한국', '대한민국', '대통령', 1998, 2003, '외환위기 극복과 복지 제도 정비, 첫 남북정상회담을 이끌었으나 대북 송금 과정의 불법과 친인척 비리가 드러났다.', '2026-10-14'),
('rohmoohyun', '노무현', '한국', '대한민국', '대통령', 2003, 2008, '국가균형발전 정책과 과거사 정리, 한미 FTA 타결을 추진했으며, 측근의 불법 정치자금 수수가 드러났고 선거 중립 의무 위반 등으로 탄핵소추됐으나 헌법재판소에서 기각됐다.', '2026-10-14'),
('qin-shi-huang', '진시황', '중국', '진', '황제', -246, -210, '전국시대를 끝내고 최초의 통일 제국과 중앙집권 체제를 세웠다. 그러나 사상 탄압과 가혹한 노역으로 백성에게 큰 고통을 주었다.', '2026-10-14'),
('emperor-wu-han', '한 무제', '중국', '한', '황제', -141, -87, '유학을 국가 이념으로 삼고 서역 교류를 열어 한의 전성기를 이끌었다. 끊임없는 정복 전쟁과 말년의 숙청으로 백성과 주변 민족에게 큰 부담을 안겼다.', '2026-10-14'),
('taizong-tang', '태종 이세민', '중국', '당', '황제', 626, 649, '형제를 죽이고 즉위했으나 ''정관의 치''로 불리는 안정된 통치와 대외 팽창으로 당의 기틀을 다졌다. 고구려 침공은 실패로 끝나 양국에 큰 희생을 남겼다.', '2026-10-14'),
('wu-zetian', '측천무후', '중국', '당', '황제', 690, 705, '중국 역사상 유일한 여성 황제로 과거제를 넓혀 인재 등용의 폭을 키웠다. 그러나 밀고와 혹리를 이용한 공포 정치로 많은 사람을 희생시켰다.', '2026-10-14'),
('kublai-khan', '쿠빌라이 칸', '중국', '원', '칸', 1260, 1294, '남송을 멸해 중국을 재통일하고 대도와 운하를 정비해 원의 체제를 세웠다. 고려를 동원한 두 차례 일본 원정은 실패로 끝나 큰 희생을 남겼다.', '2026-10-14'),
('hongwu-emperor', '홍무제', '중국', '명', '황제', 1368, 1398, '농민 출신으로 원을 몰아내고 명을 세워 호적·토지·법률 제도를 정비했다. 그러나 대규모 옥사로 수만 명을 죽이고 황제 독재를 강화했다.', '2026-10-14'),
('yongle-emperor', '영락제', '중국', '명', '황제', 1402, 1424, '조카의 제위를 빼앗아 즉위했으나 정화의 원정과 영락대전 편찬, 베이징 천도로 명의 국력을 크게 떨쳤다. 즉위 과정의 학살과 베트남 침공, 환관 정치 강화라는 과오를 남겼다.', '2026-10-14'),
('kangxi-emperor', '강희제', '중국', '청', '황제', 1661, 1722, '삼번의 난을 진압하고 대만을 편입해 청의 통치를 안정시켰으며 감세와 문화 사업으로 ''강건성세''를 열었다. 말년에는 문자옥으로 지식인을 탄압하기도 했다.', '2026-10-14'),
('qianlong-emperor', '건륭제', '중국', '청', '황제', 1735, 1796, '청의 영토를 최대로 넓히고 사고전서를 편찬했으나 준가르 학살과 사상 통제, 말년의 부패와 쇄국으로 쇠퇴의 씨앗을 남겼다.', '2026-10-14'),
('empress-dowager-cixi', '서태후', '중국', '청', '실권자', 1861, 1908, '약 반세기 동안 청 조정의 실권을 쥐었으나 개혁을 좌절시키고 의화단을 지지해 나라를 큰 위기에 빠뜨렸다. 말년에야 과거제 폐지 등 신정 개혁을 추진했다.', '2026-10-14'),
('sun-yat-sen', '쑨원', '중국', '중화민국', '대통령', 1912, 1912, '삼민주의를 내걸고 혁명 운동을 이끌어 아시아 최초의 공화국인 중화민국의 임시대총통이 되었다. 중국 근대 국가 형성의 사상적 토대를 놓았다.', '2026-10-14'),
('chiang-kai-shek', '장제스', '중국', '중화민국', '총통', 1928, 1975, '북벌로 중국을 통일하고 항일 전쟁을 이끌었으며 한국 독립을 지원했다. 그러나 공산당 숙청과 황허 제방 파괴, 대만의 계엄 통치로 많은 희생을 낳았다.', '2026-10-14'),
('mao-zedong', '마오쩌둥', '중국', '중화인민공화국', '주석', 1949, 1976, '내전을 끝내고 중화인민공화국을 세웠으나 대약진운동과 문화대혁명으로 수천만 명의 희생을 초래했다. 한국전쟁 참전으로 한반도 분단의 고착에도 큰 영향을 미쳤다.', '2026-10-14'),
('deng-xiaoping', '덩샤오핑', '중국', '중화인민공화국', '실권자', 1978, 1992, '개혁개방으로 중국 경제를 시장 경제로 전환해 수억 명을 빈곤에서 벗어나게 했다. 그러나 톈안먼 시위 무력 진압과 강압적인 한 자녀 정책이라는 과오를 남겼다.', '2026-10-14'),
('prince-shotoku', '쇼토쿠 태자', '일본', '아스카', '섭정', 593, 622, '스이코 천황의 섭정으로 관료 제도와 성문 규범을 정비하고 수와 교류했다. 불교를 진흥해 일본 고대 국가와 문화의 기틀을 마련했다.', '2026-10-14'),
('oda-nobunaga', '오다 노부나가', '일본', '센고쿠', '실권자', 1568, 1582, '무로마치 막부를 무너뜨리고 전국 통일의 기반을 닦았으며 자유 상업 정책으로 경제를 활성화했다. 그러나 사찰과 종교 세력을 상대로 대규모 학살을 저질렀다.', '2026-10-14'),
('toyotomi-hideyoshi', '도요토미 히데요시', '일본', '센고쿠', '실권자', 1582, 1598, '전국시대를 끝내고 일본을 통일했으며 토지 조사와 신분 정리로 근세 사회의 틀을 만들었다. 그러나 두 차례 조선 침략으로 조선 백성에게 막대한 피해를 입혔다.', '2026-10-14'),
('tokugawa-ieyasu', '도쿠가와 이에야스', '일본', '에도', '쇼군', 1603, 1616, '세키가하라 전투로 패권을 잡고 에도 막부를 세워 260여 년의 평화를 열었다. 조선과 국교를 회복했으나 기독교 금지와 류큐 침공 승인이라는 과오도 있었다.', '2026-10-14'),
('emperor-meiji', '메이지 천황', '일본', '메이지', '천황', 1867, 1912, '메이지 유신으로 일본을 근대 국가로 바꾸는 개혁을 이끌었다. 그러나 그 국력을 바탕으로 류큐를 병합하고 조선을 침략해 식민지로 만들었다.', '2026-10-14'),
('ito-hirobumi', '이토 히로부미', '일본', '메이지', '총리', 1885, 1909, '초대 총리로 일본의 내각 제도와 정당 정치의 기초를 놓았다. 한국 침략을 주도해 을사늑약을 강요하고 초대 통감으로 국권 침탈을 이끌었다.', '2026-10-14'),
('hirohito', '쇼와 천황 히로히토', '일본', '쇼와', '천황', 1926, 1989, '일본 제국의 주권자로서 중일전쟁과 태평양전쟁, 전시 총동원을 재가해 아시아 각국에 막대한 피해를 입혔다. 패전 시 항복을 결정했고 전후에는 상징 천황이 되었다.', '2026-10-14'),
('tojo-hideki', '도조 히데키', '일본', '쇼와', '총리', 1941, 1944, '육군대신과 총리로서 태평양전쟁을 일으키고 이끌어 아시아·태평양 전역에 막대한 희생을 낳았다. 전후 A급 전범으로 처형되었다.', '2026-10-14'),
('george-washington', '조지 워싱턴', '미국', '', '대통령', 1789, 1797, '독립전쟁을 승리로 이끌고 초대 대통령으로 연방 정부의 틀과 평화적 권력 이양의 전통을 세웠다. 반면 노예를 소유했고 도망노예법에 서명했으며 원주민 마을 파괴 작전을 명령했다.', '2026-10-14'),
('thomas-jefferson', '토머스 제퍼슨', '미국', '', '대통령', 1801, 1809, '독립선언서를 쓰고 루이지애나 매입으로 국토를 두 배로 넓혔다. 평생 수백 명의 노예를 소유했고 출항금지법으로 경제에 큰 타격을 주었다.', '2026-10-14'),
('abraham-lincoln', '에이브러햄 링컨', '미국', '', '대통령', 1861, 1865, '남북전쟁에서 연방을 지키고 노예제 폐지를 이끌었다. 전시에 인신보호영장을 정지했고 다코타족 38명의 집단 처형을 승인했다.', '2026-10-14'),
('theodore-roosevelt', '시어도어 루스벨트', '미국', '', '대통령', 1901, 1909, '독점 규제와 소비자 보호, 자연 보존으로 혁신주의 개혁을 이끌었다. 대외적으로는 파나마 분리에 개입하고 가쓰라-태프트 밀약으로 일본의 한국 지배를 인정했다.', '2026-10-14'),
('franklin-roosevelt', '프랭클린 D. 루스벨트', '미국', '', '대통령', 1933, 1945, '뉴딜과 사회보장 제도로 대공황을 헤쳐 나가고 제2차 세계대전에서 연합국 승리를 이끌었다. 일본계 미국인 약 12만 명을 강제 수용한 것은 큰 과오다.', '2026-10-14'),
('harry-truman', '해리 S. 트루먼', '미국', '', '대통령', 1945, 1953, '마셜 플랜과 6·25 전쟁 참전으로 전후 질서와 한국의 존립에 큰 영향을 남겼다. 원자폭탄 투하로 수많은 민간인이 희생되었고 38선 분할 점령을 제안했다.', '2026-10-14'),
('john-f-kennedy', '존 F. 케네디', '미국', '', '대통령', 1961, 1963, '쿠바 미사일 위기를 평화적으로 풀고 핵실험 금지 조약과 아폴로 계획을 남겼다. 피그스만 침공 실패와 베트남 개입 확대는 과오로 꼽힌다.', '2026-10-14'),
('richard-nixon', '리처드 닉슨', '미국', '', '대통령', 1969, 1974, '중국과의 관계 개선과 군비 통제, 환경보호청 설립을 이루었다. 캄보디아 비밀 폭격과 워터게이트 은폐로 큰 피해와 불신을 남기고 사임했다.', '2026-10-14'),
('ronald-reagan', '로널드 레이건', '미국', '', '대통령', 1981, 1989, '소련과 중거리핵전력 조약을 맺어 냉전 종식에 기여하고 GPS 민간 개방을 결정했다. 니카라과 콘트라 반군 지원과 이란-콘트라 사건은 과오로 남았다.', '2026-10-14'),
('alexander-the-great', '알렉산드로스 대왕', '유럽', '마케도니아', '군주', -336, -323, '페르시아 제국을 정복해 그리스에서 인도에 이르는 제국을 세우고 헬레니즘 시대를 열었다. 정복 과정에서 테베와 티레의 주민을 학살·노예화했고 사후 제국은 곧 분열되었다.', '2026-10-14'),
('julius-caesar', '율리우스 카이사르', '유럽', '로마', '실권자', -49, -44, '갈리아를 정복하고 내전에서 승리해 로마의 최고 권력자가 되었으며 율리우스력을 도입했다. 갈리아 전쟁의 막대한 인명 피해와 공화정 붕괴를 이끈 책임이 크다.', '2026-10-14'),
('augustus', '아우구스투스', '유럽', '로마', '황제', -27, 14, '100년 가까운 내전을 끝내고 원수정을 세워 약 200년간의 로마의 평화를 열었다. 집권 과정에서 살생부를 통한 대규모 숙청을 벌였다.', '2026-10-14'),
('charlemagne', '카롤루스 대제', '유럽', '프랑크', '황제', 768, 814, '서유럽 대부분을 통일하고 서로마 황제로 즉위했으며 카롤링거 르네상스로 학문을 되살렸다. 작센 정복 과정에서 강제 개종과 대량 처형을 벌였다.', '2026-10-14'),
('elizabeth-i', '엘리자베스 1세', '유럽', '영국', '군주', 1558, 1603, '종교 갈등을 수습하고 스페인 무적함대를 물리쳐 잉글랜드의 안정과 해양 진출의 기반을 마련했다. 노예무역에 투자했고 아일랜드 반란을 초토화 작전으로 진압했다.', '2026-10-14'),
('louis-xiv', '루이 14세', '유럽', '프랑스', '군주', 1643, 1715, '절대왕정을 완성하고 학문·산업 육성으로 프랑스를 유럽 최강국으로 만들었다. 낭트 칙령 폐지와 흑인법, 잇단 전쟁으로 큰 인명 피해와 재정 파탄을 남겼다.', '2026-10-14'),
('frederick-the-great', '프리드리히 대왕', '유럽', '프로이센', '군주', 1740, 1786, '계몽 군주로서 고문 폐지와 의무교육 등 개혁을 펼치고 프로이센을 강대국으로 키웠다. 슐레지엔 침공과 7년 전쟁, 폴란드 분할로 큰 전쟁 피해와 타국 영토 병합을 일으켰다.', '2026-10-14'),
('napoleon', '나폴레옹', '유럽', '프랑스', '황제', 1799, 1815, '나폴레옹 법전과 근대 행정·교육 제도로 프랑스와 유럽에 오래 남는 유산을 남겼다. 노예제 부활과 끝없는 정복 전쟁으로 수백만 명의 희생을 낳았다.', '2026-10-14'),
('queen-victoria', '빅토리아 여왕', '유럽', '영국', '군주', 1837, 1901, '입헌군주로서 대영제국의 전성기를 상징했으며, 재위 중 정부의 개혁 입법과 함께 아편전쟁·식민지 기근·강제수용 같은 제국주의의 과오가 이어졌다. 결정 대부분이 내각의 것이어서 점수를 낮게 매겼다.', '2026-10-14'),
('otto-von-bismarck', '오토 폰 비스마르크', '유럽', '독일', '총리', 1862, 1890, '세 차례 전쟁으로 독일을 통일하고 세계 최초의 사회보험을 도입했다. 의회를 무시한 통치와 가톨릭·사회주의 탄압, 아프리카 분할 회의 주도는 과오다.', '2026-10-14'),
('winston-churchill', '윈스턴 처칠', '유럽', '영국', '총리', 1940, 1955, '제2차 세계대전에서 나치 독일에 굴복하지 않고 영국의 항전을 이끌었다. 벵골 대기근 대응과 케냐·이란 등 식민지·약소국 정책에서 큰 피해를 남겼다.', '2026-10-14'),
('adolf-hitler', '아돌프 히틀러', '유럽', '독일', '총통', 1933, 1945, '나치 독재를 세우고 제2차 세계대전을 일으켜 수천만 명의 죽음을 불렀으며 홀로코스트로 유대인 약 600만 명을 학살했다.', '2026-10-14'),
('benito-mussolini', '베니토 무솔리니', '유럽', '이탈리아', '총리', 1922, 1943, '파시즘 독재를 세우고 리비아·에티오피아에서 잔혹한 식민 전쟁을 벌였으며 이탈리아를 제2차 세계대전 패전으로 이끌었다. 라테란 조약과 습지 간척 같은 성과도 있었다.', '2026-10-14'),
('charles-de-gaulle', '샤를 드골', '유럽', '프랑스', '대통령', 1959, 1969, '자유프랑스를 이끌어 나치에 맞섰고 제5공화국을 세우며 알제리 독립을 인정했다. 세티프 학살과 1961년 파리 학살 등 알제리인에 대한 탄압이 그의 집권기에 일어났다.', '2026-10-14'),
('peter-the-great', '표트르 대제', '러시아', '러시아 제국', '황제', 1682, 1725, '서유럽식 개혁과 발트해 진출로 러시아를 유럽의 강대국으로 끌어올렸다. 그 과정에서 가혹한 처형과 농민에 대한 수탈이 뒤따랐다.', '2026-10-14'),
('catherine-ii', '예카테리나 2세', '러시아', '러시아 제국', '황제', 1762, 1796, '계몽사상을 표방하며 영토를 크게 넓히고 행정을 정비했다. 그러나 귀족 특권을 강화해 농노의 처지는 더 나빠졌고 폴란드 분할에 앞장섰다.', '2026-10-14'),
('lenin', '블라디미르 레닌', '러시아', '소련', '실권자', 1917, 1924, '10월 혁명으로 볼셰비키 정권을 세우고 소련의 기틀을 놓았다. 집권 과정에서 의회를 해산하고 적색 테러와 전시공산주의로 막대한 희생을 낳았다.', '2026-10-14'),
('stalin', '이오시프 스탈린', '러시아', '소련', '실권자', 1924, 1953, '강압적 공업화로 소련을 공업 강국으로 만들고 독소전쟁에서 승리했다. 그러나 집단화·대숙청·강제 이주로 수백만 명이 목숨을 잃었다.', '2026-10-14'),
('gorbachev', '미하일 고르바초프', '러시아', '소련', '대통령', 1985, 1991, '개방과 개혁으로 소련 사회를 자유화하고 냉전을 평화적으로 끝내는 데 기여했다. 경제 개혁은 실패했고 일부 민족 분쟁에는 무력으로 대응했다.', '2026-10-14'),
('ramesses-ii', '람세스 2세', '기타', '이집트', '파라오', -1279, -1213, '60년 넘게 재위하며 대규모 신전을 남기고 히타이트와 평화조약을 맺었다. 카데시 전투에서는 목표를 이루지 못했다.', '2026-10-14'),
('ashoka', '아소카', '기타', '인도', '군주', -268, -232, '칼링가 정복의 참상을 겪은 뒤 불교에 귀의해 비폭력과 관용의 통치를 펼쳤다. 불교를 아시아 각지로 전파하는 데 결정적 역할을 했다.', '2026-10-14'),
('genghis-khan', '칭기즈 칸', '기타', '몽골', '칸', 1206, 1227, '흩어진 몽골 부족을 통일하고 유라시아에 걸친 대제국의 기초를 세웠다. 정복 과정에서 여러 도시를 파괴하고 대규모 학살을 저질렀다.', '2026-10-14'),
('suleiman-i', '쉴레이만 1세', '기타', '오스만', '술탄', 1520, 1566, '오스만 제국의 최대 전성기를 이끌며 영토를 넓히고 법과 건축을 발전시켰다. 빈 포위에 실패했고 후계 다툼 속에 장남을 처형했다.', '2026-10-14'),
('ataturk', '무스타파 케말 아타튀르크', '기타', '튀르키예', '대통령', 1923, 1938, '독립전쟁을 이끌어 튀르키예 공화국을 세우고 세속화·근대화 개혁을 추진했다. 반대 세력과 쿠르드인 봉기는 강압적으로 진압했다.', '2026-10-14'),
('mandela', '넬슨 만델라', '기타', '남아프리카공화국', '대통령', 1994, 1999, '27년의 수감 끝에 석방되어 아파르트헤이트를 협상으로 끝내고 첫 흑인 대통령이 되었다. 보복 대신 화해를 택해 다인종 민주주의의 기틀을 세웠다.', '2026-10-14')
insert into events (id, leader_id, year, title, description, score, reason) values
('geunchogo-1', 'geunchogo', 369, '치양 전투 승리', '고구려 고국원왕이 2만 군사로 침입하자 태자 근구수를 보내 치양에서 격파했다.', 3, '고구려의 남진을 막아 백제의 북쪽 국경을 안정시켰다.'),
('geunchogo-2', 'geunchogo', 369, '마한 잔여 세력 정복', '남쪽으로 진출해 마한의 잔여 세력을 복속하고 남해안까지 영역을 넓혔다.', 6, '백제가 한반도 서남부 전체를 아우르는 국가로 성장하는 기반이 됐다.'),
('geunchogo-3', 'geunchogo', 371, '평양성 공격', '고구려 평양성을 공격해 고국원왕을 전사시키고 황해도 일대까지 진출했다.', 5, '백제의 영토가 최대로 넓어졌으나 고구려와의 오랜 적대 관계가 시작됐다.'),
('geunchogo-4', 'geunchogo', 372, '동진과 외교 수립', '중국 동진에 사신을 보내 국교를 맺고 책봉을 받았다.', 3, '중국 남조와의 교류 통로를 열어 선진 문물 수용의 기반을 마련했다.'),
('geunchogo-5', 'geunchogo', 375, '역사서 『서기』 편찬', '박사 고흥이 백제의 역사서 『서기』를 편찬했다.', 4, '국가 차원의 역사 기록을 시작해 왕권과 국가 체제의 정비를 보여 줬다.'),
('gwanggaeto-1', 'gwanggaeto', 391, '영락 연호 사용', '즉위 후 ''영락''이라는 독자적인 연호를 사용했다.', 3, '중국과 대등한 국가라는 자주 의식을 대내외에 드러냈다.'),
('gwanggaeto-2', 'gwanggaeto', 395, '비려(거란) 정벌', '서북쪽의 비려를 정벌해 많은 가축과 주민을 얻었다.', 3, '서북 변경을 안정시키고 국력을 키웠다.'),
('gwanggaeto-3', 'gwanggaeto', 396, '백제 공격', '백제를 공격해 58성 700촌을 차지하고 아신왕의 항복을 받았다.', 6, '한강 이북까지 영토를 넓혀 삼국 간 세력 균형을 고구려 우위로 바꿨다.'),
('gwanggaeto-4', 'gwanggaeto', 400, '신라 구원과 왜 격퇴', '5만 군사를 보내 신라에 침입한 왜를 물리치고 가야 지역까지 추격했다.', 5, '한반도 남부에 고구려의 영향력을 확대했고 금관가야가 쇠퇴하는 계기가 됐다.'),
('gwanggaeto-5', 'gwanggaeto', 410, '동부여 정벌', '동부여를 정벌해 복속시켰다.', 3, '동북 방면의 영역을 넓히고 고구려의 지배권을 굳혔다.'),
('jangsu-1', 'jangsu', 414, '광개토대왕릉비 건립', '부왕 광개토대왕의 업적을 기록한 비석을 국내성 부근에 세웠다.', 4, '고구려사 연구의 핵심 사료가 되는 기록을 남겼다.'),
('jangsu-2', 'jangsu', 427, '평양 천도', '도읍을 국내성에서 평양으로 옮겼다.', 7, '남진 정책의 거점을 마련하고 귀족 세력을 재편해 왕권을 강화했다.'),
('jangsu-3', 'jangsu', 435, '북위와 외교 관계 수립', '북위에 사신을 보내 국교를 맺고 남조와도 교류하는 양면 외교를 펼쳤다.', 3, '중국 남북조 사이에서 균형을 유지해 서쪽 국경의 안정을 확보했다.'),
('jangsu-4', 'jangsu', 475, '한성 함락', '백제 수도 한성을 함락하고 개로왕을 죽여 한강 유역을 차지했다.', 6, '고구려의 영토가 최대에 이르렀고 백제는 웅진으로 천도해야 했다.'),
('jangsu-5', 'jangsu', 481, '신라 공격 실패', '신라 북쪽 7성을 빼앗고 미질부까지 진격했으나 신라·백제·가야 연합군에 밀려 물러났다.', -2, '나제동맹의 결속을 확인시켜 남진이 더 나아가지 못했다.'),
('jinheung-1', 'jinheung', 545, '『국사』 편찬', '거칠부에게 명해 신라의 역사서 『국사』를 편찬하게 했다.', 4, '왕실의 권위를 높이고 국가 체제 정비를 뒷받침했다.'),
('jinheung-2', 'jinheung', 551, '한강 상류 차지', '백제와 함께 고구려를 공격해 한강 상류의 10군을 차지했다.', 5, '신라가 처음으로 한강 유역에 진출했다.'),
('jinheung-3', 'jinheung', 553, '한강 하류 점령과 신주 설치', '백제가 되찾은 한강 하류를 빼앗고 신주를 설치했다.', 6, '중국과 직접 통하는 서해 항로를 확보했으나 나제동맹이 깨져 백제와 오랜 전쟁이 시작됐다.'),
('jinheung-4', 'jinheung', 554, '관산성 전투 승리', '관산성에서 백제군을 격파하고 백제 성왕을 전사시켰다.', 4, '한강 유역 지배를 확정하고 백제의 반격을 꺾었다.'),
('jinheung-5', 'jinheung', 562, '대가야 정복', '이사부와 사다함을 보내 대가야를 정복했다.', 6, '낙동강 서쪽까지 영역을 넓혀 가야 지역 전체를 신라에 편입했다.'),
('jinheung-6', 'jinheung', 568, '황초령·마운령 순수비 건립', '함경도 지역까지 진출해 황초령과 마운령에 순수비를 세웠다.', 3, '동북 방면으로 영토를 넓혔음을 기록으로 남겼다.'),
('jinheung-7', 'jinheung', 576, '화랑도 개편', '원화를 폐지하고 화랑 제도를 국가 조직으로 정비했다.', 5, '인재 양성과 결속의 기반이 되어 이후 통일 전쟁의 인물들을 길러냈다.'),
('uija-1', 'uija', 642, '신라 서부 공략', '직접 신라의 40여 성을 함락하고 장군 윤충을 보내 대야성을 빼앗았다.', 5, '신라의 서쪽 방어선을 크게 무너뜨리고 낙동강 방면까지 압박했다.'),
('uija-2', 'uija', 655, '신라 북쪽 33성 공격', '고구려·말갈과 함께 신라 북쪽 국경의 33성을 공격해 빼앗았다.', 2, '일시적으로 신라를 압박했으나 신라가 당에 원병을 요청하는 계기가 됐다.'),
('uija-3', 'uija', 656, '성충 투옥', '국정 문란을 간언한 좌평 성충을 옥에 가두었고 성충은 옥중에서 죽었다.', -4, '충언하는 신하를 배제해 국정 판단과 방어 준비가 약해졌다.'),
('uija-4', 'uija', 657, '서자 41명 좌평 임명', '왕의 서자 41명을 좌평으로 임명하고 식읍을 내렸다.', -3, '관직 질서를 흐트러뜨리고 귀족층의 이반을 불렀다.'),
('uija-5', 'uija', 660, '백제 멸망', '나당 연합군의 침공으로 사비성이 함락되자 웅진성에서 항복했다.', -9, '약 700년 이어진 백제가 멸망하고 많은 백성과 왕족이 당으로 끌려갔다.'),
('muyeol-1', 'muyeol', 642, '고구려 청병 실패', '백제를 막기 위해 고구려에 군사 지원을 요청했으나 거절당하고 억류되었다가 돌아왔다.', -1, '외교적 성과 없이 고구려와 신라의 대립만 확인됐다.'),
('muyeol-2', 'muyeol', 648, '나당 동맹 체결', '당에 건너가 태종과 백제·고구려 공격을 위한 군사 동맹을 맺었다.', 6, '통일 전쟁의 결정적 기반이 됐으나 이후 당의 한반도 개입을 부르는 결과도 낳았다.'),
('muyeol-3', 'muyeol', 649, '당 의관 제도 도입', '김춘추의 건의로 신라 관리들이 당의 의관을 입게 됐다.', 2, '당과의 관계를 강화하고 제도 정비의 계기가 됐다.'),
('muyeol-4', 'muyeol', 654, '율령 정비', '즉위 후 이방부격 60여 조를 손질해 법령을 정비했다.', 3, '왕권 중심의 통치 체제를 다지는 데 기여했다.'),
('muyeol-5', 'muyeol', 660, '백제 정복', '당군과 연합해 사비성을 함락하고 백제를 멸망시켰다.', 7, '신라가 삼국 통일로 나아가는 결정적 전환점이 됐다.'),
('munmu-1', 'munmu', 668, '고구려 정복', '당군과 함께 평양성을 함락해 고구려를 멸망시켰다.', 6, '삼국 통일의 큰 고비를 넘겼으나 고구려 옛 땅의 상당 부분은 당의 지배 아래 놓였다.'),
('munmu-2', 'munmu', 670, '고구려 부흥 세력 지원', '고구려 왕족 안승을 고구려왕으로 책봉하고 부흥 세력을 지원했다.', 3, '고구려 유민을 끌어들여 당에 맞서는 힘을 키웠다.'),
('munmu-3', 'munmu', 675, '매소성 전투 승리', '매소성에서 당의 대군을 격파했다.', 6, '나당 전쟁의 판세를 신라 쪽으로 돌려놓았다.'),
('munmu-4', 'munmu', 676, '기벌포 전투와 삼국 통일 완성', '기벌포에서 당 수군을 격파해 당 세력을 한반도에서 몰아냈다.', 8, '대동강 이남을 하나의 국가로 통합해 이후 민족 문화 형성의 토대를 마련했다.'),
('munmu-5', 'munmu', 681, '대왕암 수중릉 유언', '죽어서 동해의 용이 되어 나라를 지키겠다며 화장 후 동해에 장사 지내라는 유언을 남겼다.', 2, '검소한 장례와 호국 의지를 보여 준 상징적 행위였다.'),
('yeon-gaesomun-1', 'yeon-gaesomun', 642, '정변으로 권력 장악', '영류왕과 대신 100여 명을 죽이고 보장왕을 세운 뒤 대막리지가 되었다.', -6, '대규모 살육으로 집권해 귀족 사회를 분열시키고 독재 체제를 만들었다.'),
('yeon-gaesomun-2', 'yeon-gaesomun', 642, '김춘추의 청병 거절', '신라 김춘추의 군사 지원 요청에 죽령 이북 땅 반환을 요구하며 거절했다.', -3, '신라가 당과 동맹을 맺는 방향으로 기우는 계기가 됐다.'),
('yeon-gaesomun-3', 'yeon-gaesomun', 643, '도교 도입', '당에 요청해 도사와 『도덕경』을 들여오고 도교를 장려했다.', -2, '불교계의 반발을 불러 승려 보덕이 백제로 망명하는 등 내부 분열을 낳았다.'),
('yeon-gaesomun-4', 'yeon-gaesomun', 645, '당 태종의 침입 격퇴', '당 태종의 대규모 침입을 요동 방어선과 안시성 항전으로 막아냈다.', 6, '국가의 존립을 지켜 내고 당의 동방 팽창을 저지했다.'),
('yeon-gaesomun-5', 'yeon-gaesomun', 662, '사수 전투 승리', '사수에서 방효태가 이끄는 당군을 전멸시켰다.', 5, '평양을 노리던 당군의 공세를 꺾었다.'),
('eulji-mundeok-1', 'eulji-mundeok', 612, '적진 거짓 항복', '수군 진영에 거짓으로 항복하러 가서 적의 군량 부족과 사정을 살피고 돌아왔다.', 2, '적의 약점을 파악해 이후 작전의 근거를 마련했다.'),
('eulji-mundeok-2', 'eulji-mundeok', 612, '우중문에게 시를 보냄', '수의 장수 우중문에게 그만 돌아가라는 뜻의 오언시를 보냈다.', 1, '적장의 심리를 흔들어 철수를 유도했다.'),
('eulji-mundeok-3', 'eulji-mundeok', 612, '살수대첩', '거듭 지는 척 수군을 평양 근처까지 끌어들인 뒤, 철수하는 별동대를 살수에서 공격해 30만여 명 중 2,700명만 살아 돌아가게 했다.', 9, '고구려를 멸망 위기에서 구하고 수가 쇠망하는 큰 원인이 됐다.'),
('kim-yusin-1', 'kim-yusin', 629, '낭비성 전투 승리', '고구려 낭비성 공격에서 앞장서 싸워 승리를 이끌었다.', 3, '장수로서 이름을 떨치며 신라 군사력의 중심 인물로 떠올랐다.'),
('kim-yusin-2', 'kim-yusin', 647, '비담의 난 진압', '상대등 비담 등이 일으킨 반란을 진압했다.', 5, '왕실을 지키고 김춘추와 함께 정권의 중심을 장악했다.'),
('kim-yusin-3', 'kim-yusin', 648, '대야성 방면 반격', '백제를 공격해 장수 8명을 사로잡고 대야성에서 죽은 김품석 부부의 유해를 돌려받았다.', 3, '대야성 함락 이후 무너졌던 서부 전선을 회복했다.'),
('kim-yusin-4', 'kim-yusin', 660, '황산벌 전투 승리', '5만 군을 이끌고 황산벌에서 계백의 결사대를 격파했다.', 6, '사비성 함락과 백제 멸망으로 이어지는 결정적 승리였다.'),
('kim-yusin-5', 'kim-yusin', 662, '평양 당군에 군량 수송', '혹한 속에 평양을 포위한 당군에게 군량을 운반해 전달했다.', 3, '나당 연합을 유지하며 고구려 정벌 작전을 뒷받침했다.'),
('dae-joyeong-1', 'dae-joyeong', 698, '천문령 전투 승리', '추격해 온 당군을 천문령에서 크게 격파했다.', 6, '당의 추격을 끊고 독자 세력을 세울 수 있는 기반을 확보했다.'),
('dae-joyeong-2', 'dae-joyeong', 698, '발해 건국', '동모산에서 나라를 세우고 국호를 진이라 했다.', 9, '고구려 계승 국가를 세워 이후 200여 년간 만주와 한반도 북부를 아우르는 남북국 시대를 열었다.'),
('dae-joyeong-3', 'dae-joyeong', 705, '당과 관계 개선', '당이 사신을 보내오자 아들을 당에 보내 관계를 회복했다.', 3, '건국 초기 국가의 안정을 확보했다.'),
('dae-joyeong-4', 'dae-joyeong', 713, '발해군왕 책봉', '당으로부터 발해군왕으로 책봉되고 이후 국호를 발해로 삼았다.', 4, '국제적으로 국가의 지위를 인정받았다.'),
('sinmun-1', 'sinmun', 681, '김흠돌의 난 진압', '장인 김흠돌이 일으킨 반란을 진압하고 연루된 귀족들을 숙청했다.', 3, '왕권을 강화했으나 많은 진골 귀족이 처형되는 숙청을 동반했다.'),
('sinmun-2', 'sinmun', 682, '국학 설립', '유학 교육 기관인 국학을 세웠다.', 6, '유교 이념에 기반한 관리 양성 체계를 처음 마련했다.'),
('sinmun-3', 'sinmun', 685, '9주 5소경 완비', '전국을 9주로 나누고 5소경을 두어 지방 행정 체제를 완성했다.', 7, '통일 이후 넓어진 영토를 체계적으로 다스리는 틀을 만들었다.'),
('sinmun-4', 'sinmun', 687, '관료전 지급', '관리들에게 조세만 거두는 관료전을 지급했다.', 5, '귀족의 경제 기반을 약화하고 관료 중심 체제로 옮겨 가는 토대가 됐다.'),
('sinmun-5', 'sinmun', 689, '녹읍 폐지', '귀족이 토지와 백성을 함께 지배하던 녹읍을 폐지했다.', 5, '귀족의 사적 지배를 줄여 왕권을 강화했다.'),
('sinmun-6', 'sinmun', 689, '달구벌 천도 시도 무산', '도읍을 달구벌로 옮기려 했으나 이루지 못했다.', -1, '경주 귀족의 반발을 넘지 못해 수도가 동남쪽에 치우친 한계가 계속됐다.'),
('taejo-wanggeon-1', 'taejo-wanggeon', 918, '고려 건국', '궁예를 몰아내고 왕위에 올라 국호를 고려라 했다.', 8, '이후 470여 년 이어지는 왕조를 열었다.'),
('taejo-wanggeon-2', 'taejo-wanggeon', 927, '공산 전투 패배', '공산에서 견훤의 후백제군에 크게 패해 신숭겸 등 많은 장수를 잃었다.', -4, '고려가 한때 후백제에 밀리는 위기를 맞았다.'),
('taejo-wanggeon-3', 'taejo-wanggeon', 930, '고창 전투 승리', '고창(안동)에서 후백제군을 크게 격파했다.', 5, '경상도 호족들이 고려로 기울며 후삼국의 판세가 바뀌었다.'),
('taejo-wanggeon-4', 'taejo-wanggeon', 934, '발해 유민 수용', '발해 세자 대광현이 이끄는 유민 수만 명을 받아들였다.', 4, '발해 유민을 포용해 고구려 계승 의식과 국력을 키웠다.'),
('taejo-wanggeon-5', 'taejo-wanggeon', 935, '신라 귀부 수용', '신라 경순왕의 항복을 받아들이고 예우했다.', 5, '전쟁 없이 신라를 통합해 정통성을 확보했다.'),
('taejo-wanggeon-6', 'taejo-wanggeon', 936, '후삼국 통일', '일리천 전투에서 후백제군을 격파하고 후백제를 멸망시켰다.', 9, '분열된 한반도를 다시 하나의 국가로 통합했다.'),
('taejo-wanggeon-7', 'taejo-wanggeon', 942, '만부교 사건', '거란이 보낸 사신을 섬으로 유배하고 낙타 50필을 만부교 아래에서 굶겨 죽였다.', -2, '거란과의 관계를 단절해 이후 대립의 한 배경이 됐다.'),
('taejo-wanggeon-8', 'taejo-wanggeon', 943, '훈요 10조', '후대 왕들이 지켜야 할 정치 지침인 훈요 10조를 남겼다.', 2, '불교 숭상과 북진 등 고려 국정 운영의 방향을 제시했으나 특정 지역 인재 배제 조항도 담겼다.'),
('gwangjong-1', 'gwangjong', 950, '광덕 연호 사용', '''광덕''이라는 독자적인 연호를 사용했다.', 2, '왕권의 위상과 자주 의식을 드러냈다.'),
('gwangjong-2', 'gwangjong', 956, '노비안검법 시행', '억울하게 노비가 된 사람들을 조사해 양인으로 되돌렸다.', 6, '호족의 경제·군사 기반을 약화하고 국가 재정을 확충했다.'),
('gwangjong-3', 'gwangjong', 958, '과거제 실시', '후주 출신 쌍기의 건의로 과거 제도를 처음 실시했다.', 8, '능력에 따른 관리 선발 제도를 도입해 이후 천 년 가까이 이어지는 인재 등용 방식의 기초를 놓았다.'),
('gwangjong-4', 'gwangjong', 960, '백관 공복 제정', '관리의 등급에 따라 공복의 색을 자색·단색·비색·녹색으로 구분했다.', 3, '관료 위계를 정비해 왕 중심의 질서를 세웠다.'),
('gwangjong-5', 'gwangjong', 960, '호족·공신 숙청', '참소를 계기로 많은 공신과 호족, 왕족을 처형하는 숙청을 벌였다.', -6, '왕권은 강화됐으나 대규모 희생과 정치적 공포를 낳았다.'),
('gwangjong-6', 'gwangjong', 963, '제위보 설치', '빈민을 구제하는 기관인 제위보를 설치했다.', 2, '빈민 구휼을 제도화한 조치였다.'),
('seongjong-goryeo-1', 'seongjong-goryeo', 982, '시무 28조 수용', '최승로가 올린 시무 28조를 받아들여 국정 개혁의 방향으로 삼았다.', 6, '유교 정치 이념을 국가 운영의 기본으로 확립했다.'),
('seongjong-goryeo-2', 'seongjong-goryeo', 983, '12목 설치', '전국 주요 지역에 12목을 두고 처음으로 지방관을 파견했다.', 7, '중앙 집권적 지방 통치의 출발점이 됐다.'),
('seongjong-goryeo-3', 'seongjong-goryeo', 992, '국자감 설치', '최고 교육 기관인 국자감을 세웠다.', 5, '유학 교육과 관리 양성 체계를 갖추었다.'),
('seongjong-goryeo-4', 'seongjong-goryeo', 993, '상평창 설치', '개경·서경과 12목에 물가 조절 기관인 상평창을 두었다.', 3, '곡물 가격을 안정시켜 백성의 생활을 보호하려 했다.'),
('seongjong-goryeo-5', 'seongjong-goryeo', 993, '거란 침입 때 할지론 기울어짐', '거란 1차 침입 때 서경 이북 땅을 떼어 주자는 의견을 따르려 하고 서경 창고의 쌀을 버리게 하려 했다.', -2, '서희 등의 반대로 철회됐으나 위기 대응이 흔들렸다.'),
('seongjong-goryeo-6', 'seongjong-goryeo', 995, '10도 설치', '전국을 10도로 나누는 행정 구역을 정했다.', 2, '지방 행정 구획을 체계화했다.'),
('seongjong-goryeo-7', 'seongjong-goryeo', 996, '건원중보 주조', '고려 최초의 철전인 건원중보를 만들었다.', 2, '화폐 유통을 시도했으나 널리 쓰이지는 못했다.'),
('hyeonjong-goryeo-1', 'hyeonjong-goryeo', 1010, '연등회·팔관회 부활', '성종 때 폐지된 연등회와 팔관회를 다시 열었다.', 2, '전통 행사를 되살려 사회 통합을 꾀했다.'),
('hyeonjong-goryeo-2', 'hyeonjong-goryeo', 1011, '개경 함락과 나주 피란', '거란 2차 침입으로 개경이 함락되자 나주까지 피란했다.', -3, '도성의 궁궐과 기록이 불타는 큰 피해를 입었다.'),
('hyeonjong-goryeo-3', 'hyeonjong-goryeo', 1011, '초조대장경 조판 시작', '거란 침입을 불력으로 물리치기를 바라며 대장경 조판을 시작했다.', 5, '고려 인쇄 문화와 불교 문화의 큰 성과로 이어졌다.'),
('hyeonjong-goryeo-4', 'hyeonjong-goryeo', 1013, '7대 실록 편찬 착수', '전란으로 불탄 태조부터 목종까지의 역사를 다시 정리하는 실록 편찬을 시작했다.', 3, '잃어버린 국가 기록을 복원하는 계기가 됐다.'),
('hyeonjong-goryeo-5', 'hyeonjong-goryeo', 1018, '지방 제도 정비', '5도 양계와 4도호부 8목을 중심으로 지방 제도를 정비했다.', 6, '고려 지방 행정의 기본 틀을 완성했다.'),
('seohui-1', 'seohui', 972, '송과 국교 재개', '사신으로 송에 가서 10여 년간 끊겼던 국교를 다시 열었다.', 3, '고려와 송의 외교·문화 교류를 되살렸다.'),
('seohui-2', 'seohui', 993, '할지론 반대', '거란 침입 때 서경 이북을 떼어 주자는 주장에 맞서 항전과 협상을 주장했다.', 3, '영토를 내주는 굴복을 막았다.'),
('seohui-3', 'seohui', 993, '소손녕과 외교 담판', '거란 장수 소손녕과 담판해 고려가 고구려 계승국임을 내세우고 거란군을 물러나게 했다.', 8, '전투 없이 침입을 끝내고 압록강 동쪽 땅의 영유권을 인정받았다.'),
('seohui-4', 'seohui', 994, '강동 6주 개척', '압록강 동쪽의 여진을 몰아내고 강동 6주에 성을 쌓았다.', 6, '영토를 압록강까지 넓히고 이후 거란 방어의 거점을 마련했다.'),
('gang-gamchan-1', 'gang-gamchan', 1010, '항복론 반대', '거란 2차 침입 때 항복하자는 의견에 반대하고 왕의 남쪽 피란을 건의했다.', 4, '왕실을 보전하고 항전을 이어 갈 수 있게 했다.'),
('gang-gamchan-2', 'gang-gamchan', 1018, '흥화진 전투 승리', '상원수로서 흥화진에서 강물을 막았다가 터뜨리는 전술로 거란군을 격파했다.', 4, '거란 3차 침입의 초기 기세를 꺾었다.'),
('gang-gamchan-3', 'gang-gamchan', 1019, '귀주대첩', '귀주에서 퇴각하는 거란군을 크게 격파해 10만 대군 중 수천 명만 살아 돌아가게 했다.', 9, '거란의 침입을 끝내고 고려·송·거란 사이의 세력 균형을 이루었다.'),
('gang-gamchan-4', 'gang-gamchan', 1029, '개경 나성 완성', '그의 건의로 쌓기 시작한 개경 외곽의 나성이 완성되었다.', 3, '수도 방어 체계를 크게 보강했다.'),
('choe-chungheon-1', 'choe-chungheon', 1196, '이의민 제거와 집권', '동생 최충수와 함께 이의민 일족을 죽이고 권력을 잡았다.', -3, '무신 간 정변을 이어 가며 사병에 기반한 독재의 출발점이 됐다.'),
('choe-chungheon-2', 'choe-chungheon', 1196, '봉사 10조 건의', '명종에게 사회 폐단을 바로잡자는 봉사 10조를 올렸다.', 2, '개혁 방향을 제시했으나 실제로는 거의 실행되지 않았다.'),
('choe-chungheon-3', 'choe-chungheon', 1197, '명종 폐위', '명종을 폐위하고 신종을 세웠다.', -4, '왕위를 실권자의 뜻대로 바꾸는 선례를 굳혔다.'),
('choe-chungheon-4', 'choe-chungheon', 1198, '만적의 난 진압', '자신의 사노비 만적이 주도한 신분 해방 봉기 계획을 사전에 진압하고 100여 명을 강에 던져 죽였다.', -3, '하층민의 저항을 가혹하게 탄압했다.'),
('choe-chungheon-5', 'choe-chungheon', 1209, '교정도감 설치', '국정을 총괄하는 최고 권력 기구로 교정도감을 설치했다.', -5, '국가 기구 위에 사적 권력 기구를 두어 최씨 정권의 세습 독재를 제도화했다.'),
('choe-chungheon-6', 'choe-chungheon', 1211, '희종 폐위', '자신을 제거하려던 시도가 실패하자 희종을 폐위하고 강종을 세웠다.', -3, '왕권을 더욱 무력화했다.'),
('gongmin-1', 'gongmin', 1352, '변발·호복 폐지', '몽골식 머리 모양과 옷차림을 금지했다.', 3, '원 간섭에서 벗어나려는 의지를 상징적으로 보였다.'),
('gongmin-2', 'gongmin', 1356, '친원 세력 숙청', '기철 등 친원 세력을 제거하고 정동행성 이문소를 폐지했다.', 6, '원의 내정 간섭 통로를 끊고 왕권을 회복했다.'),
('gongmin-3', 'gongmin', 1356, '쌍성총관부 수복', '무력으로 쌍성총관부를 공격해 철령 이북 땅을 되찾았다.', 7, '약 100년 만에 빼앗긴 영토를 회복했다.'),
('gongmin-4', 'gongmin', 1361, '홍건적 침입과 개경 함락', '홍건적의 2차 침입으로 개경이 함락되자 복주(안동)로 피란했다.', -4, '도성이 큰 피해를 입고 개혁의 동력이 약해졌다.'),
('gongmin-5', 'gongmin', 1366, '전민변정도감 설치', '신돈을 등용해 전민변정도감을 두고 권문세족이 빼앗은 토지와 노비를 돌려주게 했다.', 5, '권문세족의 경제 기반을 줄이고 백성의 부담을 덜었다.'),
('gongmin-6', 'gongmin', 1367, '성균관 중건', '성균관을 다시 짓고 유학 교육을 강화했다.', 4, '신진 사대부가 성장하는 기반이 됐다.'),
('gongmin-7', 'gongmin', 1372, '자제위 설치', '젊은 귀족 자제들로 이루어진 측근 기구인 자제위를 두었다.', -2, '측근 정치가 심해졌고 1374년 자제위 소속 인물들에게 시해되는 배경이 됐다.'),
('taejo-joseon-1', 'taejo-joseon', 1388, '위화도 회군', '요동 정벌군을 이끌던 중 압록강 위화도에서 군대를 돌려 개경을 장악하고 우왕과 최영을 몰아냈다.', 2, '명과의 무리한 전쟁을 피했지만 군사력으로 정권을 장악한 정변이었다.'),
('taejo-joseon-2', 'taejo-joseon', 1391, '과전법 시행', '신진 사대부와 함께 권문세족의 대토지를 정리하고 관리에게 수조권을 나누어 주는 과전법을 시행했다.', 5, '고려 말 토지 문란을 바로잡고 새 왕조의 경제 기반을 마련했다.'),
('taejo-joseon-3', 'taejo-joseon', 1392, '조선 건국', '공양왕을 폐하고 왕위에 올라 새 왕조를 열었으며 이듬해 국호를 조선으로 정했다.', 8, '500년 넘게 이어진 왕조의 기틀을 세웠다.'),
('taejo-joseon-4', 'taejo-joseon', 1392, '막내 이방석 세자 책봉', '공이 큰 전처 소생 아들들을 제치고 계비 신덕왕후 소생의 막내 이방석을 세자로 세웠다.', -3, '왕자들의 반발을 불러 1398년 제1차 왕자의 난의 원인이 되었다.'),
('taejo-joseon-5', 'taejo-joseon', 1394, '고려 왕족 왕씨 처형', '공양왕과 그 아들들을 죽이고 각지의 왕씨 일족을 대거 처형했다.', -4, '정권 안정을 이유로 전 왕조 왕족을 집단 살해했다.'),
('taejo-joseon-6', 'taejo-joseon', 1394, '한양 천도', '도읍을 개경에서 한양으로 옮기고 궁궐과 종묘를 세웠다.', 7, '한양은 이후 600년 넘게 한국의 수도로 이어졌다.'),
('jeong-dojeon-1', 'jeong-dojeon', 1392, '조선 개국 주도', '이성계를 왕으로 추대하는 데 앞장서 개국 1등 공신이 되었다.', 6, '새 왕조의 이념과 정치 세력을 결집한 핵심 인물이었다.'),
('jeong-dojeon-2', 'jeong-dojeon', 1394, '『조선경국전』 편찬', '재상 중심의 통치 원칙과 6전 체제를 담은 법전 『조선경국전』을 지어 바쳤다.', 7, '뒷날 『경국대전』으로 이어지는 조선 법제의 토대가 되었다.'),
('jeong-dojeon-3', 'jeong-dojeon', 1395, '한양 도성과 경복궁 설계', '한양의 궁궐·종묘·도성 배치를 주도하고 경복궁과 그 전각들의 이름을 지었다.', 3, '수도 한양의 공간 구조를 오래도록 결정지었다.'),
('jeong-dojeon-4', 'jeong-dojeon', 1395, '『고려국사』 편찬', '정총 등과 함께 고려 역사를 정리한 『고려국사』를 편찬했다.', 2, '전 왕조 역사를 정리했으나 책은 전하지 않고 영향은 제한적이었다.'),
('jeong-dojeon-5', 'jeong-dojeon', 1398, '요동 정벌 추진', '진법 훈련을 강화하며 요동 정벌을 추진했다.', -2, '건국 초 명과의 외교 갈등을 키웠다.'),
('taejong-joseon-1', 'taejong-joseon', 1398, '제1차 왕자의 난', '정도전과 세자 이방석, 이방번 등을 살해하고 실권을 장악했다.', -4, '개국 공신과 형제를 무력으로 제거한 유혈 정변이었다.'),
('taejong-joseon-2', 'taejong-joseon', 1400, '사병 혁파', '왕족과 공신이 거느리던 사병을 없애고 군사권을 국가로 일원화했다.', 5, '내란의 위험을 줄이고 중앙 집권의 기반을 다졌다.'),
('taejong-joseon-3', 'taejong-joseon', 1401, '신문고 설치', '억울한 일을 직접 호소할 수 있도록 궁궐 밖에 신문고를 달았다.', 2, '백성의 호소 통로를 만들었으나 실제 이용은 제한적이었다.'),
('taejong-joseon-4', 'taejong-joseon', 1410, '민무구·민무질 형제 처형', '왕비 원경왕후의 동생인 민무구·민무질 형제를 유배 끝에 자결하게 했다.', -3, '외척 견제를 명분으로 정치적 숙청을 단행했다.'),
('taejong-joseon-5', 'taejong-joseon', 1413, '호패법 시행', '16세 이상 남자에게 신분증인 호패를 차게 했다.', 4, '인구와 역 부담자를 파악하는 국가 행정의 기반을 마련했다.'),
('taejong-joseon-6', 'taejong-joseon', 1414, '6조 직계제 실시', '6조가 의정부를 거치지 않고 왕에게 직접 보고하도록 바꾸었다.', 5, '왕권 중심의 효율적 행정 체계를 세웠다.'),
('taejong-joseon-7', 'taejong-joseon', 1418, '충녕대군 세자 책봉', '세자 양녕대군을 폐하고 셋째 아들 충녕대군을 세자로 세운 뒤 왕위를 물려주었다.', 5, '세종의 즉위로 이어져 조선 전기 전성기를 열었다.'),
('sejong-1', 'sejong', 1420, '집현전 확대 개편', '집현전을 학문 연구와 정책 자문 기관으로 확대 개편했다.', 6, '많은 학자를 길러 각종 편찬 사업과 제도 정비의 중심이 되었다.'),
('sejong-2', 'sejong', 1429, '『농사직설』 편찬', '각 지방 농민의 경험을 모아 우리 풍토에 맞는 농법을 정리한 『농사직설』을 펴냈다.', 5, '농업 생산력 향상에 오래도록 기여했다.'),
('sejong-3', 'sejong', 1432, '노비종모법 환원', '아버지가 양인이면 자식도 양인이 되던 종부법을 폐지하고 어머니 신분을 따르는 종모법으로 되돌렸다.', -3, '양인 노비 소생의 노비화를 늘려 신분 상승의 길을 좁혔다.'),
('sejong-4', 'sejong', 1433, '4군 6진 개척', '최윤덕과 김종서를 보내 압록강·두만강 유역의 여진을 몰아내고 4군 6진을 설치했다.', 7, '오늘날 한반도 북쪽 국경선의 바탕을 확정했다.'),
('sejong-5', 'sejong', 1441, '측우기 제작', '강우량을 재는 측우기를 만들고 이듬해 각 지방에 설치하게 했다.', 5, '전국적 강우 관측 체계를 세워 농업 행정에 활용했다.'),
('sejong-6', 'sejong', 1443, '훈민정음 창제', '백성이 쉽게 익혀 쓸 수 있는 고유 문자 훈민정음을 만들었다.', 10, '오늘날까지 쓰이는 한글의 기원으로 한국 문화 전반에 결정적 영향을 주었다.'),
('sejong-7', 'sejong', 1444, '공법 제정', '토지 비옥도에 따른 전분 6등법과 풍흉에 따른 연분 9등법으로 전세 제도를 정비했다.', 5, '여론 조사를 거쳐 세금 부과를 합리화했다.'),
('sejo-joseon-1', 'sejo-joseon', 1453, '계유정난', '수양대군으로서 김종서·황보인 등 대신을 살해하고 정권을 장악했다.', -6, '어린 왕을 보좌하던 대신들을 무력으로 제거한 정변이었다.'),
('sejo-joseon-2', 'sejo-joseon', 1456, '사육신 처형과 집현전 폐지', '단종 복위를 꾀한 성삼문·박팽년 등을 처형하고 집현전을 없앴다.', -5, '많은 학자와 관료를 죽이고 학문 기관을 폐지했다.'),
('sejo-joseon-3', 'sejo-joseon', 1457, '진관 체제 실시', '각 도에 거진을 두고 주변 고을을 묶어 스스로 방어하게 하는 진관 체제를 마련했다.', 3, '지역 단위 방어 체계를 갖추었다.'),
('sejo-joseon-4', 'sejo-joseon', 1457, '단종 사사', '노산군으로 강봉해 영월로 유배한 단종을 죽게 했다.', -5, '왕위를 빼앗은 조카를 살해한 행위였다.'),
('sejo-joseon-5', 'sejo-joseon', 1460, '『경국대전』 편찬 착수', '통치 법전 편찬에 착수해 먼저 호전을 완성했다.', 4, '조선 법치 체제의 근간이 되는 법전 편찬을 시작했다.'),
('sejo-joseon-6', 'sejo-joseon', 1466, '직전법 시행', '현직 관리에게만 수조권을 지급하는 직전법을 시행했다.', 3, '부족해진 토지를 확보해 국가 재정을 보충했다.'),
('sejo-joseon-7', 'sejo-joseon', 1467, '이시애의 난 진압', '함경도에서 일어난 이시애의 반란을 진압했다.', 2, '지방 반란을 수습하고 중앙 통제를 강화했다.'),
('seongjong-joseon-1', 'seongjong-joseon', 1470, '관수관급제 시행', '관청이 직접 조세를 거두어 관리에게 나누어 주는 관수관급제를 시행했다.', 3, '관리의 과도한 수탈을 줄이고 국가의 토지 지배를 강화했다.'),
('seongjong-joseon-2', 'seongjong-joseon', 1474, '『국조오례의』 완성', '국가 의례의 기준이 되는 『국조오례의』를 완성했다.', 3, '국가 의례를 체계화해 유교적 통치 질서를 뒷받침했다.'),
('seongjong-joseon-3', 'seongjong-joseon', 1478, '홍문관 설치', '집현전의 기능을 잇는 학문·언론 기관인 홍문관을 두었다.', 4, '삼사 언론 체계를 갖추어 왕권 견제와 학문 진흥에 기여했다.'),
('seongjong-joseon-4', 'seongjong-joseon', 1481, '『동국여지승람』 편찬', '전국 각 지역의 지리와 풍속을 정리한 『동국여지승람』을 편찬했다.', 3, '국가 통치와 지역 이해에 쓰인 대표 지리지가 되었다.'),
('seongjong-joseon-5', 'seongjong-joseon', 1482, '폐비 윤씨 사사', '1479년에 폐한 왕비 윤씨에게 사약을 내렸다.', -4, '연산군 대 갑자사화의 원인이 되어 대규모 피해로 이어졌다.'),
('seongjong-joseon-6', 'seongjong-joseon', 1485, '『경국대전』 반포', '세조 때 시작한 『경국대전』을 완성해 시행했다.', 8, '조선 말까지 통치의 기본 법전으로 쓰였다.'),
('yeonsangun-1', 'yeonsangun', 1498, '무오사화', '김종직의 「조의제문」을 문제 삼아 김일손 등 사림을 처형하고 김종직을 부관참시했다.', -6, '많은 사림 관료를 희생시킨 첫 사화였다.'),
('yeonsangun-2', 'yeonsangun', 1504, '갑자사화', '생모 폐비 윤씨 사건에 관련된 대신과 선비들을 대거 처형했다.', -7, '무오사화보다 큰 규모로 조정 인재를 숙청했다.'),
('yeonsangun-3', 'yeonsangun', 1504, '경연·사간원 폐지', '왕에게 학문을 강론하는 경연을 없애고 간쟁 기관인 사간원을 폐지했다.', -3, '왕권 견제 장치를 없애 폭정을 가속했다.'),
('yeonsangun-4', 'yeonsangun', 1504, '한글 사용 금지', '자신을 비방하는 한글 투서가 나오자 한글 교습과 사용을 금지하고 관련 서적을 불태우게 했다.', -4, '한글의 보급과 사용을 크게 위축시켰다.'),
('jungjong-joseon-1', 'jungjong-joseon', 1506, '정국공신 대거 책봉', '반정 직후 100명이 넘는 인원을 정국공신으로 책봉했다.', -2, '공신 남발로 훈구 세력의 특권이 커지고 재정 부담이 늘었다.'),
('jungjong-joseon-2', 'jungjong-joseon', 1510, '삼포왜란 진압', '부산포·제포·염포에 거주하던 왜인들의 폭동을 진압했다.', 3, '남부 해안의 치안을 회복했다.'),
('jungjong-joseon-3', 'jungjong-joseon', 1512, '임신약조 체결', '대마도주와 임신약조를 맺어 제포만 열고 세견선을 줄인 조건으로 교역을 재개했다.', 2, '통제된 범위에서 일본과의 관계를 복구했다.'),
('jungjong-joseon-4', 'jungjong-joseon', 1515, '조광조 등용과 개혁 정치', '조광조 등 사림을 등용해 현량과 실시, 소격서 폐지, 향약 보급 등 개혁을 추진했다.', 4, '사림 정치와 유교적 향촌 질서의 기반을 넓혔다.'),
('jungjong-joseon-5', 'jungjong-joseon', 1519, '기묘사화', '위훈 삭제에 반발한 훈구 세력의 탄핵을 받아들여 조광조를 사사하고 사림을 대거 축출했다.', -6, '개혁을 좌절시키고 많은 인재를 희생시켰다.'),
('seonjo-joseon-1', 'seonjo-joseon', 1589, '기축옥사', '정여립 모반 사건을 계기로 동인 계열 인사 1,000여 명을 처벌했다.', -5, '대규모 옥사로 많은 선비가 희생되고 당쟁이 격화되었다.'),
('seonjo-joseon-2', 'seonjo-joseon', 1591, '이순신 전라좌수사 발탁', '정읍 현감이던 이순신을 전라좌도 수군절도사로 파격 승진시켰다.', 5, '임진왜란에서 조선 수군 승리의 바탕이 되었다.'),
('seonjo-joseon-3', 'seonjo-joseon', 1591, '일본 침략 대비 소홀', '일본에 다녀온 통신사의 엇갈린 보고 가운데 침략 가능성을 낮게 본 의견을 받아들였다.', -4, '전쟁 대비가 부족해 초기에 큰 패배를 당했다.'),
('seonjo-joseon-4', 'seonjo-joseon', 1592, '한양 포기와 의주 몽진', '일본군이 북상하자 한양을 버리고 의주까지 피란했다.', -3, '도성 방어를 포기해 민심이 크게 흔들렸다.'),
('seonjo-joseon-5', 'seonjo-joseon', 1592, '명에 원군 요청', '명에 사신을 보내 지원군 파병을 이끌어 냈다.', 3, '명군 참전으로 평양 탈환 등 전세 회복에 도움을 받았다.'),
('seonjo-joseon-6', 'seonjo-joseon', 1593, '훈련도감 설치', '포수·사수·살수의 삼수병으로 구성된 상비군 훈련도감을 설치했다.', 4, '조선 후기 5군영 체제의 출발점이 되었다.'),
('seonjo-joseon-7', 'seonjo-joseon', 1597, '이순신 파직·하옥', '출전 명령 불응 등을 이유로 삼도수군통제사 이순신을 파직하고 투옥했다.', -6, '후임 원균이 칠천량에서 대패해 조선 수군이 거의 궤멸했다.'),
('yi-sunsin-1', 'yi-sunsin', 1592, '옥포해전', '거제 옥포에서 일본 수군을 격파해 임진왜란 첫 해전 승리를 거두었다.', 5, '육지에서 연패하던 조선에 첫 승리를 안겨 사기를 높였다.'),
('yi-sunsin-2', 'yi-sunsin', 1592, '사천해전 거북선 투입', '직접 건조한 거북선을 사천해전에 처음 투입해 승리했다.', 4, '새 전선을 실전에 활용해 수군 전력을 크게 높였다.'),
('yi-sunsin-3', 'yi-sunsin', 1592, '한산도대첩', '학익진으로 견내량의 일본 수군을 한산도 앞바다로 유인해 크게 격파했다.', 9, '일본군의 서해 진출과 수륙 병진 계획을 좌절시켜 전쟁의 흐름을 바꾸었다.'),
('yi-sunsin-4', 'yi-sunsin', 1593, '한산도 수군 본영 설치', '본영을 한산도로 옮기고 삼도수군통제사로서 둔전과 전선 건조로 수군을 정비했다.', 3, '장기전을 버틸 수군의 거점과 보급 체계를 마련했다.'),
('yi-sunsin-5', 'yi-sunsin', 1597, '명량해전', '칠천량 패전 뒤 남은 13척의 배로 울돌목에서 130여 척의 일본 함대를 물리쳤다.', 9, '궤멸 직전의 수군을 되살리고 일본군의 서해 진출을 다시 막았다.'),
('yi-sunsin-6', 'yi-sunsin', 1598, '노량해전', '철수하는 일본 수군을 노량에서 격파하다가 적탄에 맞아 전사했다.', 6, '전쟁의 마지막 대규모 해전에서 일본 수군에 큰 타격을 주었다.'),
('gwanghaegun-1', 'gwanghaegun', 1608, '대동법 시행', '선혜청을 두고 경기도에 공물을 쌀로 내게 하는 대동법을 처음 시행했다.', 7, '공납 부담을 줄이는 개혁이 이후 전국으로 확대되었다.'),
('gwanghaegun-2', 'gwanghaegun', 1609, '기유약조 체결', '임진왜란 뒤 끊겼던 일본과의 국교를 기유약조로 재개했다.', 3, '제한된 교역을 허용해 남쪽 국경을 안정시켰다.'),
('gwanghaegun-3', 'gwanghaegun', 1613, '계축옥사', '역모 사건을 빌미로 영창대군을 서인으로 강등해 강화도에 유배했고 이듬해 그가 죽었다.', -5, '어린 왕자를 희생시키고 반대파를 대거 숙청했다.'),
('gwanghaegun-4', 'gwanghaegun', 1613, '『동의보감』 간행', '허준이 완성한 의서 『동의보감』을 간행했다.', 4, '동아시아 의학의 대표 서적으로 오래도록 쓰였다.'),
('gwanghaegun-5', 'gwanghaegun', 1617, '인경궁·경덕궁 공사', '인경궁과 경덕궁을 짓는 대규모 궁궐 공사를 벌였다.', -3, '전란 뒤 재정과 백성에게 큰 부담을 주었다.'),
('gwanghaegun-6', 'gwanghaegun', 1618, '인목대비 서궁 유폐', '폐모론에 따라 인목대비를 서궁(경운궁)에 가두었다.', -4, '유교 윤리를 내세운 반대 세력의 반정 명분이 되었다.'),
('gwanghaegun-7', 'gwanghaegun', 1619, '명·후금 사이 실리 외교', '명의 요청으로 강홍립의 군대를 파병했으나 사르후 전투 뒤 투항한 이후 후금과의 충돌을 피하는 외교를 폈다.', 4, '재위 동안 후금의 침입을 막았다.'),
('injo-joseon-1', 'injo-joseon', 1623, '인조반정', '서인 세력과 함께 군사를 일으켜 광해군을 폐위하고 왕위에 올랐다.', -4, '무력으로 왕을 몰아냈고 이후 외교 노선 전환으로 전란을 초래했다.'),
('injo-joseon-2', 'injo-joseon', 1623, '강원도 대동법 시행', '대동법을 강원도로 확대 시행했다.', 3, '공납 개혁의 범위를 넓혔다.'),
('injo-joseon-3', 'injo-joseon', 1627, '정묘호란', '친명배금 정책 속에 후금의 침입을 받아 강화도로 피란하고 형제 관계를 맺었다.', -5, '외교 실패로 전쟁을 부르고 굴욕적 강화를 맺었다.'),
('injo-joseon-4', 'injo-joseon', 1633, '상평통보 주조', '동전 상평통보를 처음 주조했다.', 2, '화폐 유통의 시도였으나 당시에는 널리 쓰이지 못했다.'),
('injo-joseon-5', 'injo-joseon', 1635, '영정법 시행', '풍흉에 관계없이 토지 1결당 전세를 쌀 4~6두로 고정하는 영정법을 시행했다.', 3, '전세 부담을 낮추고 징수를 단순화했다.'),
('injo-joseon-6', 'injo-joseon', 1636, '병자호란과 삼전도 항복', '청의 침입에 남한산성에서 버티다 이듬해 삼전도에서 청 태종에게 항복했다.', -8, '청에 신하의 예를 갖추게 되었고 수많은 백성이 포로로 끌려갔다.'),
('injo-joseon-7', 'injo-joseon', 1646, '세자빈 강씨 사사', '소현세자가 죽은 뒤 세자빈 강씨에게 사약을 내리고 원손들을 제주도로 유배했다.', -4, '근거가 약한 혐의로 며느리를 죽이고 손자들을 희생시켰다.'),
('hyojong-joseon-1', 'hyojong-joseon', 1651, '충청도 대동법 시행', '김육의 건의를 받아들여 대동법을 충청도로 확대했다.', 4, '삼남 지방으로 공납 개혁을 넓혀 농민 부담을 덜었다.'),
('hyojong-joseon-2', 'hyojong-joseon', 1652, '북벌 군비 확장', '어영청을 개편·확대하는 등 청을 치기 위한 군사력 증강을 추진했다.', -2, '북벌은 실행되지 못한 채 재정과 백성의 부담만 늘었다.'),
('hyojong-joseon-3', 'hyojong-joseon', 1653, '시헌력 채택', '서양 역법을 반영한 청의 시헌력을 받아들여 시행했다.', 3, '보다 정확한 역법을 도입해 조선 말까지 사용했다.'),
('hyojong-joseon-4', 'hyojong-joseon', 1654, '나선 정벌', '청의 요청으로 조총병을 보내 흑룡강 일대의 러시아군을 물리쳤으며 1658년에 다시 출병했다.', 3, '조선 조총병의 전력을 입증했다.'),
('hyojong-joseon-5', 'hyojong-joseon', 1655, '『농가집성』 간행', '신속이 엮은 농서 『농가집성』을 간행해 보급했다.', 3, '이앙법 등 개선된 농법 보급에 기여했다.'),
('sukjong-joseon-1', 'sukjong-joseon', 1678, '상평통보 전국 유통', '상평통보를 다시 주조해 법화로 삼고 전국에 유통시켰다.', 5, '화폐 경제가 자리 잡아 상업 발달을 뒷받침했다.'),
('sukjong-joseon-2', 'sukjong-joseon', 1680, '경신환국', '남인 정권을 몰아내고 허적·윤휴 등을 처형한 뒤 서인을 기용했다.', -3, '급격한 정권 교체로 붕당 간 보복을 키웠다.'),
('sukjong-joseon-3', 'sukjong-joseon', 1682, '금위영 설치', '금위영을 설치해 5군영 체제를 완성했다.', 3, '수도 방어 체계를 정비했다.'),
('sukjong-joseon-4', 'sukjong-joseon', 1689, '기사환국', '희빈 장씨 소생의 원자 책봉에 반대한 송시열 등 서인을 숙청하고 인현왕후를 폐했다.', -4, '송시열 사사 등 대규모 숙청으로 정쟁을 격화시켰다.'),
('sukjong-joseon-5', 'sukjong-joseon', 1694, '울릉도 수토와 영유권 교섭', '장한상을 울릉도에 보내 조사하게 하고 일본과의 교섭에서 울릉도가 조선 땅임을 주장했다.', 4, '1696년 막부의 울릉도 도해 금지로 이어져 영토를 지켰다.'),
('sukjong-joseon-6', 'sukjong-joseon', 1701, '희빈 장씨 사사', '인현왕후를 저주했다는 무고의 옥으로 희빈 장씨에게 사약을 내렸다.', -3, '궁중 문제가 다시 정쟁과 처벌로 번졌다.'),
('sukjong-joseon-7', 'sukjong-joseon', 1708, '황해도 대동법 시행', '대동법을 황해도까지 확대해 평안·함경도를 제외한 전국에서 시행하게 했다.', 6, '100년에 걸친 공납 개혁을 사실상 완성했다.'),
('sukjong-joseon-8', 'sukjong-joseon', 1712, '백두산정계비 건립', '청과 국경을 정하고 백두산에 정계비를 세웠다.', 2, '북방 국경을 정했으나 문구 해석을 둘러싸고 훗날 간도 문제가 생겼다.'),
('yeongjo-joseon-1', 'yeongjo-joseon', 1725, '압슬형 폐지', '무릎을 짓누르는 가혹한 고문인 압슬형을 없앴다.', 2, '형벌 제도를 완화했다.'),
('yeongjo-joseon-2', 'yeongjo-joseon', 1728, '이인좌의 난 진압', '소론 강경파와 남인 일부가 일으킨 이인좌의 난을 진압했다.', 2, '왕권에 대한 무력 도전을 수습했다.'),
('yeongjo-joseon-3', 'yeongjo-joseon', 1742, '탕평책 추진과 탕평비 건립', '붕당 간 고른 인재 등용을 내세운 탕평책을 펴고 성균관에 탕평비를 세웠다.', 5, '격화된 붕당 갈등을 누그러뜨리고 왕권을 안정시켰다.'),
('yeongjo-joseon-4', 'yeongjo-joseon', 1750, '균역법 시행', '군포를 2필에서 1필로 줄이고 부족분은 결작·어염세 등으로 보충했다.', 6, '농민의 군역 부담을 크게 덜었다.'),
('yeongjo-joseon-5', 'yeongjo-joseon', 1760, '청계천 준천', '대규모 인력을 동원해 청계천 바닥을 파내고 물길을 정비했다.', 3, '도성의 홍수 피해를 줄였다.'),
('yeongjo-joseon-6', 'yeongjo-joseon', 1762, '임오화변', '세자인 사도세자를 폐하고 뒤주에 가두어 죽게 했다.', -6, '왕실의 비극이자 이후 정치 갈등의 불씨가 되었다.'),
('yeongjo-joseon-7', 'yeongjo-joseon', 1770, '『동국문헌비고』 편찬', '우리나라 역대 문물과 제도를 정리한 백과사전 『동국문헌비고』를 편찬했다.', 3, '국가 제도와 문화를 체계적으로 정리했다.'),
('jeongjo-joseon-1', 'jeongjo-joseon', 1776, '규장각 설치', '즉위하자마자 규장각을 세워 학문 연구와 정책 개발의 중심 기관으로 삼았다.', 6, '서얼 출신 검서관을 포함한 인재를 길러 개혁 정치의 기반이 되었다.'),
('jeongjo-joseon-2', 'jeongjo-joseon', 1785, '『대전통편』 편찬', '『경국대전』과 『속대전』 이후의 법령을 통합한 『대전통편』을 펴냈다.', 4, '법전 체계를 정비해 통치의 일관성을 높였다.'),
('jeongjo-joseon-3', 'jeongjo-joseon', 1791, '신해통공', '육의전을 제외한 시전 상인의 금난전권을 폐지했다.', 5, '자유로운 상업 활동을 넓혀 상품 경제 발달을 촉진했다.'),
('jeongjo-joseon-4', 'jeongjo-joseon', 1791, '신해박해', '모친 제사를 거부하고 신주를 불태운 윤지충·권상연을 처형했다.', -3, '신앙을 이유로 사람을 처형해 천주교 탄압의 선례를 남겼다.'),
('jeongjo-joseon-5', 'jeongjo-joseon', 1792, '문체반정', '소설·소품체 문장을 금하고 고문 문체로 돌아갈 것을 명령했다.', -2, '새로운 문풍과 사상을 위축시켰다.'),
('jeongjo-joseon-6', 'jeongjo-joseon', 1793, '장용영 설치', '국왕 직속 친위 부대 장용영을 정식으로 설치했다.', 2, '왕권을 뒷받침하는 군사 기반을 마련했다.'),
('jeongjo-joseon-7', 'jeongjo-joseon', 1796, '수원 화성 완공', '정약용의 설계와 거중기를 활용해 수원 화성을 완공했다.', 5, '과학적 축성술의 성과로 오늘날 세계유산으로 남아 있다.'),
('heungseon-daewongun-1', 'heungseon-daewongun', 1865, '비변사 폐지', '비변사의 기능을 의정부와 삼군부로 돌리고 비변사를 없앴다.', 3, '세도 가문이 장악한 권력 기구를 정리하고 행정 체계를 바로잡았다.'),
('heungseon-daewongun-2', 'heungseon-daewongun', 1865, '『대전회통』 편찬', '조선의 마지막 통일 법전인 『대전회통』을 편찬했다.', 3, '흩어진 법령을 정리해 통치 기준을 세웠다.'),
('heungseon-daewongun-3', 'heungseon-daewongun', 1865, '경복궁 중건', '임진왜란 때 불탄 경복궁을 다시 짓기 위해 원납전을 걷고 백성을 대규모로 동원했다.', -2, '왕실 권위는 회복했으나 재정 압박과 민생 부담이 컸다.'),
('heungseon-daewongun-4', 'heungseon-daewongun', 1866, '병인박해', '프랑스 신부 9명과 수천 명의 천주교도를 처형했다.', -6, '대규모 종교 박해로 많은 생명을 잃었고 병인양요의 원인이 되었다.'),
('heungseon-daewongun-5', 'heungseon-daewongun', 1866, '당백전 발행', '경복궁 중건 비용을 마련하려고 액면가가 상평통보의 100배인 당백전을 발행했다.', -5, '물가가 폭등해 백성의 생활이 크게 어려워졌다.'),
('heungseon-daewongun-6', 'heungseon-daewongun', 1871, '서원 철폐', '전국 서원 가운데 47곳만 남기고 나머지를 철폐했다.', 4, '면세·면역 특권과 붕당의 근거지를 정리해 국가 재정을 늘렸다.'),
('heungseon-daewongun-7', 'heungseon-daewongun', 1871, '호포제 실시', '양반에게도 군포를 집 단위로 거두는 호포제를 실시했다.', 4, '신분에 따른 군역 불평등을 줄였다.'),
('heungseon-daewongun-8', 'heungseon-daewongun', 1871, '척화비 건립', '신미양요 뒤 서양과의 통상 수교를 거부하는 척화비를 전국에 세웠다.', -4, '통상 거부 정책을 굳혀 근대 문물 수용과 대외 대응을 늦추었다.'),
('gojong-1', 'gojong', 1876, '강화도조약 체결', '일본과 강화도조약을 맺어 부산 등 항구를 열었다.', -5, '치외법권과 해안 측량권을 허용한 불평등조약으로 일본 침투의 발판이 됐다.'),
('gojong-2', 'gojong', 1880, '통리기무아문 설치', '개화 정책을 총괄하는 통리기무아문을 설치하고 신식 군대인 별기군을 창설했다.', 3, '근대 제도 도입의 첫걸음이었으나 반발 속에 성과는 제한적이었다.'),
('gojong-3', 'gojong', 1894, '청군 파병 요청', '동학농민운동을 진압하기 위해 청에 군대 파견을 요청했다.', -6, '일본군도 출병하는 빌미가 되어 청일전쟁이 국내에서 벌어지고 일본의 내정 간섭이 강화됐다.'),
('gojong-4', 'gojong', 1896, '아관파천', '을미사변 이후 러시아 공사관으로 거처를 옮겨 약 1년간 머물렀다.', -4, '러시아의 영향력이 커지고 열강에 광산·철도 등 이권이 대거 넘어갔다.'),
('gojong-5', 'gojong', 1897, '대한제국 선포와 광무개혁', '경운궁으로 환궁해 대한제국을 선포하고 황제로 즉위한 뒤 광무개혁을 추진했다.', 5, '자주 국가임을 대외에 밝히고 양전 사업과 지계 발급, 근대 산업 육성을 추진했다.'),
('gojong-6', 'gojong', 1898, '독립협회 강제 해산', '만민공동회를 열어 개혁을 요구하던 독립협회를 강제로 해산시켰다.', -4, '민권과 의회 설립을 요구하던 정치 개혁 운동이 꺾이고 전제 황권 체제가 굳어졌다.'),
('gojong-7', 'gojong', 1907, '헤이그 특사 파견', '을사늑약의 부당함을 알리기 위해 헤이그 만국평화회의에 특사를 파견했다.', 3, '국권 침탈의 불법성을 국제사회에 호소했으나 회의 참석이 거부됐고 일본은 이를 구실로 퇴위를 강요했다.'),
('sunjong-1', 'sunjong', 1907, '한일신협약 체결', '통감이 내정 전반을 지휘하고 일본인을 각 부 차관에 임명하는 한일신협약이 체결됐다.', -4, '고종 퇴위 직후 일본의 강요로 재가되어 대한제국 행정이 통감부의 통제 아래 들어갔다.'),
('sunjong-2', 'sunjong', 1907, '대한제국 군대 해산', '한일신협약의 부속 각서에 따라 대한제국 군대를 해산하는 조칙이 내려졌다.', -4, '일본의 요구로 재가되어 국가 방위력이 사라졌고, 해산 군인들이 의병에 합류했다.'),
('sunjong-3', 'sunjong', 1909, '기유각서 체결', '사법권과 감옥 사무를 일본에 넘기는 기유각서가 체결됐다.', -3, '사법권이 일본으로 넘어가 국민이 일본의 사법 통제 아래 놓였다.'),
('sunjong-4', 'sunjong', 1910, '경찰권 위탁', '대한제국의 경찰 사무를 일본에 위탁하는 각서가 체결됐다.', -2, '치안권까지 넘어가 병합을 막을 수단이 사실상 남지 않았다.'),
('sunjong-5', 'sunjong', 1910, '국권 피탈', '순종 명의의 전권위임장으로 한일병합조약이 체결·공포되어 대한제국이 멸망했다.', -5, '실권 없는 황제였으나 재위 중 나라를 잃어 35년간의 식민 지배가 시작됐다.'),
('leewanyong-1', 'leewanyong', 1896, '독립협회 창립 참여', '독립협회 창립에 참여해 초대 위원장을 맡았다.', 2, '독립문 건립 등 자주 독립 의식을 높이는 활동에 관여했다.'),
('leewanyong-2', 'leewanyong', 1905, '을사늑약 찬성', '학부대신으로서 외교권을 일본에 넘기는 을사늑약에 찬성했다.', -9, '대한제국이 외교권을 잃고 통감부가 설치되어 보호국으로 전락했다.'),
('leewanyong-3', 'leewanyong', 1907, '고종 퇴위 강요', '헤이그 특사 사건 후 일본과 함께 고종에게 퇴위를 압박했다.', -6, '국권 회복을 시도하던 황제가 물러나고 일본의 통제가 강화됐다.'),
('leewanyong-4', 'leewanyong', 1907, '한일신협약 체결', '총리대신으로서 이토 히로부미와 한일신협약에 서명했다.', -8, '일본인 차관이 행정을 장악하고 군대 해산으로 이어졌다.'),
('leewanyong-5', 'leewanyong', 1910, '한일병합조약 체결', '총리대신으로서 데라우치 마사타케와 한일병합조약에 서명했다.', -10, '대한제국이 멸망하고 35년간의 식민 지배가 시작됐다.'),
('kimgu-1', 'kimgu', 1919, '임시정부 경무국장 취임', '상하이 대한민국 임시정부에서 초대 경무국장을 맡았다.', 3, '초기 임시정부의 조직과 보안을 맡아 정부 운영의 기반을 다졌다.'),
('kimgu-2', 'kimgu', 1931, '한인애국단 조직', '일제 요인 처단을 목표로 하는 한인애국단을 조직했다.', 4, '침체된 임시정부의 독립운동에 새로운 활로를 열었다.'),
('kimgu-3', 'kimgu', 1932, '윤봉길 의거 지휘', '한인애국단원 윤봉길의 상하이 훙커우 공원 의거를 계획·지휘했다.', 7, '독립 의지를 국제적으로 알렸고 중국 국민당 정부가 임시정부를 지원하는 계기가 됐다.'),
('kimgu-4', 'kimgu', 1940, '한국광복군 창설', '충칭의 임시정부가 정규군인 한국광복군을 창설했다.', 6, '임시정부가 독자적 군사력을 갖추어 연합군과 함께 대일 항전에 참여할 수 있게 됐다.'),
('kimgu-5', 'kimgu', 1941, '대일 선전포고', '태평양전쟁 발발 직후 임시정부 주석으로서 일본에 선전포고했다.', 3, '임시정부가 연합국 측 교전 주체임을 대외에 밝혔다.'),
('kimgu-6', 'kimgu', 1947, '백범일지 간행', '자서전 「백범일지」를 국내에서 출간했다.', 2, '독립운동의 과정을 기록해 후대에 중요한 역사 자료로 남았다.'),
('leeseungman-1', 'leeseungman', 1948, '대한민국 정부 수립', '초대 대통령에 선출되어 대한민국 정부 수립을 선포했다.', 7, '민주공화국 헌법에 기초한 정부가 출범하고 유엔 총회의 승인을 받았다.'),
('leeseungman-2', 'leeseungman', 1949, '농지개혁법 제정', '유상매수·유상분배 방식의 농지개혁법을 제정해 시행했다.', 7, '지주제가 해체되고 다수 농민이 자기 땅을 갖게 되어 이후 사회 변화의 기반이 됐다.'),
('leeseungman-3', 'leeseungman', 1949, '반민특위 무력화', '친일 행위자를 처벌하던 반민족행위특별조사위원회가 경찰의 습격과 정부의 반대 속에 해체됐다.', -5, '친일 청산이 좌절되어 다수의 친일 인사가 처벌받지 않고 요직에 남았다.'),
('leeseungman-4', 'leeseungman', 1950, '국민보도연맹 학살', '한국전쟁 초기 군경이 국민보도연맹원 등 민간인을 재판 없이 집단 살해했다.', -8, '수많은 민간인이 희생됐으며 진실화해위원회 조사와 법원 판결로 국가 책임이 인정됐다.'),
('leeseungman-5', 'leeseungman', 1952, '발췌개헌', '부산에서 계엄을 선포하고 국회의원을 연행한 상태에서 대통령 직선제 개헌안을 통과시켰다.', -5, '국회의 대통령 선출권을 강압적으로 바꾸어 재선의 길을 열고 의회 정치를 훼손했다.'),
('leeseungman-6', 'leeseungman', 1953, '한미상호방위조약 체결', '정전 직후 미국과 한미상호방위조약을 체결했다.', 7, '미군 주둔의 법적 근거가 마련되어 이후 장기간 안보와 경제 성장의 바탕이 됐다.'),
('leeseungman-7', 'leeseungman', 1954, '사사오입 개헌', '의결 정족수에 한 표 모자라 부결된 개헌안을 사사오입 논리로 번복해 통과시켰다.', -6, '초대 대통령의 중임 제한을 없애 장기 집권을 가능하게 하고 헌법 절차를 무력화했다.'),
('leeseungman-8', 'leeseungman', 1960, '3·15 부정선거와 하야', '정부와 자유당이 3·15 정·부통령 선거에서 대규모 부정을 저질렀고, 4·19 혁명으로 이승만은 하야했다.', -7, '선거 제도가 무너졌고 항의 시위 진압 과정에서 다수의 시민이 사망했다.'),
('yunboseon-1', 'yunboseon', 1960, '제4대 대통령 선출', '4·19 혁명 후 개정된 헌법에 따라 국회에서 내각책임제의 대통령으로 선출됐다.', 2, '헌법 절차에 따라 제2공화국 정부가 구성되는 데 참여했다.'),
('yunboseon-2', 'yunboseon', 1961, '5·16 군사정변 진압 건의 거부', '5·16 군사정변 당시 유엔군 사령관의 진압 건의에 동의하지 않고 군정 아래 대통령직에 유임했다.', -3, '헌정을 중단시킨 군사정권이 기존 국가원수를 유지하며 체제를 안착시키는 결과로 이어졌다.'),
('yunboseon-3', 'yunboseon', 1962, '대통령직 사임', '정치인의 활동을 금지한 정치활동정화법에 반대해 대통령직에서 물러났다.', 2, '군사정권의 정치 활동 제한에 항의하는 뜻을 공개적으로 밝혔다.'),
('yunboseon-4', 'yunboseon', 1976, '3·1 민주구국선언 참여', '김대중·함석헌 등과 함께 유신체제를 비판하는 3·1 민주구국선언에 서명했다.', 2, '긴급조치 아래 민주주의 회복을 공개 요구했으며 이로 인해 기소됐다.'),
('parkchunghee-1', 'parkchunghee', 1961, '5·16 군사정변', '군을 동원해 정변을 일으켜 장면 내각을 무너뜨리고 국가재건최고회의를 통해 권력을 잡았다.', -8, '헌법에 따라 구성된 정부와 국회가 무력으로 해산되고 군정이 시작됐다.'),
('parkchunghee-2', 'parkchunghee', 1962, '경제개발 5개년 계획', '제1차 경제개발 5개년 계획을 시작해 수출 주도 공업화를 추진했다.', 8, '이후 연이은 계획을 통해 장기간 고도성장이 이어지고 산업 구조가 바뀌었다.'),
('parkchunghee-3', 'parkchunghee', 1965, '한일기본조약 체결', '일본과 한일기본조약을 맺어 국교를 정상화하고 청구권 자금을 받았다.', 2, '자금이 경제개발에 투입됐으나 식민 지배 책임과 개인 배상 문제를 명확히 하지 않아 이후 분쟁의 원인이 됐다.'),
('parkchunghee-4', 'parkchunghee', 1969, '3선 개헌', '대통령의 3회 연임을 허용하는 개헌안을 야당 의원이 없는 가운데 국회 별관에서 기습 처리하고 국민투표로 확정했다.', -5, '중임 제한을 무력화해 장기 집권의 길을 열었다.'),
('parkchunghee-5', 'parkchunghee', 1970, '경부고속도로 개통', '서울과 부산을 잇는 경부고속도로를 개통했다.', 5, '전국 물류와 산업 입지를 바꾸어 이후 경제 성장의 기반 시설이 됐다.'),
('parkchunghee-6', 'parkchunghee', 1972, '10월 유신', '비상계엄을 선포하고 국회를 해산한 뒤 대통령 간선제와 긴급조치권을 담은 유신헌법을 제정했다.', -8, '삼권분립과 기본권이 무력화된 체제가 7년간 이어졌다.'),
('parkchunghee-7', 'parkchunghee', 1973, '중화학공업화 선언', '철강·조선·기계·화학 등 중화학공업을 집중 육성하는 정책을 선언했다.', 6, '이후 한국 주력 산업의 토대가 마련됐다.'),
('parkchunghee-8', 'parkchunghee', 1975, '인혁당 재건위 사건 사형 집행', '인민혁명당 재건위원회 사건 관련자 8명을 대법원 판결 18시간 만에 사형 집행했다.', -7, '2007년 재심에서 전원 무죄가 선고되어 무고한 사람들이 국가에 의해 처형된 것으로 확인됐다.'),
('choikyuhah-1', 'choikyuhah', 1979, '긴급조치 9호 해제', '대통령 취임 직후 긴급조치 9호를 해제하고 관련 구속자를 석방했다.', 3, '유신체제 아래 기본권 제한이 일부 풀렸다.'),
('choikyuhah-2', 'choikyuhah', 1979, '정승화 연행 사후 재가', '12·12 군사반란 당시 신군부의 요구에 따라 계엄사령관 정승화의 연행을 사후 재가했다.', -4, '신군부의 군권 장악이 형식상 승인되는 결과를 낳았다.'),
('choikyuhah-3', 'choikyuhah', 1980, '정치인 복권', '김대중 등 유신체제에서 처벌받은 인사들의 공민권을 회복시켰다.', 2, '정치 활동 재개의 길이 열렸으나 이후 신군부에 의해 다시 막혔다.'),
('choikyuhah-4', 'choikyuhah', 1980, '비상계엄 전국 확대', '신군부의 요구로 국무회의에서 비상계엄을 전국으로 확대하는 안이 의결됐다.', -5, '정치 활동이 금지되고 광주에서 유혈 진압으로 이어졌다.'),
('choikyuhah-5', 'choikyuhah', 1980, '대통령직 사임', '신군부의 압력 속에 대통령직에서 물러났다.', -3, '전두환이 통일주체국민회의에서 대통령으로 선출되는 길이 열렸다.'),
('choikyuhah-6', 'choikyuhah', 1996, '법정 증언 거부', '12·12 및 5·18 사건 재판에 증인으로 소환됐으나 증언을 거부했다.', -2, '핵심 사건의 진상 규명에 필요한 증언이 남지 않았다.'),
('chundoohwan-1', 'chundoohwan', 1979, '12·12 군사반란', '보안사령관으로서 하나회 중심의 군 병력을 동원해 계엄사령관을 강제 연행하고 군권을 장악했다.', -8, '군 지휘 체계를 무력으로 무너뜨렸으며 대법원은 이를 반란으로 판결했다.'),
('chundoohwan-2', 'chundoohwan', 1980, '5·17 내란과 광주 유혈 진압', '비상계엄을 전국으로 확대하고 광주의 민주화 시위를 계엄군으로 진압했다.', -9, '다수의 시민이 사망했으며 대법원은 이를 내란 및 내란목적살인으로 판결했다.'),
('chundoohwan-3', 'chundoohwan', 1980, '삼청교육대 운영', '사회 정화를 명분으로 수만 명을 영장 없이 연행해 삼청교육대에 수용했다.', -6, '가혹 행위로 사망자와 다수의 부상자가 발생했고 이후 국가 배상 책임이 인정됐다.'),
('chundoohwan-4', 'chundoohwan', 1980, '언론 통폐합', '신문사와 방송사를 강제로 통폐합하고 다수의 언론인을 해직시켰다.', -5, '언론의 자유가 크게 위축되고 보도 지침에 따른 통제가 이어졌다.'),
('chundoohwan-5', 'chundoohwan', 1982, '야간통행금지 해제', '1945년부터 이어진 야간통행금지를 해제했다.', 3, '시민의 일상 활동 제약이 풀렸다.'),
('chundoohwan-6', 'chundoohwan', 1982, '물가 안정', '긴축 재정과 임금 억제 정책으로 20%대이던 물가상승률을 한 자릿수로 낮추었다.', 4, '고물가가 진정되어 이후 1980년대 중반 경제 성장의 바탕이 됐다.'),
('chundoohwan-7', 'chundoohwan', 1987, '4·13 호헌 조치', '대통령 직선제 개헌 논의를 중단하고 현행 헌법으로 다음 정부를 선출하겠다고 발표했다.', -4, '전국적인 반발을 불러 6월 민주항쟁으로 이어졌다.'),
('chundoohwan-8', 'chundoohwan', 1997, '뇌물수수 유죄 확정', '재임 중 기업들로부터 거액의 뇌물을 받아 비자금을 조성한 사실이 대법원에서 확정되어 2205억 원 추징이 선고됐다.', -6, '권력을 이용한 대규모 부패가 사법적으로 확인됐다.'),
('rohtaewoo-1', 'rohtaewoo', 1979, '12·12 군사반란 가담', '9사단장으로서 병력을 서울로 이동시켜 12·12 군사반란에 가담했다.', -7, '신군부 집권의 핵심 역할을 했으며 대법원은 반란과 내란 혐의를 유죄로 판결했다.'),
('rohtaewoo-2', 'rohtaewoo', 1987, '6·29 선언', '여당 대통령 후보로서 대통령 직선제 개헌을 수용하는 6·29 선언을 발표했다.', 6, '직선제 개헌으로 현행 헌법 체제가 마련됐다.'),
('rohtaewoo-3', 'rohtaewoo', 1988, '서울 올림픽 개최', '제24회 서울 하계올림픽을 개최했다.', 4, '동서 진영이 함께 참가한 대회로 한국의 국제적 위상이 높아졌다.'),
('rohtaewoo-4', 'rohtaewoo', 1990, '한소 수교', '북방정책에 따라 소련과 국교를 수립했다.', 5, '냉전기 적대 관계를 해소하고 외교 범위를 넓혔다.'),
('rohtaewoo-5', 'rohtaewoo', 1991, '남북 유엔 동시 가입과 기본합의서', '남북한이 유엔에 동시 가입하고 남북기본합의서를 채택했다.', 5, '남북이 서로의 체제를 인정하고 교류 협력의 원칙을 처음으로 문서화했다.'),
('rohtaewoo-6', 'rohtaewoo', 1992, '한중 수교', '중국과 국교를 수립했다.', 6, '이후 중국이 최대 교역국이 되는 등 경제·외교에 장기적 영향을 끼쳤다.'),
('rohtaewoo-7', 'rohtaewoo', 1997, '뇌물수수 유죄 확정', '재임 중 기업들로부터 거액의 뇌물을 받아 비자금을 조성한 사실이 대법원에서 확정되어 2628억 원 추징이 선고됐다.', -6, '권력을 이용한 대규모 부패가 사법적으로 확인됐다.'),
('kimyoungsam-1', 'kimyoungsam', 1993, '하나회 해체', '군내 사조직인 하나회 출신 장성들을 대거 보직 해임했다.', 6, '군의 정치 개입 통로가 차단되어 문민 통제가 자리 잡았다.'),
('kimyoungsam-2', 'kimyoungsam', 1993, '금융실명제 실시', '대통령 긴급재정경제명령으로 금융실명제를 전격 실시했다.', 7, '차명·가명 거래가 금지되어 금융 거래의 투명성이 크게 높아졌다.'),
('kimyoungsam-3', 'kimyoungsam', 1995, '지방자치 전면 실시', '광역·기초 단체장과 의원을 동시에 뽑는 전국동시지방선거를 실시했다.', 6, '지방자치단체장 직선제가 정착되어 지방 자치가 제도화됐다.'),
('kimyoungsam-4', 'kimyoungsam', 1995, '5·18 특별법 제정', '5·18 민주화운동 등에 관한 특별법을 제정해 전두환·노태우를 기소하게 했다.', 5, '군사반란과 내란에 대한 사법 처벌이 이루어졌다.'),
('kimyoungsam-5', 'kimyoungsam', 1996, 'OECD 가입', '경제협력개발기구에 가입했다.', 2, '선진 경제 체제에 편입됐으나 자본시장 개방이 빨라져 외환 관리 부담이 커졌다.'),
('kimyoungsam-6', 'kimyoungsam', 1997, '차남 김현철 구속', '차남 김현철이 한보 사태 수사 과정에서 알선수재와 조세포탈 혐의로 구속됐다.', -2, '대통령 친인척 비리로 국정 신뢰가 떨어졌다.'),
('kimyoungsam-7', 'kimyoungsam', 1997, '외환위기와 IMF 구제금융', '외환보유고가 바닥나 국제통화기금에 구제금융을 신청했다.', -8, '기업 연쇄 도산과 대량 실업이 발생해 국민 생활에 큰 타격을 주었다.'),
('kimdaejung-1', 'kimdaejung', 1998, '외환위기 수습과 구조조정', '금융·기업·공공·노동 부문 구조조정을 추진하고 2001년 IMF 차입금을 조기 상환했다.', 6, '국가 부도 위기에서 벗어났으나 그 과정에서 대량 실업과 비정규직 증가가 뒤따랐다.'),
('kimdaejung-2', 'kimdaejung', 1998, '한일 공동선언', '일본 총리와 한일 파트너십 공동선언을 발표하고 일본 대중문화를 단계적으로 개방했다.', 4, '일본의 식민 지배 사과를 문서에 담고 양국 교류가 확대됐다.'),
('kimdaejung-3', 'kimdaejung', 1999, '국민기초생활보장법 제정', '최저생계비 이하 국민에게 생계를 보장하는 국민기초생활보장법을 제정했다.', 6, '근로 능력과 관계없이 최저생활을 국가가 보장하는 복지 제도의 기틀이 마련됐다.'),
('kimdaejung-4', 'kimdaejung', 2000, '대북 불법 송금', '남북정상회담을 전후해 현대그룹을 통한 대북 송금에 국가정보원 등이 불법적으로 관여했다.', -4, '2003년 특검 수사로 드러나 관련 고위 인사들이 유죄 판결을 받았다.'),
('kimdaejung-5', 'kimdaejung', 2000, '6·15 남북정상회담', '평양에서 분단 후 첫 남북정상회담을 열고 6·15 남북공동선언을 발표했다.', 6, '이산가족 상봉과 경제 협력 등 남북 교류가 크게 확대됐다.'),
('kimdaejung-6', 'kimdaejung', 2001, '국가인권위원회 설립', '독립 국가기관인 국가인권위원회를 설립했다.', 4, '인권 침해와 차별을 조사·구제하는 상설 기구가 생겼다.'),
('kimdaejung-7', 'kimdaejung', 2002, '아들들의 비리 구속', '두 아들 김홍업과 김홍걸이 금품 수수 등 비리로 구속됐다.', -2, '대통령 친인척 비리로 국정 신뢰가 떨어졌다.'),
('rohmoohyun-1', 'rohmoohyun', 2003, '측근 불법 정치자금 수수', '최도술 전 총무비서관과 안희정 등 측근들이 불법 정치자금 수수로 유죄 판결을 받았다.', -3, '대선 자금을 둘러싼 불법이 사법적으로 확인됐다.'),
('rohmoohyun-2', 'rohmoohyun', 2004, '국가균형발전특별법 제정', '국가균형발전특별법을 제정하고 행정중심복합도시와 혁신도시 건설을 추진했다.', 4, '행정기관과 공공기관이 지방으로 이전해 세종시와 혁신도시가 조성됐다.'),
('rohmoohyun-3', 'rohmoohyun', 2004, '선거 중립 의무 위반과 탄핵소추', '특정 정당 지지 발언으로 국회에서 탄핵소추됐고 헌법재판소는 선거 중립 의무 위반을 인정하되 탄핵은 기각했다.', -2, '대통령 직무가 두 달간 정지되는 국정 공백이 생겼다.'),
('rohmoohyun-4', 'rohmoohyun', 2005, '과거사정리기본법 제정', '진실·화해를 위한 과거사정리기본법을 제정해 진실화해위원회를 설치했다.', 3, '국가 폭력 사건의 조사와 피해자 구제, 재심의 근거가 마련됐다.'),
('rohmoohyun-5', 'rohmoohyun', 2007, '한미 FTA 타결', '미국과 자유무역협정 협상을 타결하고 협정에 서명했다.', 5, '최대 교역국 중 하나와 무역 장벽을 낮추는 장기적 통상 체제가 마련됐다.'),
('rohmoohyun-6', 'rohmoohyun', 2007, '10·4 남북공동선언', '평양에서 제2차 남북정상회담을 열고 10·4 남북공동선언을 발표했다.', 3, '경제 협력 확대에 합의했으나 정권 교체 후 대부분 이행되지 않았다.'),
('qin-shi-huang-1', 'qin-shi-huang', -221, '6국 통일', '한·조·위·초·연·제를 차례로 멸하고 중국 최초의 통일 제국을 세웠다.', 9, '이후 2천 년 넘게 이어진 통일 중국이라는 정치적 틀의 출발점이 되었다.'),
('qin-shi-huang-2', 'qin-shi-huang', -221, '군현제 실시', '봉건제를 폐지하고 전국을 군과 현으로 나누어 중앙에서 관리를 파견했다.', 7, '중앙집권적 관료 통치의 기본 구조로 후대 왕조에 계승되었다.'),
('qin-shi-huang-3', 'qin-shi-huang', -221, '문자·도량형·화폐 통일', '지역마다 달랐던 문자와 도량형, 화폐를 하나로 통일했다.', 8, '광대한 지역의 행정·경제·문화 통합을 가능하게 한 장기적 기반이 되었다.'),
('qin-shi-huang-4', 'qin-shi-huang', -214, '만리장성 연결 축조', '흉노를 막기 위해 기존 성벽들을 잇는 대규모 장성 공사를 벌였다.', -3, '북방 방어에 기여했으나 대규모 강제 노역으로 많은 백성이 희생되었다.'),
('qin-shi-huang-5', 'qin-shi-huang', -213, '분서', '의약·점복·농업 서적을 제외한 민간의 사서와 제자백가 서적을 불태우게 했다.', -6, '사상과 학문의 자유를 억압하고 많은 고대 문헌을 소실시켰다.'),
('qin-shi-huang-6', 'qin-shi-huang', -212, '갱유', '황제를 비방했다는 이유로 수백 명의 학자를 생매장했다.', -5, '지식인에 대한 공포 정치로 비판을 봉쇄했다.'),
('emperor-wu-han-1', 'emperor-wu-han', -139, '장건의 서역 파견', '월지와 동맹을 맺기 위해 장건을 서역에 파견했다.', 8, '동서 교역로인 비단길이 열리는 계기가 되어 유라시아 교류에 장기적 영향을 주었다.'),
('emperor-wu-han-2', 'emperor-wu-han', -136, '오경박사 설치', '오경박사를 두어 유학을 국가의 공식 학문으로 삼았다.', 7, '유교가 이후 2천 년간 중국과 동아시아의 통치 이념이 되는 토대를 놓았다.'),
('emperor-wu-han-3', 'emperor-wu-han', -119, '막북 전투 승리', '위청과 곽거병을 보내 흉노 본거지를 공격해 크게 이겼다.', 5, '흉노의 위협을 크게 줄였으나 거듭된 원정으로 막대한 인명과 재정이 소모되었다.'),
('emperor-wu-han-4', 'emperor-wu-han', -108, '고조선 멸망과 한사군 설치', '고조선을 침공해 멸망시키고 그 땅에 낙랑군 등 4군을 설치했다.', -7, '한반도 최초의 국가를 무너뜨리고 그 주민을 이민족 지배 아래 두었다.'),
('emperor-wu-han-5', 'emperor-wu-han', -91, '무고의 화', '저주 사건을 빌미로 한 수사 과정에서 태자 유거가 죽고 수만 명이 연루되어 죽었다.', -6, '황실과 조정이 크게 흔들리고 무고한 사람들이 대량으로 희생되었다.'),
('emperor-wu-han-6', 'emperor-wu-han', -89, '윤대의 조', '무리한 원정과 사치를 스스로 반성하는 조서를 내리고 백성을 쉬게 하는 정책으로 돌아섰다.', 2, '정책 전환으로 민생 회복의 계기를 마련했다.'),
('taizong-tang-1', 'taizong-tang', 626, '현무문의 변', '현무문에서 형 이건성과 동생 이원길을 죽이고 태자가 된 뒤 즉위했다.', -4, '골육상쟁으로 권력을 잡아 왕위 계승의 정당성을 무너뜨렸다.'),
('taizong-tang-2', 'taizong-tang', 630, '동돌궐 정벌', '동돌궐을 멸망시키고 북방 유목민들로부터 ''천가한'' 칭호를 받았다.', 5, '오랜 북방 위협을 제거하고 당의 대외적 안정과 교류를 넓혔다.'),
('taizong-tang-3', 'taizong-tang', 637, '정관률 반포', '수의 법률을 정비해 형벌을 완화한 정관률을 반포했다.', 5, '당 율령 체계의 기초가 되어 동아시아 여러 나라의 법제에 영향을 주었다.'),
('taizong-tang-4', 'taizong-tang', 641, '문성공주 출가', '문성공주를 토번의 송첸캄포에게 시집보내 화친을 맺었다.', 3, '토번과의 평화 관계와 문화 교류를 촉진했다.'),
('taizong-tang-5', 'taizong-tang', 645, '고구려 침공', '대군을 이끌고 고구려를 침공했으나 안시성에서 막혀 철수했다.', -6, '명분 없는 침략으로 고구려와 당 양국에 큰 인명 피해를 냈다.'),
('wu-zetian-1', 'wu-zetian', 655, '황후 책봉과 경쟁자 제거', '고종의 황후가 된 뒤 폐위된 왕황후와 소숙비를 죽였다.', -4, '궁중 암투 속에서 잔혹한 방식으로 권력을 다졌다.'),
('wu-zetian-2', 'wu-zetian', 686, '밀고 장려와 혹리 등용', '투서함을 설치해 밀고를 장려하고 내준신 등 혹리를 등용했다.', -6, '수많은 관료와 황족이 모함으로 처형되는 공포 정치를 낳았다.'),
('wu-zetian-3', 'wu-zetian', 690, '전시 실시', '황제가 직접 과거 응시자를 시험하는 전시를 처음 실시했다.', 5, '문벌 귀족 대신 과거 출신 인재를 등용하는 흐름을 강화했다.'),
('wu-zetian-4', 'wu-zetian', 692, '안서 4진 회복', '왕효걸을 보내 토번에 빼앗긴 서역의 안서 4진을 되찾았다.', 3, '서역 교역로의 안정을 되찾았다.'),
('wu-zetian-5', 'wu-zetian', 702, '무과 설치', '무예로 인재를 뽑는 무거를 처음 설치했다.', 3, '군사 인재 선발을 제도화해 후대 왕조로 이어졌다.'),
('kublai-khan-1', 'kublai-khan', 1260, '중통초 발행', '지폐인 중통원보교초를 발행해 전국 통화로 삼았다.', 3, '넓은 제국의 상거래를 원활하게 했다.'),
('kublai-khan-2', 'kublai-khan', 1267, '대도 건설', '오늘날 베이징 자리에 새 수도 대도의 건설을 시작했다.', 4, '이후 베이징이 중국의 정치 중심지가 되는 기초를 놓았다.'),
('kublai-khan-3', 'kublai-khan', 1269, '파스파 문자 제정', '티베트 승려 파스파에게 명해 새 문자를 만들어 국자로 반포했다.', 2, '다민족 제국의 표기 통일을 시도했으나 널리 쓰이지는 못했다.'),
('kublai-khan-4', 'kublai-khan', 1274, '1차 일본 원정', '고려에 배와 군사를 만들게 해 일본을 침공했으나 실패했다.', -5, '고려 백성에게 막대한 징발 부담을 지우고 많은 병사가 희생되었다.'),
('kublai-khan-5', 'kublai-khan', 1279, '남송 정복', '애산 전투로 남송을 완전히 멸망시켜 중국 전역을 지배했다.', 4, '오랜 분열을 끝내 중국을 재통일했으나 정복 전쟁에서 많은 희생이 따랐다.'),
('kublai-khan-6', 'kublai-khan', 1281, '2차 일본 원정', '고려와 옛 남송의 대군을 동원해 다시 일본을 침공했으나 태풍 등으로 대패했다.', -5, '고려에 거듭된 동원 부담을 지우고 수많은 병사가 목숨을 잃었다.'),
('kublai-khan-7', 'kublai-khan', 1293, '통혜하 완공', '대도와 대운하를 잇는 통혜하를 완공했다.', 4, '강남의 곡물을 수도로 운반하는 물류망을 완성했다.'),
('hongwu-emperor-1', 'hongwu-emperor', 1368, '명 건국', '원을 북쪽으로 몰아내고 난징에서 명을 세웠다.', 8, '오랜 전란을 끝내고 약 3백 년 지속된 왕조를 열었다.'),
('hongwu-emperor-2', 'hongwu-emperor', 1371, '해금령', '민간의 해상 무역과 출항을 금지하는 해금 정책을 시행했다.', -4, '대외 교역을 위축시키고 밀무역과 왜구 문제를 키웠다.'),
('hongwu-emperor-3', 'hongwu-emperor', 1380, '호유용의 옥', '재상 호유용을 반역죄로 처형하고 연루자 수만 명을 죽인 뒤 재상제를 폐지했다.', -7, '대규모 숙청으로 무고한 희생을 낳고 황제 독재 체제를 굳혔다.'),
('hongwu-emperor-4', 'hongwu-emperor', 1381, '이갑제와 부역황책', '이갑제를 시행하고 전국 호구를 조사한 부역황책을 만들었다.', 5, '농촌 행정과 세금 징수 체계를 안정시켰다.'),
('hongwu-emperor-5', 'hongwu-emperor', 1387, '어린도책 완성', '전국 토지를 측량해 토지 대장인 어린도책을 만들었다.', 3, '토지 파악을 정확히 해 조세 공평에 기여했다.'),
('hongwu-emperor-6', 'hongwu-emperor', 1393, '남옥의 옥', '장군 남옥을 모반죄로 처형하고 1만 5천여 명을 연좌시켜 죽였다.', -6, '개국 공신과 무장들을 대량 학살해 공포 정치를 이어갔다.'),
('hongwu-emperor-7', 'hongwu-emperor', 1397, '대명률 반포', '여러 차례 수정한 대명률을 최종 반포했다.', 5, '명·청과 조선 등 주변국 법제의 기준이 되었다.'),
('yongle-emperor-1', 'yongle-emperor', 1399, '정난의 변', '번왕 삭감에 반발해 군사를 일으켜 조카 건문제와 3년간 내전을 벌였다.', -5, '내전으로 많은 인명이 희생되고 제위를 무력으로 찬탈했다.'),
('yongle-emperor-2', 'yongle-emperor', 1402, '건문제 측근 숙청', '즉위 후 방효유의 일족 등 건문제의 신하와 그 가족을 대량 처형했다.', -5, '반대 세력에 대한 잔혹한 연좌 처형으로 많은 사람이 희생되었다.'),
('yongle-emperor-3', 'yongle-emperor', 1405, '정화의 원정', '정화에게 대함대를 맡겨 동남아시아와 인도양, 아프리카 동해안까지 원정하게 했다.', 6, '아시아·아프리카 각지와의 외교·교역 관계를 넓혔다.'),
('yongle-emperor-4', 'yongle-emperor', 1407, '베트남 침공과 병합', '베트남의 호 왕조를 무너뜨리고 그 땅을 명의 직할령으로 삼았다.', -4, '베트남 사람들의 거센 저항을 불렀고 결국 명도 20여 년 만에 철수했다.'),
('yongle-emperor-5', 'yongle-emperor', 1408, '영락대전 완성', '학자 2천여 명을 동원해 2만여 권에 이르는 백과사전을 완성했다.', 6, '방대한 고문헌을 집대성해 많은 서적이 후대에 전해지게 했다.'),
('yongle-emperor-6', 'yongle-emperor', 1420, '동창 설치', '환관이 지휘하는 감찰·정보 기관인 동창을 설치했다.', -4, '환관의 권력 남용과 공포 정치의 기반이 되었다.'),
('yongle-emperor-7', 'yongle-emperor', 1421, '베이징 천도', '자금성을 완공하고 수도를 난징에서 베이징으로 옮겼다.', 5, '북방 방어를 강화했고 베이징이 이후 중국의 수도로 이어졌다.'),
('kangxi-emperor-1', 'kangxi-emperor', 1681, '삼번의 난 진압', '오삼계 등 한족 번왕들이 일으킨 8년간의 반란을 진압했다.', 6, '내전을 끝내고 청의 전국 통치를 안정시켰다.'),
('kangxi-emperor-2', 'kangxi-emperor', 1683, '대만 편입', '정씨 세력을 굴복시키고 대만을 청의 영토로 편입했다.', 4, '동남 해안의 전란을 끝내고 대만을 중국 행정 체계에 넣었다.'),
('kangxi-emperor-3', 'kangxi-emperor', 1684, '해금 해제', '해상 무역 금지를 풀고 해관을 설치해 대외 무역을 허용했다.', 4, '연해 지역의 경제를 되살리고 교역을 활성화했다.'),
('kangxi-emperor-4', 'kangxi-emperor', 1689, '네르친스크 조약', '러시아와 조약을 맺어 헤이룽강 일대의 국경을 정했다.', 5, '중국이 유럽 국가와 맺은 최초의 대등한 국경 조약으로 북방 분쟁을 해소했다.'),
('kangxi-emperor-5', 'kangxi-emperor', 1712, '인두세 고정', '이후 늘어나는 인구에 대해서는 인두세를 더 걷지 않겠다고 선포했다.', 6, '백성의 세금 부담을 줄여 인구 증가와 사회 안정에 기여했다.'),
('kangxi-emperor-6', 'kangxi-emperor', 1713, '남산집 사건', '문집에 남명의 연호를 썼다는 이유로 대명세를 처형하고 관련자를 처벌했다.', -3, '문자옥으로 지식인의 사상과 표현을 위축시켰다.'),
('kangxi-emperor-7', 'kangxi-emperor', 1716, '강희자전 완성', '4만 7천여 자를 수록한 자전을 편찬했다.', 5, '한자 연구와 사전 편찬의 표준으로 오랫동안 쓰였다.'),
('qianlong-emperor-1', 'qianlong-emperor', 1757, '준가르 정벌과 학살', '준가르를 정복하면서 그 주민 대다수를 학살하거나 죽음에 이르게 했다.', -8, '한 민족 집단이 사실상 소멸할 만큼 대규모 학살이 일어났다.'),
('qianlong-emperor-2', 'qianlong-emperor', 1757, '광저우 일구통상', '서양과의 무역을 광저우 한 곳으로 제한했다.', -4, '대외 교류를 제약해 서양 정세에 대한 대응력을 약화시켰다.'),
('qianlong-emperor-3', 'qianlong-emperor', 1759, '회부 평정', '타림 분지 일대를 평정해 신장 지역을 청의 영토로 확정했다.', 3, '청의 최대 판도를 완성해 오늘날 중국 영토의 바탕이 되었다.'),
('qianlong-emperor-4', 'qianlong-emperor', 1774, '금서 색출과 소각', '사고전서 편찬과 함께 청에 불리한 서적을 찾아내 대량으로 없애게 했다.', -5, '수많은 서적이 소실되고 문자옥으로 지식인이 탄압받았다.'),
('qianlong-emperor-5', 'qianlong-emperor', 1776, '화신 중용', '화신을 군기대신에 임명하고 20여 년간 총애했다.', -5, '화신의 막대한 부정 축재로 관료 부패가 만연해 청의 쇠퇴를 앞당겼다.'),
('qianlong-emperor-6', 'qianlong-emperor', 1782, '사고전서 완성', '3천여 종의 서적을 경·사·자·집으로 분류한 총서의 첫 세트를 완성했다.', 5, '방대한 중국 고전을 집대성해 후대에 전했다.'),
('qianlong-emperor-7', 'qianlong-emperor', 1793, '매카트니 사절단 거절', '영국 사절단의 통상 확대 요구를 거절했다.', -3, '서양과의 관계 조정 기회를 놓쳐 이후 충돌의 배경이 되었다.'),
('empress-dowager-cixi-1', 'empress-dowager-cixi', 1861, '신유정변', '공친왕과 손잡고 섭정대신들을 제거한 뒤 수렴청정을 시작했다.', -3, '정변으로 권력을 잡아 장기간의 비공식 통치를 시작했다.'),
('empress-dowager-cixi-2', 'empress-dowager-cixi', 1888, '이화원 재건', '해군 경비 등을 끌어다 이화원을 재건했다.', -4, '근대 해군 육성에 써야 할 재정을 궁원 공사에 돌렸다.'),
('empress-dowager-cixi-3', 'empress-dowager-cixi', 1898, '무술정변', '광서제의 변법 개혁을 중단시키고 황제를 유폐했으며 개혁파를 처형했다.', -7, '청의 근대화 개혁 기회를 무산시켰다.'),
('empress-dowager-cixi-4', 'empress-dowager-cixi', 1900, '의화단 지지와 열강 선전포고', '의화단을 지원하며 8개국에 선전포고했다가 베이징을 점령당했다.', -8, '막대한 인명 피해와 신축조약의 거액 배상, 외국군 주둔을 초래했다.'),
('empress-dowager-cixi-5', 'empress-dowager-cixi', 1901, '신정 개혁 착수', '서안 피난 중 조서를 내려 행정·군사·교육 개혁에 나섰다.', 4, '신식 군대와 학교 등 근대 제도 도입을 시작했다.'),
('empress-dowager-cixi-6', 'empress-dowager-cixi', 1905, '과거제 폐지', '1천 3백여 년 이어진 과거제를 폐지했다.', 5, '근대 교육 체제로 전환하는 길을 열었다.'),
('sun-yat-sen-1', 'sun-yat-sen', 1894, '흥중회 결성', '하와이에서 청 타도를 목표로 한 혁명 단체 흥중회를 조직했다.', 3, '중국 근대 혁명 운동의 출발점이 되었다.'),
('sun-yat-sen-2', 'sun-yat-sen', 1905, '중국동맹회 결성', '도쿄에서 여러 혁명 단체를 통합해 중국동맹회를 결성하고 삼민주의를 제창했다.', 6, '흩어진 혁명 세력을 하나로 모으고 공화 혁명의 이념을 제시했다.'),
('sun-yat-sen-3', 'sun-yat-sen', 1912, '중화민국 임시대총통 취임', '신해혁명 후 난징에서 중화민국 임시대총통에 취임했다.', 8, '2천 년 넘는 황제 체제를 끝내고 아시아 최초의 공화국을 세웠다.'),
('sun-yat-sen-4', 'sun-yat-sen', 1924, '제1차 국공합작', '국민당을 개편해 공산당과 합작하고 황푸군관학교를 세웠다.', 4, '군벌을 타도하고 국가를 통일하는 북벌의 기반을 만들었다.'),
('chiang-kai-shek-1', 'chiang-kai-shek', 1927, '상하이 쿠데타', '상하이에서 공산당원과 노동운동가들을 대규모로 체포·처형했다.', -6, '수많은 사람이 희생되고 오랜 국공 내전의 발단이 되었다.'),
('chiang-kai-shek-2', 'chiang-kai-shek', 1928, '북벌 완료', '베이징을 점령해 군벌 체제를 끝내고 국민정부 아래 중국을 형식상 통일했다.', 6, '분열된 중국에 중앙 정부를 다시 세웠다.'),
('chiang-kai-shek-3', 'chiang-kai-shek', 1937, '중일전쟁 항전', '일본의 전면 침공에 맞서 공산당과 다시 손잡고 장기 항전에 나섰다.', 7, '일본의 중국 정복을 막아내고 연합국 승리에 기여했다.'),
('chiang-kai-shek-4', 'chiang-kai-shek', 1938, '황허 제방 파괴', '일본군 진격을 막기 위해 화위안커우의 황허 제방을 터뜨렸다.', -7, '대홍수로 수십만 명의 민간인이 죽고 수백만 명의 난민이 생겼다.'),
('chiang-kai-shek-5', 'chiang-kai-shek', 1943, '카이로 회담', '카이로 회담에 참석해 한국 독립을 명시한 선언 채택에 참여했다.', 4, '연합국이 한국 독립을 처음 공식 약속하는 데 기여했다.'),
('chiang-kai-shek-6', 'chiang-kai-shek', 1947, '2·28 사건 진압', '대만 주민의 항의 시위를 진압하기 위해 군대를 파견했다.', -6, '진압 과정에서 수많은 대만 주민이 학살되었다.'),
('chiang-kai-shek-7', 'chiang-kai-shek', 1949, '대만 계엄령', '대만에 계엄령을 선포하고 38년간 유지했다.', -6, '장기간 정치적 자유를 억압하고 많은 사람을 투옥·처형했다.'),
('chiang-kai-shek-8', 'chiang-kai-shek', 1953, '대만 토지개혁', '경자유전 정책으로 지주의 토지를 소작농에게 분배했다.', 5, '농민 생활을 안정시키고 대만 경제 성장의 토대가 되었다.'),
('mao-zedong-1', 'mao-zedong', 1949, '중화인민공화국 수립', '국공 내전에서 승리하고 베이징에서 중화인민공화국 수립을 선포했다.', 6, '수십 년의 전란을 끝내고 통일된 중앙 정부를 세웠다.'),
('mao-zedong-2', 'mao-zedong', 1950, '혼인법 공포', '강제 결혼과 축첩을 금지하고 혼인과 이혼의 자유를 규정한 혼인법을 공포했다.', 4, '여성의 법적 지위를 크게 높였다.'),
('mao-zedong-3', 'mao-zedong', 1950, '한국전쟁 참전', '중국 인민지원군을 한반도에 파병해 전쟁에 개입했다.', -7, '전쟁을 장기화해 한국인과 중국인 등 막대한 인명 피해를 낳고 분단 고착에 영향을 주었다.'),
('mao-zedong-4', 'mao-zedong', 1957, '반우파 투쟁', '정권을 비판한 지식인들을 우파로 몰아 대규모로 숙청했다.', -6, '수십만 명이 박해를 받고 비판의 자유가 사라졌다.'),
('mao-zedong-5', 'mao-zedong', 1958, '대약진운동', '급진적 공업화와 인민공사화를 강행했다.', -10, '뒤이은 대기근으로 수천만 명이 굶어 죽었다.'),
('mao-zedong-6', 'mao-zedong', 1966, '문화대혁명', '홍위병을 동원해 10년간 정치 운동을 벌이며 반대파와 전통문화를 공격했다.', -10, '수많은 사람이 박해·살해되고 교육과 문화유산이 크게 파괴되었다.'),
('mao-zedong-7', 'mao-zedong', 1972, '닉슨 방중', '미국 대통령 닉슨을 베이징에 맞아 미중 관계 개선의 길을 열었다.', 4, '냉전 구도를 바꾸고 중국이 국제 사회로 나오는 계기가 되었다.'),
('deng-xiaoping-1', 'deng-xiaoping', 1978, '개혁개방', '중국공산당 11기 3중전회에서 개혁개방 노선을 확정했다.', 9, '중국 경제를 급성장시키고 수억 명을 빈곤에서 벗어나게 했다.'),
('deng-xiaoping-2', 'deng-xiaoping', 1979, '중월전쟁', '베트남을 침공해 한 달간 전쟁을 벌였다.', -4, '양국에 수만 명의 사상자를 냈다.'),
('deng-xiaoping-3', 'deng-xiaoping', 1980, '경제특구 설치', '선전 등 4곳을 경제특구로 지정해 외국 자본과 기술을 받아들였다.', 5, '중국 수출 주도 성장의 출발점이 되었다.'),
('deng-xiaoping-4', 'deng-xiaoping', 1980, '한 자녀 정책 본격 시행', '부부당 자녀를 한 명으로 제한하는 산아 제한 정책을 전국적으로 시행했다.', -6, '강제 낙태와 불임 시술, 성비 불균형과 급속한 고령화를 낳았다.'),
('deng-xiaoping-5', 'deng-xiaoping', 1984, '중영공동성명', '일국양제 원칙으로 홍콩 반환에 관한 공동성명을 영국과 체결했다.', 3, '무력 충돌 없이 홍콩 반환 절차를 마련했다.'),
('deng-xiaoping-6', 'deng-xiaoping', 1989, '톈안먼 사건', '민주화를 요구하는 시위대를 계엄군을 동원해 무력으로 진압했다.', -8, '수많은 시민이 사망하고 정치 개혁의 길이 막혔다.'),
('deng-xiaoping-7', 'deng-xiaoping', 1992, '남순강화', '남부 지역을 시찰하며 개혁개방의 지속과 확대를 촉구했다.', 5, '톈안먼 사건 이후 정체된 시장 경제 개혁을 다시 가속했다.'),
('prince-shotoku-1', 'prince-shotoku', 603, '관위 12계 제정', '능력에 따라 관리의 등급을 주는 관위 12계를 제정했다.', 5, '가문 중심에서 관료제 중심 국가로 나아가는 첫걸음이 되었다.'),
('prince-shotoku-2', 'prince-shotoku', 604, '헌법 17조 제정', '화합과 불교 존중, 천황 중심 질서를 담은 관리의 규범을 정했다.', 6, '일본 중앙집권 국가 이념의 기초가 되었다.'),
('prince-shotoku-3', 'prince-shotoku', 607, '견수사 파견', '오노노 이모코를 수에 사신으로 보냈다.', 5, '중국의 제도와 문물을 직접 받아들이는 통로를 열었다.'),
('prince-shotoku-4', 'prince-shotoku', 607, '호류지 건립', '나라 지역에 불교 사원 호류지를 세웠다.', 4, '불교 문화 발전에 기여했으며 현존 최고(最古)급 목조 건축의 상징이 되었다.'),
('oda-nobunaga-1', 'oda-nobunaga', 1568, '교토 입성', '아시카가 요시아키를 쇼군으로 옹립하며 교토에 들어갔다.', 4, '전국 통일 과정의 결정적 발판을 마련했다.'),
('oda-nobunaga-2', 'oda-nobunaga', 1571, '엔랴쿠지 방화', '히에이산의 엔랴쿠지를 불태우고 승려와 주민 수천 명을 죽였다.', -6, '종교 시설과 민간인을 대상으로 한 대량 학살이었다.'),
('oda-nobunaga-3', 'oda-nobunaga', 1573, '무로마치 막부 멸망', '아시카가 요시아키를 교토에서 추방해 무로마치 막부를 사실상 끝냈다.', 3, '유명무실한 막부를 정리하고 새 통일 권력의 길을 열었다.'),
('oda-nobunaga-4', 'oda-nobunaga', 1574, '나가시마 잇코잇키 학살', '나가시마의 잇코종 신도 세력을 포위해 약 2만 명을 몰살했다.', -5, '항복한 사람들까지 포함한 대규모 민간인 학살이었다.'),
('oda-nobunaga-5', 'oda-nobunaga', 1575, '나가시노 전투', '대량의 조총을 활용해 다케다 가쓰요리의 군대를 격파했다.', 3, '강력한 경쟁 세력을 꺾어 통일을 앞당겼다.'),
('oda-nobunaga-6', 'oda-nobunaga', 1577, '라쿠이치·라쿠자', '아즈치 성하에서 시장세를 면제하고 상인 조합의 독점을 폐지했다.', 5, '상업 활동을 자유롭게 해 도시와 상업 발전을 촉진했다.'),
('toyotomi-hideyoshi-1', 'toyotomi-hideyoshi', 1582, '태합검지 시작', '전국의 토지를 통일된 기준으로 측량하는 검지를 시작했다.', 5, '조세 체계를 통일해 근세 일본 토지 제도의 기초가 되었다.'),
('toyotomi-hideyoshi-2', 'toyotomi-hideyoshi', 1587, '바테렌 추방령', '기독교 선교사의 국외 추방을 명령했다.', -2, '종교 자유를 제약하고 이후 기독교 탄압의 시작이 되었다.'),
('toyotomi-hideyoshi-3', 'toyotomi-hideyoshi', 1588, '도수령', '농민이 가진 칼과 무기를 몰수하게 했다.', 3, '병농 분리를 진행해 무력 충돌을 줄이고 신분 질서를 굳혔다.'),
('toyotomi-hideyoshi-4', 'toyotomi-hideyoshi', 1590, '전국 통일', '오다와라의 호조 가문을 굴복시켜 일본 전국을 통일했다.', 7, '백여 년에 걸친 전국시대 내전을 끝냈다.'),
('toyotomi-hideyoshi-5', 'toyotomi-hideyoshi', 1592, '임진왜란', '조선을 침략해 7년 전쟁을 일으켰다.', -10, '조선 전역이 황폐해지고 수많은 백성이 죽거나 끌려가 동아시아 전체에 큰 상처를 남겼다.'),
('toyotomi-hideyoshi-6', 'toyotomi-hideyoshi', 1597, '정유재란', '강화 협상이 결렬되자 조선을 다시 침략했다.', -8, '민간인 학살과 코 베기, 도공 등 백성 납치로 조선에 막대한 피해를 입혔다.'),
('tokugawa-ieyasu-1', 'tokugawa-ieyasu', 1600, '세키가하라 전투', '도요토미 정권을 지지하는 서군을 격파하고 패권을 잡았다.', 5, '히데요시 사후의 혼란을 수습하고 새 정권의 기반을 마련했다.'),
('tokugawa-ieyasu-2', 'tokugawa-ieyasu', 1603, '에도 막부 수립', '정이대장군에 임명되어 에도에 막부를 열었다.', 8, '260여 년간 큰 전쟁 없는 안정기를 열었다.'),
('tokugawa-ieyasu-3', 'tokugawa-ieyasu', 1607, '조선과 국교 회복', '임진왜란 이후 조선 사절을 맞아 국교를 재개했다.', 4, '전쟁 후 단절된 관계를 회복하고 조선인 포로 일부의 송환과 평화 교류로 이어졌다.'),
('tokugawa-ieyasu-4', 'tokugawa-ieyasu', 1609, '사쓰마의 류큐 침공 승인', '사쓰마번의 류큐 왕국 침공을 허락했다.', -4, '류큐 왕국을 사쓰마의 지배 아래 두어 수탈을 받게 했다.'),
('tokugawa-ieyasu-5', 'tokugawa-ieyasu', 1614, '기독교 금교령', '전국에 기독교를 금지하고 선교사를 추방했다.', -4, '신자 박해의 출발점이 되었고 이후 쇄국 정책으로 이어졌다.'),
('tokugawa-ieyasu-6', 'tokugawa-ieyasu', 1615, '무가제법도 제정', '오사카 전투 후 다이묘를 통제하는 무가제법도를 공포했다.', 5, '다이묘의 무력을 억제해 막부 체제의 장기 안정을 뒷받침했다.'),
('emperor-meiji-1', 'emperor-meiji', 1868, '메이지 유신과 5개조 서문', '왕정복고 후 5개조 서문을 발표하고 근대 개혁을 시작했다.', 8, '일본이 봉건 사회에서 근대 국가로 전환하는 출발점이 되었다.'),
('emperor-meiji-2', 'emperor-meiji', 1871, '폐번치현', '번을 폐지하고 중앙에서 관리를 보내는 현을 설치했다.', 6, '중앙집권적 근대 행정 체계를 확립했다.'),
('emperor-meiji-3', 'emperor-meiji', 1872, '학제 공포', '전국에 근대 학교 제도를 마련하는 학제를 공포했다.', 5, '의무교육 확대의 기반이 되었다.'),
('emperor-meiji-4', 'emperor-meiji', 1876, '강화도 조약 강요', '운요호 사건을 빌미로 조선에 불평등 조약을 강요했다.', -6, '조선 침략의 발판을 마련한 불평등 조약이었다.'),
('emperor-meiji-5', 'emperor-meiji', 1879, '류큐 병합', '류큐 왕국을 폐지하고 오키나와현으로 편입했다.', -5, '독립 왕국을 강제로 병합해 류큐인의 주권을 빼앗았다.'),
('emperor-meiji-6', 'emperor-meiji', 1889, '대일본제국 헌법 공포', '아시아 최초의 근대 헌법을 공포했다.', 5, '의회 제도를 도입했으나 천황 주권과 군부 독립이라는 한계를 담았다.'),
('emperor-meiji-7', 'emperor-meiji', 1894, '청일전쟁', '조선 지배권을 놓고 청에 전쟁을 일으켰다.', -5, '조선 땅이 전쟁터가 되고 동학 농민군이 진압되며 조선 침략이 본격화되었다.'),
('emperor-meiji-8', 'emperor-meiji', 1910, '한국 병합', '한일병합조약으로 대한제국을 일본의 식민지로 만들었다.', -10, '35년간의 식민 지배로 한국인의 주권과 생명, 재산을 빼앗았다.'),
('ito-hirobumi-1', 'ito-hirobumi', 1885, '내각 제도 창설', '태정관제를 폐지하고 내각 제도를 만들어 초대 총리에 올랐다.', 5, '일본 근대 행정부 체제의 기틀을 만들었다.'),
('ito-hirobumi-2', 'ito-hirobumi', 1895, '시모노세키 조약 체결', '청일전쟁 후 청과 조약을 맺어 대만을 할양받고 막대한 배상금을 받았다.', -4, '대만을 식민지로 만들고 조선 침략의 장애물을 없앴다.'),
('ito-hirobumi-3', 'ito-hirobumi', 1900, '입헌정우회 창당', '정당인 입헌정우회를 창당하고 총재가 되었다.', 3, '일본 정당 정치 발전의 기반이 되었다.'),
('ito-hirobumi-4', 'ito-hirobumi', 1905, '을사늑약 강요', '군대를 동원한 위협 속에 대한제국의 외교권을 빼앗는 조약을 강요했다.', -9, '대한제국의 국권을 사실상 박탈해 식민 지배로 가는 결정적 단계가 되었다.'),
('ito-hirobumi-5', 'ito-hirobumi', 1907, '고종 퇴위와 군대 해산', '통감으로서 고종을 강제 퇴위시키고 한일신협약으로 대한제국 군대를 해산했다.', -8, '대한제국의 내정과 군사권을 빼앗아 병합을 앞당겼다.'),
('hirohito-1', 'hirohito', 1937, '중일전쟁 확대', '중일전쟁이 전면전으로 확대되는 과정에서 대규모 파병을 재가했다.', -9, '난징 대학살을 비롯해 중국인 수백만 명이 희생되는 전쟁이 되었다.'),
('hirohito-2', 'hirohito', 1938, '국가총동원법 재가', '전쟁에 인력과 물자를 총동원하는 국가총동원법을 재가했다.', -8, '식민지 조선인의 강제 동원 등 수많은 사람을 전쟁에 내모는 근거가 되었다.'),
('hirohito-3', 'hirohito', 1941, '태평양전쟁 개전 재가', '어전회의에서 미국·영국 등과의 개전을 재가했다.', -9, '아시아·태평양 전역에서 수백만 명의 사망자를 낸 전쟁으로 이어졌다.'),
('hirohito-4', 'hirohito', 1945, '항복 결정', '포츠담 선언 수락을 결정하고 라디오로 항복을 알렸다.', 5, '전쟁을 끝내 추가 희생을 막았고 한국 등 식민지 해방으로 이어졌다.'),
('hirohito-5', 'hirohito', 1946, '인간 선언', '천황의 신격을 스스로 부정하는 조서를 발표했다.', 3, '천황 숭배에 기반한 국가 체제의 해체에 기여했다.'),
('tojo-hideki-1', 'tojo-hideki', 1941, '전진훈 하달', '육군대신으로서 포로가 되는 것을 치욕으로 여기라는 전진훈을 하달했다.', -4, '병사와 민간인의 집단 자결과 무모한 옥쇄를 부추겼다.'),
('tojo-hideki-2', 'tojo-hideki', 1941, '태평양전쟁 개전', '총리로서 진주만 공격과 함께 미국·영국과의 전쟁을 시작했다.', -9, '아시아·태평양 전역에서 수백만 명이 희생된 전쟁을 일으켰다.'),
('tojo-hideki-3', 'tojo-hideki', 1942, '태국-버마 철도 건설', '연합군 포로와 아시아 노동자를 동원해 태국-버마 철도 건설을 강행했다.', -6, '가혹한 강제 노동으로 수만 명이 목숨을 잃었다.'),
('tojo-hideki-4', 'tojo-hideki', 1944, '조선인 징병제 시행', '내각 결정에 따라 조선인을 일본군에 징병하기 시작했다.', -7, '수많은 조선 청년을 침략 전쟁에 강제로 내몰았다.'),
('george-washington-1', 'george-washington', 1779, '설리번 원정 명령', '대륙군 총사령관으로서 이로쿼이족 거주지를 공격하는 원정을 명령해 40여 개 마을과 농작물이 파괴되었다.', -4, '이로쿼이족은 삶의 터전을 잃고 이듬해 겨울 큰 기아와 피해를 겪었다.'),
('george-washington-2', 'george-washington', 1781, '요크타운 전투 승리', '프랑스군과 함께 요크타운에서 영국군의 항복을 받아내 독립전쟁의 승부를 결정지었다.', 9, '미국이 독립 국가로 성립하는 결정적 계기가 되었고 이후 세계 공화정 확산에도 영향을 주었다.'),
('george-washington-3', 'george-washington', 1787, '제헌회의 의장', '필라델피아 제헌회의 의장을 맡아 미국 헌법 제정을 주재했다.', 7, '이때 만든 헌법은 현재까지 이어지는 미국 정치 체제의 기반이 되었다.'),
('george-washington-4', 'george-washington', 1791, '제1합중국은행 설립 승인', '해밀턴의 재정 계획에 따라 중앙은행인 제1합중국은행 설립법에 서명했다.', 4, '연방 정부의 신용과 통일된 금융 체계를 세우는 데 기여했다.'),
('george-washington-5', 'george-washington', 1793, '도망노예법 서명', '다른 주로 도망친 노예를 붙잡아 소유주에게 돌려보내도록 한 도망노예법에 서명했다.', -5, '노예제를 연방 법률로 뒷받침해 탈출한 흑인과 자유 흑인까지 납치 위험에 놓이게 했다.'),
('george-washington-6', 'george-washington', 1793, '중립 선언', '영국과 프랑스의 전쟁에 대해 미국의 중립을 선언했다.', 4, '신생국이 유럽 전쟁에 휘말리지 않고 국력을 기를 시간을 확보했다.'),
('george-washington-7', 'george-washington', 1796, '두 임기 후 자진 퇴임', '고별사를 발표하고 3선에 나서지 않아 이듬해 존 애덤스에게 권력을 넘겼다.', 7, '대통령 두 임기 관행과 평화적 권력 이양의 전통을 세웠다.'),
('george-washington-8', 'george-washington', 1799, '유언으로 노예 해방 지시', '유언장에서 자신이 소유한 노예 123명을 아내 사후에 해방하도록 했다.', 2, '건국 지도자 가운데 드문 조치였으나 생전에는 노예 소유를 계속했고 아내 가문의 노예는 대상이 아니었다.'),
('thomas-jefferson-1', 'thomas-jefferson', 1776, '독립선언서 기초', '모든 사람은 평등하게 창조되었다는 원칙을 담은 독립선언서 초안을 작성했다.', 9, '미국 건국의 이념적 토대가 되었고 이후 세계 각지의 독립·인권 운동에 인용되었다.'),
('thomas-jefferson-2', 'thomas-jefferson', 1786, '버지니아 종교자유법 제정', '그가 기초한 버지니아 종교자유법이 주 의회를 통과해 국교 강제를 폐지했다.', 5, '미국 수정헌법 제1조의 종교 자유와 정교분리 원칙에 영향을 주었다.'),
('thomas-jefferson-3', 'thomas-jefferson', 1803, '루이지애나 매입', '프랑스로부터 루이지애나 지역을 1,500만 달러에 사들여 국토를 약 두 배로 넓혔다.', 8, '미국이 대륙 국가로 성장하는 기반이 되었으나 그 땅에 살던 원주민의 의사는 고려되지 않았다.'),
('thomas-jefferson-4', 'thomas-jefferson', 1804, '루이스·클라크 탐험 파견', '루이스와 클라크 탐험대를 보내 태평양 연안까지 서부를 조사하게 했다.', 3, '서부의 지리·자원 정보를 확보해 이후 서부 개척의 바탕이 되었다.'),
('thomas-jefferson-5', 'thomas-jefferson', 1807, '노예 수입 금지법 서명', '1808년부터 해외에서 노예를 들여오는 것을 금지하는 법에 서명했다.', 5, '대서양 노예무역을 통한 미국 유입을 법으로 끊었으나 국내 노예제와 노예 거래는 그대로 남았다.'),
('thomas-jefferson-6', 'thomas-jefferson', 1807, '출항금지법 시행', '영국·프랑스와의 분쟁에 대응해 미국 선박의 외국 항구 출항을 전면 금지했다.', -5, '수출이 급감해 해운·농업 경제가 큰 타격을 입었고 외교적 목적도 이루지 못했다.'),
('thomas-jefferson-7', 'thomas-jefferson', 1826, '노예 대부분 미해방', '사망하면서 유언으로 노예 5명만 해방했고 나머지 약 130명은 이듬해 빚을 갚기 위해 팔렸다.', -3, '평등을 선언한 그가 평생 600명 넘는 노예를 소유했고 그 가족들이 경매로 흩어졌다.'),
('abraham-lincoln-1', 'abraham-lincoln', 1861, '연방 수호 결정', '섬터 요새 피격 후 남부 연합의 분리 독립을 인정하지 않고 연방 수호를 위한 전쟁에 나섰다.', 7, '약 60만 명이 숨지는 큰 희생이 따랐으나 연방이 유지되고 노예제 폐지로 이어졌다.'),
('abraham-lincoln-2', 'abraham-lincoln', 1861, '인신보호영장 정지', '전시 치안을 이유로 의회 승인 없이 일부 지역에서 인신보호영장을 정지했다.', -3, '수천 명의 민간인이 재판 없이 구금되는 등 시민적 자유가 제한되었다.'),
('abraham-lincoln-3', 'abraham-lincoln', 1862, '홈스테드법 서명', '5년간 거주·경작한 시민에게 서부 공유지 160에이커를 무상으로 주는 홈스테드법에 서명했다.', 5, '수십만 가구가 자영농이 되었으나 원주민 땅의 상실을 가속했다.'),
('abraham-lincoln-4', 'abraham-lincoln', 1862, '태평양 철도법 서명', '대륙횡단철도 건설을 지원하는 태평양 철도법에 서명했다.', 4, '1869년 대륙횡단철도 완공으로 동서 경제가 하나로 연결되었다.'),
('abraham-lincoln-5', 'abraham-lincoln', 1862, '모릴법 서명', '연방 토지를 주에 주어 농업·공학 대학을 세우게 한 모릴 토지불하법에 서명했다.', 4, '여러 주립대학이 세워져 고등교육 대중화의 기반이 되었다.'),
('abraham-lincoln-6', 'abraham-lincoln', 1862, '다코타족 38명 처형 승인', '다코타 전쟁 후 사형 선고를 받은 303명을 검토해 대부분을 감형하고 38명의 교수형을 승인했다.', -3, '다수를 감형했지만 졸속 군사재판에 따른 미국 역사상 최대 규모의 집단 처형이 이루어졌다.'),
('abraham-lincoln-7', 'abraham-lincoln', 1863, '노예해방선언', '반란 상태의 남부 주에 있는 노예를 자유인으로 선언했다.', 10, '전쟁의 목적을 노예제 폐지로 바꾸어 수백만 흑인 해방의 길을 열었다.'),
('abraham-lincoln-8', 'abraham-lincoln', 1865, '수정헌법 제13조 의회 통과 주도', '미국 전역에서 노예제를 폐지하는 수정헌법 제13조의 하원 통과를 이끌었다.', 8, '노예제를 헌법으로 영구히 금지해 노예해방을 법적으로 완성했다.'),
('theodore-roosevelt-1', 'theodore-roosevelt', 1902, '무연탄 파업 중재', '펜실베이니아 탄광 대파업에 정부가 직접 개입해 노사 중재를 이끌어냈다.', 4, '노동 분쟁에서 정부가 중립적 중재자로 나서는 선례를 만들고 겨울 연료 위기를 막았다.'),
('theodore-roosevelt-2', 'theodore-roosevelt', 1903, '파나마 분리 독립 개입', '콜롬비아가 운하 조약을 거부하자 파나마의 분리 독립을 군함 파견으로 지원하고 곧바로 승인했다.', -3, '운하 확보를 위해 주권 국가의 영토 분리에 개입한 사례로 중남미의 반미 감정을 키웠다.'),
('theodore-roosevelt-3', 'theodore-roosevelt', 1904, '노던증권 해체 판결', '정부가 제기한 반독점 소송에서 대법원이 거대 철도지주회사 노던증권의 해체를 판결했다.', 5, '셔먼 반독점법을 실제로 집행해 독점 규제의 길을 열었다.'),
('theodore-roosevelt-4', 'theodore-roosevelt', 1904, '파나마 운하 건설 착수', '미국이 파나마 운하 지대를 넘겨받아 운하 건설을 시작했다.', 6, '1914년 개통된 운하는 세계 해운과 무역에 큰 영향을 주었다.'),
('theodore-roosevelt-5', 'theodore-roosevelt', 1905, '가쓰라-태프트 밀약 승인', '육군 장관 태프트와 일본 총리 가쓰라가 미국의 필리핀 지배와 일본의 한국 지배를 서로 인정한 합의를 승인했다.', -5, '같은 해 을사늑약을 앞두고 미국이 일본의 한국 보호국화를 묵인하는 입장을 취했다.'),
('theodore-roosevelt-6', 'theodore-roosevelt', 1906, '고적법 제정과 자연 보존', '고적법에 서명하는 등 임기 중 약 2억 3천만 에이커의 국유림·국립공원·보호구역을 지정했다.', 6, '미국 자연 보존 정책의 기반을 세워 오늘날까지 넓은 자연환경이 보호되고 있다.'),
('theodore-roosevelt-7', 'theodore-roosevelt', 1906, '순수식품의약품법 서명', '식품과 의약품의 불량 제조와 허위 표시를 금지하는 법에 서명했다.', 5, '오늘날 식품의약국(FDA)으로 이어지는 소비자 보호 제도의 출발점이 되었다.'),
('theodore-roosevelt-8', 'theodore-roosevelt', 1906, '브라운즈빌 사건 흑인 병사 불명예 전역', '텍사스 브라운즈빌 총격 사건 후 증거 없이 흑인 병사 167명 전원을 불명예 전역시켰다.', -3, '재판 없이 집단 처벌한 조치로 1972년에야 명예가 회복되었다.'),
('franklin-roosevelt-1', 'franklin-roosevelt', 1933, '뉴딜 착수', '긴급은행법과 테네시강 유역 개발공사 등 대공황 극복을 위한 뉴딜 정책을 시작했다.', 7, '금융 위기를 진정시키고 대규모 공공사업으로 실업자를 구제했다.'),
('franklin-roosevelt-2', 'franklin-roosevelt', 1935, '사회보장법 서명', '노령연금과 실업보험을 도입한 사회보장법에 서명했다.', 8, '미국 사회안전망의 근간이 되어 오늘날까지 수천만 명의 노후를 지탱하고 있다.'),
('franklin-roosevelt-3', 'franklin-roosevelt', 1937, '대법원 증원 시도', '뉴딜 법률에 제동을 건 대법원을 견제하려고 대법관 증원 법안을 추진했다.', -2, '사법부 독립을 위협한다는 반발 속에 의회에서 무산되었다.'),
('franklin-roosevelt-4', 'franklin-roosevelt', 1941, '무기대여법 서명', '영국 등 연합국에 무기와 물자를 지원하는 무기대여법에 서명했다.', 6, '나치 독일에 맞선 영국과 소련의 전쟁 수행을 크게 뒷받침했다.'),
('franklin-roosevelt-5', 'franklin-roosevelt', 1941, '제2차 세계대전 참전과 전쟁 지휘', '진주만 공습 직후 일본과 독일에 맞서 참전하고 연합국의 전쟁을 이끌었다.', 8, '추축국 패배를 이끌어 한국의 광복으로도 이어졌다.'),
('franklin-roosevelt-6', 'franklin-roosevelt', 1942, '일본계 미국인 강제 수용', '행정명령 9066호로 서부의 일본계 주민 약 12만 명을 수용소에 강제로 가두었다.', -7, '대부분 미국 시민이었던 이들이 혐의 없이 재산과 자유를 잃었고 1988년 정부가 공식 사과했다.'),
('franklin-roosevelt-7', 'franklin-roosevelt', 1944, '제대군인원호법 서명', '참전 군인에게 학비와 주택 융자를 지원하는 제대군인원호법(GI Bill)에 서명했다.', 5, '수백만 명이 대학 교육과 주택을 얻어 전후 중산층 확대의 기반이 되었다.'),
('harry-truman-1', 'harry-truman', 1945, '국제연합 헌장 서명', '샌프란시스코 회의를 마무리하고 미국의 국제연합 헌장 서명과 비준을 이끌었다.', 6, '국제연합 창설로 전후 국제 협력 체제의 기틀이 마련되었다.'),
('harry-truman-2', 'harry-truman', 1945, '원자폭탄 투하 승인', '히로시마와 나가사키에 원자폭탄 투하를 승인했다.', -6, '일본의 항복을 앞당겼으나 한국인 피폭자를 포함해 20만 명 안팎의 민간인이 숨졌다.'),
('harry-truman-3', 'harry-truman', 1945, '38선 분할 점령 제안', '일본군 항복 접수를 위해 한반도를 38선 기준으로 미국과 소련이 나누어 점령하자고 제안했다.', -5, '임시 군사 경계였던 38선이 남북 분단의 출발점이 되었다.'),
('harry-truman-4', 'harry-truman', 1948, '마셜 플랜 시행', '서유럽 재건을 위한 대규모 경제원조 계획인 마셜 플랜 법안에 서명했다.', 7, '서유럽의 빠른 경제 회복과 정치적 안정에 크게 기여했다.'),
('harry-truman-5', 'harry-truman', 1948, '베를린 공수 작전', '소련이 서베를린을 봉쇄하자 1년 가까이 항공기로 생필품을 실어 날랐다.', 4, '무력 충돌 없이 서베를린 주민 200만여 명을 지켜냈다.'),
('harry-truman-6', 'harry-truman', 1948, '군대 내 인종차별 철폐', '행정명령 9981호로 미군 내 인종 분리와 차별을 금지했다.', 6, '연방 차원의 인종 통합을 처음으로 제도화해 민권운동에 힘을 실었다.'),
('harry-truman-7', 'harry-truman', 1950, '6·25 전쟁 참전 결정', '북한의 남침 직후 미군 파병과 유엔군 결성을 결정했다.', 7, '대한민국이 공산화되지 않고 존속하는 데 결정적 역할을 했다.'),
('harry-truman-8', 'harry-truman', 1951, '맥아더 해임', '중국 본토 공격 확대를 주장하던 맥아더 유엔군 사령관을 해임했다.', 3, '문민 통제 원칙을 지키고 전쟁이 더 큰 전쟁으로 번지는 것을 막았다.'),
('john-f-kennedy-1', 'john-f-kennedy', 1961, '평화봉사단 창설', '개발도상국에 미국 청년 자원봉사자를 보내는 평화봉사단을 창설했다.', 4, '한국을 포함한 여러 나라에서 교육·보건 분야를 지원했다.'),
('john-f-kennedy-2', 'john-f-kennedy', 1961, '피그스만 침공 실패', 'CIA가 훈련한 쿠바 망명자들의 쿠바 침공을 승인했으나 사흘 만에 실패했다.', -4, '주권 국가에 대한 불법 침공이었고 쿠바가 소련에 더 밀착하는 계기가 되었다.'),
('john-f-kennedy-3', 'john-f-kennedy', 1961, '아폴로 계획 선언', '1960년대 안에 인간을 달에 보내겠다는 목표를 의회 연설에서 선언했다.', 6, '1969년 달 착륙으로 이어졌고 우주·전자 기술 발전에 큰 영향을 주었다.'),
('john-f-kennedy-4', 'john-f-kennedy', 1961, '베트남 군사 개입 확대', '남베트남 군사고문단을 늘리기 시작하고 고엽제 살포 작전을 승인했다.', -4, '고문단이 1만 6천여 명으로 늘며 이후 대규모 베트남 전쟁의 기반이 되었다.'),
('john-f-kennedy-5', 'john-f-kennedy', 1962, '쿠바 미사일 위기 해결', '소련의 쿠바 핵미사일 배치에 해상 봉쇄로 대응하고 협상으로 철수를 이끌어냈다.', 7, '핵전쟁 직전까지 간 위기를 무력 충돌 없이 끝냈다.'),
('john-f-kennedy-6', 'john-f-kennedy', 1963, '민권법안 제출', '공공시설의 인종 분리를 금지하는 포괄적 민권법안을 의회에 제출했다.', 4, '그의 사후인 1964년 민권법으로 제정되는 출발점이 되었다.'),
('john-f-kennedy-7', 'john-f-kennedy', 1963, '부분적 핵실험 금지 조약 체결', '소련·영국과 대기권·우주·수중 핵실험을 금지하는 조약에 서명했다.', 6, '방사능 낙진을 크게 줄였고 이후 핵 군비 통제 협상의 첫걸음이 되었다.'),
('richard-nixon-1', 'richard-nixon', 1969, '캄보디아 비밀 폭격', '의회와 국민에게 알리지 않고 중립국 캄보디아에 대한 대규모 폭격을 시작했다.', -6, '수많은 캄보디아 민간인이 숨졌고 크메르 루주가 세력을 키우는 배경이 되었다.'),
('richard-nixon-2', 'richard-nixon', 1970, '환경보호청 설립', '연방 환경 규제를 총괄하는 환경보호청(EPA)을 설립했다.', 6, '대기·수질 규제가 본격화되어 미국의 환경이 장기적으로 개선되었다.'),
('richard-nixon-3', 'richard-nixon', 1972, '중국 방문', '미국 대통령으로는 처음 중화인민공화국을 방문해 상하이 공동성명을 발표했다.', 7, '미중 관계 정상화의 길을 열어 냉전 구도와 동아시아 질서를 바꾸었다.'),
('richard-nixon-4', 'richard-nixon', 1972, '전략무기제한협정 체결', '소련과 전략무기제한협정(SALT I)과 탄도탄요격미사일 조약에 서명했다.', 5, '미소 간 핵무기 경쟁을 처음으로 조약을 통해 제한했다.'),
('richard-nixon-5', 'richard-nixon', 1972, '워터게이트 사건 은폐', '민주당 본부 도청 침입 사건에 대한 수사를 방해하고 은폐를 지시했다.', -6, '권력 남용이 드러나 1974년 미국 대통령 최초로 사임했고 정부 신뢰가 크게 무너졌다.'),
('richard-nixon-6', 'richard-nixon', 1973, '파리 평화협정과 베트남 철군', '파리 평화협정을 체결하고 베트남에서 미군 전투 병력을 철수시켰다.', 5, '미국의 베트남 전쟁 직접 개입을 끝내 미군 희생을 멈추었다.'),
('ronald-reagan-1', 'ronald-reagan', 1981, '콘트라 반군 지원 개시', 'CIA를 통해 니카라과 산디니스타 정부에 맞선 콘트라 반군 지원을 승인했다.', -4, '내전이 길어지며 민간인 피해가 커졌고 1986년 국제사법재판소는 미국의 지원을 국제법 위반으로 판결했다.'),
('ronald-reagan-2', 'ronald-reagan', 1983, 'GPS 민간 개방 결정', '대한항공 007편 격추 사건 후 군사용 위성항법시스템을 민간 항공에도 개방하기로 했다.', 4, '오늘날 전 세계 내비게이션과 위치 서비스의 바탕이 되었다.'),
('ronald-reagan-3', 'ronald-reagan', 1986, '이란-콘트라 사건', '무기 금수 대상인 이란에 비밀리에 무기를 팔고 그 수익을 의회가 금지한 콘트라 지원에 돌린 사실이 드러났다.', -5, '의회의 결정을 우회한 불법 행위로 정부 고위 관료들이 기소되었다.'),
('ronald-reagan-4', 'ronald-reagan', 1986, '이민개혁통제법 서명', '불법 체류자 약 270만 명에게 합법적 지위를 주는 이민개혁통제법에 서명했다.', 4, '오랫동안 미국에 살아온 이민자들이 법적 보호를 받게 되었다.'),
('ronald-reagan-5', 'ronald-reagan', 1987, '중거리핵전력 조약 체결', '고르바초프와 중거리 핵미사일 전체를 폐기하는 조약에 서명했다.', 7, '핵무기 한 종류를 처음으로 완전히 없애 냉전 종식의 흐름을 만들었다.'),
('ronald-reagan-6', 'ronald-reagan', 1988, '일본계 미국인 배상법 서명', '제2차 세계대전 중 강제 수용된 일본계 미국인에게 공식 사과하고 1인당 2만 달러를 배상하는 법에 서명했다.', 3, '국가의 과거 인권 침해를 공식 인정하고 배상한 선례가 되었다.'),
('alexander-the-great-1', 'alexander-the-great', -335, '테베 파괴', '반란을 일으킨 그리스 도시 테베를 함락해 도시를 허물고 주민 약 3만 명을 노예로 팔았다.', -5, '그리스의 유서 깊은 도시가 사라지고 수천 명이 학살되었다.'),
('alexander-the-great-2', 'alexander-the-great', -332, '티레 함락과 주민 학살', '7개월 포위 끝에 티레를 함락하고 수천 명을 처형하며 약 3만 명을 노예로 팔았다.', -5, '저항한 도시의 민간인에게 대규모 보복을 가했다.'),
('alexander-the-great-3', 'alexander-the-great', -331, '알렉산드리아 건설', '이집트 나일강 하구에 도시 알렉산드리아를 세웠다.', 6, '이후 수백 년간 지중해 세계의 학문·교역 중심지가 되었다.'),
('alexander-the-great-4', 'alexander-the-great', -331, '가우가멜라 전투 승리', '다리우스 3세의 페르시아군을 격파해 아케메네스 제국 정복을 사실상 완성했다.', 5, '그리스와 서아시아를 잇는 헬레니즘 문화권이 형성되어 수백 년간 영향을 미쳤다.'),
('alexander-the-great-5', 'alexander-the-great', -330, '페르세폴리스 방화', '페르시아 제국의 수도 페르세폴리스의 왕궁을 불태웠다.', -4, '페르시아 문명의 상징적 건축물과 기록이 파괴되었다.'),
('alexander-the-great-6', 'alexander-the-great', -324, '수사 합동결혼식', '수사에서 자신과 장교들이 페르시아 귀족 여성과 혼인하는 합동결혼식을 열었다.', 2, '정복민과 융합하려는 정책이었으나 그의 사후 대부분 이어지지 않았다.'),
('julius-caesar-1', 'julius-caesar', -58, '갈리아 전쟁 개시', '갈리아 총독으로서 8년에 걸친 정복 전쟁을 시작해 오늘날 프랑스 일대를 로마 영토로 만들었다.', -6, '고대 기록에 따르면 약 100만 명이 죽고 100만 명이 노예가 되는 막대한 피해가 있었다.'),
('julius-caesar-2', 'julius-caesar', -49, '루비콘강 도하', '원로원의 군대 해산 명령을 거부하고 군대를 이끌고 루비콘강을 건너 내전을 일으켰다.', -5, '수년간의 내전으로 많은 로마인이 희생되었고 공화정 체제가 무너지기 시작했다.'),
('julius-caesar-3', 'julius-caesar', -49, '알프스 이남 갈리아 시민권 부여', '로스키우스법으로 포강 이북 주민들에게 로마 시민권을 주었다.', 3, '속주민을 로마 공동체에 편입하는 시민권 확대의 흐름을 열었다.'),
('julius-caesar-4', 'julius-caesar', -48, '정적 사면', '파르살루스 전투에서 폼페이우스를 꺾은 뒤 항복한 반대파 다수를 처벌하지 않고 사면했다.', 2, '이전 내전과 달리 대규모 숙청을 피해 추가 유혈을 줄였다.'),
('julius-caesar-5', 'julius-caesar', -46, '율리우스력 제정', '1년을 365일로 하고 4년마다 윤일을 두는 태양력을 도입했다.', 8, '1,600년 넘게 쓰였고 오늘날 세계 표준인 그레고리력의 바탕이 되었다.'),
('julius-caesar-6', 'julius-caesar', -44, '종신 독재관 취임', '임기 제한이 없는 종신 독재관에 올라 권력을 한 몸에 모았다.', -4, '공화정 원칙을 무너뜨렸고 그의 암살과 또 다른 내전으로 이어졌다.'),
('augustus-1', 'augustus', -43, '살생부 숙청', '제2차 삼두정치를 결성하고 살생부를 공표해 키케로를 비롯한 정적 수백 명을 처형했다.', -6, '원로원 의원과 기사 계급 다수가 재판 없이 살해되고 재산을 빼앗겼다.'),
('augustus-2', 'augustus', -31, '악티움 해전 승리', '안토니우스와 클레오파트라의 함대를 격파해 로마 내전을 끝냈다.', 7, '수십 년 이어진 내전을 종식시키고 지중해 세계를 하나로 안정시켰다.'),
('augustus-3', 'augustus', -27, '원수정 수립', '공화정의 형식을 유지하면서 실권을 장악하는 원수정 체제를 세웠다.', 6, '약 200년간 이어진 ''로마의 평화''의 기반이 되었으나 공화정은 사실상 끝났다.'),
('augustus-4', 'augustus', 6, '로마 소방대 창설', '로마시에 화재 진압과 야간 순찰을 맡는 상설 소방대를 설치했다.', 2, '대도시 로마의 화재 피해와 치안 문제를 줄였다.'),
('augustus-5', 'augustus', 6, '군사 금고 설치', '퇴역 군인 연금을 지급하는 군사 금고를 세우고 전용 세금을 마련했다.', 3, '군인이 정치 지도자 개인에 의존하지 않게 해 내전의 원인을 줄였다.'),
('augustus-6', 'augustus', 9, '토이토부르크 숲 패배', '바루스가 이끄는 로마 3개 군단이 게르만족에게 전멸당했다.', -3, '약 2만 명의 병사가 희생되었고 로마는 라인강 동쪽 정복을 포기했다.'),
('charlemagne-1', 'charlemagne', 772, '작센 전쟁 개시', '작센족의 성소 이르민술을 파괴하며 30여 년에 걸친 작센 정복 전쟁을 시작했다.', -5, '오랜 전쟁과 강제 개종으로 작센 사회가 큰 피해를 입었다.'),
('charlemagne-2', 'charlemagne', 782, '페르덴 학살', '반란에 가담한 작센인 약 4,500명을 페르덴에서 한꺼번에 처형했다.', -6, '항복한 포로를 대량 처형한 학살이었다.'),
('charlemagne-3', 'charlemagne', 789, '일반 훈령 반포', '수도원과 성당에 학교를 세워 읽기와 쓰기를 가르치도록 하는 일반 훈령을 내렸다.', 6, '카롤링거 르네상스로 고전 문헌이 필사·보존되어 중세 학문의 기반이 되었다.'),
('charlemagne-4', 'charlemagne', 794, '화폐 개혁', '프랑크푸르트 회의에서 은화 데나리우스를 표준으로 하는 통일 화폐 제도를 정했다.', 5, '파운드·실링·펜스 체계의 원형이 되어 유럽에서 천 년 넘게 쓰였다.'),
('charlemagne-5', 'charlemagne', 800, '서로마 황제 대관', '로마에서 교황 레오 3세에게 서로마 황제의 관을 받았다.', 7, '서유럽을 하나의 기독교 세계로 묶는 정체성을 세우고 신성로마제국 전통의 출발점이 되었다.'),
('charlemagne-6', 'charlemagne', 802, '순찰사 제도 정비', '국왕 순찰사를 각지에 보내 지방 관리를 감독하고 법을 집행하게 했다.', 3, '넓은 제국에서 지방 권력의 남용을 견제하는 행정 체계를 만들었다.'),
('elizabeth-i-1', 'elizabeth-i', 1559, '엘리자베스 종교 정착', '수장령과 통일령을 제정해 온건한 개신교 국교회 체제를 세웠다.', 6, '가톨릭과 개신교의 극단적 충돌을 줄이고 잉글랜드 국교회의 기틀을 세웠다.'),
('elizabeth-i-2', 'elizabeth-i', 1564, '노예무역 항해 투자', '존 호킨스의 아프리카 노예무역 항해에 왕실 군함을 빌려주고 투자했다.', -4, '잉글랜드가 대서양 노예무역에 뛰어드는 데 왕실이 직접 관여했다.'),
('elizabeth-i-3', 'elizabeth-i', 1569, '북부 반란 진압', '가톨릭 귀족들이 일으킨 북부 반란을 진압하고 수백 명을 처형했다.', -3, '반란 진압 후 평민을 포함해 약 600명이 처형되었다.'),
('elizabeth-i-4', 'elizabeth-i', 1583, '데즈먼드 반란 초토화 진압', '아일랜드 먼스터 지방의 데즈먼드 반란을 농작물과 가축을 없애는 초토화 작전으로 진압했다.', -5, '기근으로 먼스터 주민 수만 명이 숨졌다.'),
('elizabeth-i-5', 'elizabeth-i', 1588, '스페인 무적함대 격퇴', '잉글랜드 침공을 노린 스페인 무적함대를 물리쳤다.', 6, '잉글랜드의 독립을 지키고 이후 해양 강국으로 성장하는 발판이 되었다.'),
('elizabeth-i-6', 'elizabeth-i', 1601, '구빈법 제정', '교구 단위로 세금을 걷어 빈민을 구제하는 엘리자베스 구빈법을 제정했다.', 5, '국가가 빈민 구제를 책임지는 제도로 200년 넘게 영국 복지의 근간이 되었다.'),
('louis-xiv-1', 'louis-xiv', 1661, '친정 개시와 콜베르 등용', '재상 마자랭 사후 직접 통치를 시작하고 콜베르를 등용해 재정과 산업을 정비했다.', 4, '중앙집권 행정과 중상주의 산업 육성으로 국력이 커졌다.'),
('louis-xiv-2', 'louis-xiv', 1666, '왕립 과학 아카데미 설립', '국가가 과학자를 지원하는 왕립 과학 아카데미를 세웠다.', 4, '프랑스가 근대 과학 연구의 중심지 가운데 하나가 되었다.'),
('louis-xiv-3', 'louis-xiv', 1666, '미디 운하 건설 승인', '대서양과 지중해를 잇는 미디 운하 건설을 칙령으로 승인했다.', 4, '1681년 완공된 운하는 남프랑스 물류를 크게 개선하고 지금도 남아 있다.'),
('louis-xiv-4', 'louis-xiv', 1685, '흑인법 제정', '프랑스 식민지의 노예를 재산으로 규정하고 가혹한 처벌을 허용한 흑인법을 반포했다.', -6, '카리브해 식민지 노예제를 법적으로 체계화해 1848년까지 수많은 흑인의 억압을 뒷받침했다.'),
('louis-xiv-5', 'louis-xiv', 1685, '낭트 칙령 폐지', '퐁텐블로 칙령으로 개신교 신앙의 자유를 보장한 낭트 칙령을 폐지했다.', -7, '위그노 약 20만 명이 박해를 피해 국외로 떠나 프랑스의 인재와 산업이 크게 유출되었다.'),
('louis-xiv-6', 'louis-xiv', 1689, '팔츠 초토화', '9년 전쟁 중 독일 팔츠 지방의 도시와 마을을 조직적으로 불태웠다.', -5, '하이델베르크 등 여러 도시가 파괴되고 많은 민간인이 터전을 잃었다.'),
('louis-xiv-7', 'louis-xiv', 1701, '스페인 왕위 계승 전쟁', '손자를 스페인 왕위에 앉히려다 유럽 연합군과 13년에 걸친 전쟁을 벌였다.', -5, '막대한 인명 피해와 국가 부채를 남겨 이후 왕정의 재정 위기로 이어졌다.'),
('frederick-the-great-1', 'frederick-the-great', 1740, '고문 폐지', '즉위 직후 형사 재판에서 고문을 대부분 금지했고 1754년에는 완전히 폐지했다.', 4, '유럽에서 이른 시기에 사법 고문을 없애 근대 형사 제도의 선례가 되었다.'),
('frederick-the-great-2', 'frederick-the-great', 1740, '슐레지엔 침공', '선전포고 없이 오스트리아령 슐레지엔을 침공해 오스트리아 왕위 계승 전쟁을 촉발했다.', -4, '영토 확장을 위한 침략으로 유럽 여러 나라가 휘말린 전쟁이 일어났다.'),
('frederick-the-great-3', 'frederick-the-great', 1756, '감자 재배 장려령', '칙령을 내려 각지에서 감자를 재배하도록 장려했다.', 4, '감자가 주요 식량으로 자리 잡아 기근 피해를 줄이는 데 기여했다.'),
('frederick-the-great-4', 'frederick-the-great', 1756, '작센 침공과 7년 전쟁', '작센을 선제 침공해 7년 전쟁을 일으켰다.', -5, '프로이센 인구의 약 10%가 숨지는 등 중부 유럽에 막대한 인명 피해를 냈다.'),
('frederick-the-great-5', 'frederick-the-great', 1763, '일반 지방학교 규정', '5세에서 13~14세 아동의 의무교육을 규정한 일반 지방학교 규정을 반포했다.', 6, '국가 주도 의무교육의 선구적 사례로 이후 근대 교육 제도에 영향을 주었다.'),
('frederick-the-great-6', 'frederick-the-great', 1772, '제1차 폴란드 분할', '러시아·오스트리아와 함께 폴란드 영토 일부를 빼앗아 나누어 가졌다.', -6, '이후 이어진 분할로 폴란드가 120여 년간 나라를 잃는 출발점이 되었다.'),
('napoleon-1', 'napoleon', 1799, '브뤼메르 쿠데타', '군대를 동원해 총재정부를 무너뜨리고 제1통령으로 권력을 잡았다.', -3, '혁명 공화정을 무력으로 끝내고 독재의 길을 열었다.'),
('napoleon-2', 'napoleon', 1800, '프랑스 은행 설립', '통화와 신용을 관리하는 프랑스 은행을 세웠다.', 4, '혁명기 혼란에 빠진 재정을 안정시키고 오늘날까지 이어지는 중앙은행이 되었다.'),
('napoleon-3', 'napoleon', 1801, '정교 협약 체결', '교황청과 정교 협약을 맺어 혁명 이후의 교회 분열을 수습했다.', 4, '종교 갈등을 진정시켜 국내 안정에 기여했다.'),
('napoleon-4', 'napoleon', 1802, '리세 설립', '국가가 운영하는 중등학교인 리세를 설립하는 법을 제정했다.', 4, '오늘날까지 이어지는 프랑스 중등교육 체계의 기반이 되었다.'),
('napoleon-5', 'napoleon', 1802, '노예제 부활', '혁명기에 폐지되었던 식민지 노예제와 노예무역을 법으로 되살렸다.', -7, '카리브해 식민지 흑인들이 다시 노예가 되었고 아이티 진압 원정에서 수많은 인명이 희생되었다.'),
('napoleon-6', 'napoleon', 1804, '나폴레옹 법전 제정', '법 앞의 평등과 사유재산권을 명시한 프랑스 민법전을 공포했다.', 9, '유럽과 세계 여러 나라 민법의 모델이 되어 지금까지 영향을 미치고 있다.'),
('napoleon-7', 'napoleon', 1808, '스페인 침공', '스페인 왕을 퇴위시키고 형 조제프를 왕으로 앉히며 이베리아반도를 침공했다.', -5, '6년간의 반도 전쟁에서 수십만 명의 민간인과 병사가 희생되었다.'),
('napoleon-8', 'napoleon', 1812, '러시아 원정', '60만 대군을 이끌고 러시아를 침공했다가 겨울 퇴각 중 군대 대부분을 잃었다.', -7, '양측에서 수십만 명이 숨졌고 제국 몰락의 결정적 계기가 되었다.'),
('queen-victoria-1', 'queen-victoria', 1840, '제1차 아편전쟁', '청이 아편 밀수를 단속하자 영국이 원정군을 보내 전쟁을 일으켰다.', -3, '아편 무역을 강요하고 난징 조약으로 불평등 조약 체제를 열어 중국에 오랜 피해를 주었다.'),
('queen-victoria-2', 'queen-victoria', 1845, '아일랜드 대기근 대응 실패', '감자 역병으로 아일랜드에 대기근이 닥쳤으나 정부는 식량 수출을 막지 않고 구호를 제한했다.', -3, '약 100만 명이 숨지고 100만 명 이상이 이민을 떠나 아일랜드 인구가 크게 줄었다.'),
('queen-victoria-3', 'queen-victoria', 1848, '공중보건법 제정', '지방 보건위원회를 두고 상하수도를 정비하도록 한 공중보건법이 제정되었다.', 2, '도시 위생 개선의 출발점이 되어 콜레라 등 전염병 피해를 줄였다.'),
('queen-victoria-4', 'queen-victoria', 1857, '인도 항쟁 진압', '세포이 항쟁을 진압하면서 대규모 보복 처형을 벌이고 이듬해 인도를 영국 정부 직할 통치로 바꾸었다.', -2, '진압 과정에서 수많은 인도인이 학살되었고 식민 지배가 더 굳어졌다.'),
('queen-victoria-5', 'queen-victoria', 1867, '제2차 선거법 개정', '도시 노동자 상당수에게 선거권을 주는 제2차 선거법 개정이 이루어졌다.', 2, '유권자 수가 약 두 배로 늘어 영국 민주주의 확대에 기여했다.'),
('queen-victoria-6', 'queen-victoria', 1870, '초등교육법 제정', '전국에 공립 초등학교를 세우도록 한 초등교육법이 제정되었다.', 2, '보편적 초등교육의 기반이 마련되어 문해율이 크게 높아졌다.'),
('queen-victoria-7', 'queen-victoria', 1876, '인도 대기근', '인도에 대기근이 닥쳤으나 식민 당국은 곡물 수출을 계속하고 구호를 최소화했다.', -3, '1876~1878년 사이 약 500만 명 이상이 숨졌다.'),
('queen-victoria-8', 'queen-victoria', 1900, '보어전쟁 강제수용소', '남아프리카 보어전쟁에서 보어인 여성·아동과 흑인 주민을 강제수용소에 가두었다.', -2, '열악한 환경으로 보어인 약 2만 6천 명과 흑인 약 2만 명이 숨졌다.'),
('otto-von-bismarck-1', 'otto-von-bismarck', 1862, '철혈 연설과 의회 무시 통치', '철과 피로 문제를 해결하겠다고 연설하고 의회의 예산 거부에도 군비 지출을 강행했다.', -3, '의회 권한을 무시한 통치로 입헌주의 발전을 가로막았다.'),
('otto-von-bismarck-2', 'otto-von-bismarck', 1871, '독일 제국 수립', '프로이센-프랑스 전쟁에서 승리한 뒤 베르사유 궁전에서 독일 제국 수립을 선포했다.', 8, '분열된 독일 국가들을 하나로 묶었으나 알자스-로렌 병합으로 프랑스와의 적대가 깊어졌다.'),
('otto-von-bismarck-3', 'otto-von-bismarck', 1872, '문화투쟁', '예수회를 추방하는 등 가톨릭 교회를 국가 통제 아래 두려는 탄압 정책을 펼쳤다.', -4, '수많은 성직자가 투옥·추방되고 가톨릭 주민과의 갈등이 깊어졌다.'),
('otto-von-bismarck-4', 'otto-von-bismarck', 1878, '베를린 회의 주재', '러시아-튀르크 전쟁 후 열강의 이해를 조정하는 베를린 회의를 주재했다.', 3, '열강 간 전쟁 위기를 외교로 진정시켰다.'),
('otto-von-bismarck-5', 'otto-von-bismarck', 1878, '사회주의자 탄압법 제정', '사회민주주의 단체와 집회, 출판을 금지하는 사회주의자 탄압법을 제정했다.', -4, '12년간 정치·결사의 자유를 억압하고 많은 활동가를 추방했다.'),
('otto-von-bismarck-6', 'otto-von-bismarck', 1883, '세계 최초 사회보험 도입', '질병보험법을 시작으로 산재보험과 노령·장애연금을 차례로 도입했다.', 8, '근대 사회보장 제도의 원형이 되어 전 세계 복지국가의 모델이 되었다.'),
('otto-von-bismarck-7', 'otto-von-bismarck', 1884, '베를린 회의와 아프리카 분할', '열강의 아프리카 분할 규칙을 정한 베를린 회의를 주최하고 독일의 아프리카 식민지 획득을 시작했다.', -5, '아프리카인의 의사와 무관하게 대륙이 분할되어 식민 지배가 본격화되었다.'),
('winston-churchill-1', 'winston-churchill', 1909, '최저임금·직업소개소 도입', '상무장관으로서 업종별 최저임금을 정하는 직종위원회법과 직업소개소 제도를 도입했다.', 4, '영국 노동자 보호와 복지 제도의 초기 기반이 되었다.'),
('winston-churchill-2', 'winston-churchill', 1915, '갈리폴리 작전 실패', '해군장관으로서 추진한 다르다넬스·갈리폴리 상륙 작전이 대규모 손실 끝에 실패했다.', -4, '양측에서 수십만 명의 사상자가 났고 그는 해군장관직에서 물러났다.'),
('winston-churchill-3', 'winston-churchill', 1925, '금본위제 복귀', '재무장관으로서 전쟁 전 환율로 금본위제에 복귀하는 결정을 내렸다.', -3, '파운드 고평가로 수출 산업이 타격을 입고 실업과 이듬해 총파업의 배경이 되었다.'),
('winston-churchill-4', 'winston-churchill', 1940, '총리 취임과 대독 항전', '총리에 올라 독일과의 강화 대신 항전을 택하고 영국 본토 항공전을 이끌었다.', 9, '유럽 대부분이 점령된 상황에서 영국이 버텨 나치 독일 패배의 발판이 되었다.'),
('winston-churchill-5', 'winston-churchill', 1941, '대서양 헌장 발표', '루스벨트와 함께 영토 불확장과 민족자결 원칙을 담은 대서양 헌장을 발표했다.', 4, '전후 국제연합 창설의 이념적 바탕이 되었으나 그는 영국 식민지에는 적용하지 않으려 했다.'),
('winston-churchill-6', 'winston-churchill', 1943, '벵골 대기근 대응', '벵골에 대기근이 닥쳤으나 전시 내각은 인도의 긴급 식량 수입 요청을 크게 줄여 승인했다.', -5, '약 300만 명이 숨진 기근에서 구호가 늦어져 피해가 커졌다.'),
('winston-churchill-7', 'winston-churchill', 1952, '케냐 마우마우 봉기 진압', '케냐에 비상사태를 선포하고 마우마우 봉기를 강제수용과 고문을 동반해 진압했다.', -5, '수만 명이 재판 없이 수용되고 학대를 당해 2013년 영국 정부가 배상했다.'),
('winston-churchill-8', 'winston-churchill', 1953, '이란 쿠데타 승인', '석유 국유화를 추진한 이란 모사데크 정부를 무너뜨리는 미국과의 공동 쿠데타 계획을 승인했다.', -4, '민선 정부가 전복되고 이후 수십 년간 이란의 권위주의 통치와 반서방 감정으로 이어졌다.'),
('adolf-hitler-1', 'adolf-hitler', 1933, '수권법 제정', '정부가 의회 동의 없이 법률을 만들 수 있게 한 수권법을 통과시켰다.', -8, '바이마르 민주주의를 끝내고 일당 독재 체제를 세웠다.'),
('adolf-hitler-2', 'adolf-hitler', 1935, '뉘른베르크법 제정', '유대인의 시민권을 박탈하고 비유대인과의 결혼을 금지한 뉘른베르크 인종법을 제정했다.', -7, '유대인 차별을 법으로 제도화해 이후 학살로 가는 길을 열었다.'),
('adolf-hitler-3', 'adolf-hitler', 1938, '수정의 밤', '전국에서 유대교 회당과 상점을 파괴하고 유대인을 폭행·체포한 조직적 폭력이 벌어졌다.', -6, '약 100명이 살해되고 3만 명이 강제수용소로 끌려갔다.'),
('adolf-hitler-4', 'adolf-hitler', 1939, '폴란드 침공', '폴란드를 침공해 제2차 세계대전을 일으켰다.', -10, '인류 역사상 최대의 전쟁으로 수천만 명이 목숨을 잃었다.'),
('adolf-hitler-5', 'adolf-hitler', 1939, 'T4 안락사 작전', '장애인과 정신질환자를 조직적으로 살해하는 T4 작전을 명령했다.', -6, '약 7만 명 이상의 장애인이 살해되었고 이후 학살 수용소 기술의 바탕이 되었다.'),
('adolf-hitler-6', 'adolf-hitler', 1941, '소련 침공', '독소 불가침 조약을 깨고 소련을 침공해 절멸 전쟁을 벌였다.', -9, '소련 군인과 민간인 약 2,700만 명이 숨지는 등 역사상 가장 참혹한 전선이 되었다.'),
('adolf-hitler-7', 'adolf-hitler', 1942, '홀로코스트', '반제 회의에서 유대인 절멸 계획을 조직화하고 절멸 수용소에서 대량 학살을 실행했다.', -10, '유대인 약 600만 명과 로마인 등 수많은 사람이 조직적으로 학살되었다.'),
('benito-mussolini-1', 'benito-mussolini', 1922, '로마 진군', '파시스트 무장대의 로마 진군으로 압력을 가해 총리에 임명되었다.', -5, '폭력으로 권력을 잡아 파시즘 독재의 출발점이 되었다.'),
('benito-mussolini-2', 'benito-mussolini', 1925, '독재 선언', '야당 의원 마테오티 살해 사건 후 의회 연설에서 책임을 자인하며 독재 체제를 선언했다.', -6, '야당과 언론의 자유가 사라지고 일당 독재가 확립되었다.'),
('benito-mussolini-3', 'benito-mussolini', 1929, '라테란 조약 체결', '교황청과 라테란 조약을 맺어 바티칸 시국을 독립국으로 인정했다.', 5, '60년 가까이 이어진 이탈리아 국가와 교황청의 갈등을 해결했다.'),
('benito-mussolini-4', 'benito-mussolini', 1930, '리비아 강제수용', '리비아 키레나이카의 저항을 꺾기 위해 주민 약 10만 명을 강제수용소로 이주시켰다.', -5, '수용소에서 수만 명이 굶주림과 질병으로 숨졌다.'),
('benito-mussolini-5', 'benito-mussolini', 1932, '폰티네 습지 간척', '로마 남쪽 폰티네 습지를 간척하고 새 도시 리토리아(현 라티나)를 건설했다.', 3, '말라리아 지대를 농지로 바꾸어 많은 농민이 정착했다.'),
('benito-mussolini-6', 'benito-mussolini', 1935, '에티오피아 침공', '에티오피아를 침공하고 국제법상 금지된 독가스를 사용해 점령했다.', -7, '수십만 명의 에티오피아인이 숨졌고 국제연맹 체제의 붕괴를 앞당겼다.'),
('benito-mussolini-7', 'benito-mussolini', 1938, '인종법 제정', '유대인의 공직·교육·결혼을 제한하는 인종법을 제정했다.', -6, '이탈리아 유대인이 시민권을 잃었고 이후 수천 명이 강제 이송되어 숨졌다.'),
('benito-mussolini-8', 'benito-mussolini', 1940, '제2차 세계대전 참전', '나치 독일 편에 서서 영국·프랑스에 선전포고했다.', -7, '수십만 명의 이탈리아인이 숨지고 나라가 전쟁터가 되었다.'),
('charles-de-gaulle-1', 'charles-de-gaulle', 1940, '6월 18일 호소', '프랑스 항복 직전 런던에서 라디오 연설로 항전을 호소하고 자유프랑스를 이끌었다.', 8, '프랑스 레지스탕스의 구심점이 되어 프랑스가 연합국 일원으로 해방되게 했다.'),
('charles-de-gaulle-2', 'charles-de-gaulle', 1944, '여성 참정권 부여', '그가 이끈 임시정부가 명령으로 프랑스 여성에게 참정권을 부여했다.', 6, '프랑스 여성이 처음으로 투표권과 피선거권을 얻었다.'),
('charles-de-gaulle-3', 'charles-de-gaulle', 1945, '세티프 학살', '그가 이끈 임시정부 아래 알제리 세티프 일대의 독립 요구 시위를 군대가 무력으로 진압했다.', -5, '보복 진압으로 수천 명 이상의 알제리인이 숨졌다.'),
('charles-de-gaulle-4', 'charles-de-gaulle', 1958, '제5공화국 헌법 제정', '강력한 대통령 중심의 제5공화국 헌법을 만들어 국민투표로 확정했다.', 6, '잦은 내각 교체로 불안정하던 정치를 안정시켰고 이 헌법은 지금도 쓰이고 있다.'),
('charles-de-gaulle-5', 'charles-de-gaulle', 1960, '사하라 핵실험', '알제리 사하라 사막에서 프랑스 최초의 핵실험을 실시했다.', -3, '핵무기 확산에 가담했고 실험 지역 주민들이 방사능 피해를 입었다.'),
('charles-de-gaulle-6', 'charles-de-gaulle', 1961, '파리 학살', '파리에서 알제리인들의 평화 시위를 경찰이 폭력 진압해 다수를 살해했다.', -4, '수십에서 수백 명의 알제리인이 숨졌고 정부는 오랫동안 사건을 은폐했다.'),
('charles-de-gaulle-7', 'charles-de-gaulle', 1962, '알제리 독립 인정', '에비앙 협정을 맺어 알제리 전쟁을 끝내고 알제리 독립을 인정했다.', 6, '8년에 걸친 전쟁을 끝내고 알제리인의 자결권을 인정했다.'),
('charles-de-gaulle-8', 'charles-de-gaulle', 1963, '엘리제 조약 체결', '서독의 아데나워 총리와 프랑스-독일 우호 협력 조약을 맺었다.', 6, '오랜 적대 관계였던 두 나라의 화해를 제도화해 유럽 통합의 축이 되었다.'),
('peter-the-great-1', 'peter-the-great', 1697, '대사절단 서유럽 파견', '표트르가 직접 신분을 숨기고 사절단과 함께 네덜란드·영국 등을 돌며 조선술과 기술을 익혔다.', 4, '서유럽 기술과 인재를 들여와 이후 근대화 개혁의 토대가 되었다.'),
('peter-the-great-2', 'peter-the-great', 1698, '스트렐치 반란 진압', '귀국한 표트르가 반란을 일으킨 스트렐치 병사 수백 명을 고문하고 공개 처형했다.', -4, '대규모 고문과 처형으로 공포 통치를 확립했다.'),
('peter-the-great-3', 'peter-the-great', 1703, '상트페테르부르크 건설', '네바강 하구에 새 도시를 세우고 이후 수도로 삼았다.', 6, '러시아의 바다 출구이자 서구화의 중심지가 되었으나 건설에 동원된 농민과 노동자가 다수 희생되었다.'),
('peter-the-great-4', 'peter-the-great', 1709, '폴타바 전투 승리', '대북방전쟁 중 폴타바에서 스웨덴의 카를 12세 군대를 격파했다.', 6, '스웨덴의 패권을 꺾고 러시아가 북유럽의 강국으로 떠오르는 전환점이 되었다.'),
('peter-the-great-5', 'peter-the-great', 1718, '황태자 알렉세이 사망', '개혁에 반대한다는 혐의로 체포된 아들 알렉세이가 고문 끝에 옥중에서 사망했다.', -3, '자식까지 고문해 숨지게 한 권력 행사로 후계 체제를 불안하게 만들었다.'),
('peter-the-great-6', 'peter-the-great', 1721, '뉘스타드 조약과 제국 선포', '스웨덴과 조약을 맺어 발트해 연안을 얻고 황제 칭호를 받아 러시아 제국을 선포했다.', 7, '발트해 진출을 확정해 러시아의 국제적 위상을 장기간 바꾸어 놓았다.'),
('peter-the-great-7', 'peter-the-great', 1722, '관등표 제정', '문무 관직을 14등급으로 나누고 출신이 아닌 공로에 따라 승진하게 했다.', 5, '능력에 따른 관료 체계를 세워 1917년까지 이어지는 국가 행정의 틀이 되었다.'),
('peter-the-great-8', 'peter-the-great', 1724, '인두세 징수 시작', '가구 대신 남성 개인에게 세금을 매기는 인두세를 전국적으로 걷기 시작했다.', -4, '농민의 세 부담을 크게 늘리고 농노제를 더욱 굳혔다.'),
('catherine-ii-1', 'catherine-ii', 1762, '궁정 쿠데타로 즉위', '근위대의 지지를 받아 남편 표트르 3세를 폐위하고 제위에 올랐으며 표트르 3세는 며칠 뒤 감금 중 사망했다.', -2, '정당한 계승이 아닌 무력 정변으로 권력을 잡았다.'),
('catherine-ii-2', 'catherine-ii', 1764, '스몰니 여학교 설립', '상트페테르부르크에 귀족 여성을 위한 국립 교육기관인 스몰니 학원을 세웠다.', 3, '러시아에서 국가가 주도한 여성 교육의 출발점이 되었다.'),
('catherine-ii-3', 'catherine-ii', 1767, '입법위원회 소집', '계몽사상을 담은 훈령을 내리고 여러 신분의 대표를 모아 법전 편찬 위원회를 열었다.', 2, '계몽 이념을 정치 논의에 들여왔으나 실제 법전 편찬으로 이어지지는 못했다.'),
('catherine-ii-4', 'catherine-ii', 1774, '퀴췩카이나르자 조약', '오스만 제국과의 전쟁에서 승리해 흑해 연안 일부와 흑해 항행권을 얻었다.', 5, '러시아가 흑해로 진출하는 발판을 마련했다.'),
('catherine-ii-5', 'catherine-ii', 1775, '지방행정 개혁', '전국을 현과 군으로 나누고 지방 행정·사법 기구를 새로 정비했다.', 4, '이후 오랫동안 유지된 러시아 지방 통치 체계의 기초가 되었다.'),
('catherine-ii-6', 'catherine-ii', 1783, '크림 칸국 병합', '오스만의 영향 아래 있던 크림 칸국을 병합했다.', 4, '흑해 지배권과 남부 영토를 확보했으나 크림 타타르인 다수가 오스만 영토로 떠났다.'),
('catherine-ii-7', 'catherine-ii', 1785, '귀족 특허장 반포', '귀족의 세금·병역 면제와 토지·농노 소유권을 법으로 보장했다.', -5, '귀족 특권을 강화해 다수 농노의 예속을 더욱 굳혔다.'),
('catherine-ii-8', 'catherine-ii', 1795, '제3차 폴란드 분할', '프로이센·오스트리아와 함께 남은 폴란드 영토를 나누어 가져 폴란드를 지도에서 없앴다.', -6, '한 나라를 소멸시켜 폴란드인이 120여 년간 독립을 잃게 했다.'),
('lenin-1', 'lenin', 1917, '토지에 관한 포고', '10월 혁명 직후 지주의 토지를 몰수해 농민이 쓰도록 한다는 포고를 내렸다.', 4, '농민의 오랜 토지 요구에 응했으나 이후 정책으로 그 성과가 오래가지 못했다.'),
('lenin-2', 'lenin', 1918, '제헌의회 강제 해산', '볼셰비키가 소수파가 된 제헌의회를 개회 하루 만에 무력으로 해산했다.', -6, '러시아 최초의 보통선거 의회를 없애고 일당 독재의 길을 열었다.'),
('lenin-3', 'lenin', 1918, '브레스트-리토프스크 조약', '독일 등과 강화 조약을 맺어 제1차 세계대전에서 빠져나왔다.', -2, '전쟁은 끝냈으나 우크라이나·발트 지역 등 넓은 영토와 인구를 잃었다.'),
('lenin-4', 'lenin', 1918, '전시공산주의 시행', '내전 중 곡물 강제 징발과 산업 국유화를 밀어붙였다.', -6, '생산이 붕괴하고 1921년 대기근의 주요 원인이 되었다.'),
('lenin-5', 'lenin', 1918, '적색 테러 선포', '체카에 반대 세력을 재판 없이 체포·처형할 권한을 주는 적색 테러를 공식화했다.', -8, '수많은 사람이 재판 없이 처형되었고 이후 소련 국가 폭력의 원형이 되었다.'),
('lenin-6', 'lenin', 1921, '크론시타트 반란 진압', '자유선거와 표현의 자유를 요구한 크론시타트 수병들의 봉기를 군대로 진압했다.', -4, '혁명을 지지했던 세력의 요구까지 무력으로 억눌렀다.'),
('lenin-7', 'lenin', 1921, '신경제정책 도입', '곡물 징발을 현물세로 바꾸고 소규모 상업과 사기업을 허용했다.', 5, '붕괴했던 농업과 경제를 빠르게 회복시켰다.'),
('stalin-1', 'stalin', 1928, '제1차 5개년 계획', '중공업 중심의 국가 계획경제로 급속한 공업화를 시작했다.', 5, '단기간에 공업 기반을 갖추었으나 소비재 부족과 강제노동의 대가가 따랐다.'),
('stalin-2', 'stalin', 1929, '강제 농업집단화', '농민의 토지와 가축을 집단농장에 강제로 편입하고 이른바 쿨라크를 숙청·추방했다.', -8, '수백만 농민이 추방·사망하고 농업 생산이 장기간 침체했다.'),
('stalin-3', 'stalin', 1932, '대기근', '집단화와 과도한 곡물 징발 속에 우크라이나·카자흐스탄 등에서 대기근이 일어났다.', -9, '곡물 징발을 멈추지 않아 수백만 명이 굶어 죽었다.'),
('stalin-4', 'stalin', 1937, '대숙청', '비밀경찰을 동원해 당·군 간부와 일반 시민을 대규모로 체포·처형했다.', -9, '약 70만 명이 처형되고 더 많은 사람이 굴라크로 보내졌다.'),
('stalin-5', 'stalin', 1939, '독소 불가침조약', '나치 독일과 불가침조약을 맺고 비밀의정서로 동유럽을 세력권으로 나누었다.', -6, '폴란드 분할과 발트 3국 병합으로 이어졌다.'),
('stalin-6', 'stalin', 1940, '카틴 학살', '포로로 잡은 폴란드 장교와 지식인 약 2만 2천 명을 비밀경찰이 처형했다.', -6, '한 나라의 지도층을 조직적으로 학살했다.'),
('stalin-7', 'stalin', 1944, '소수민족 강제 이주', '체첸인·인구시인·크림 타타르인 등을 적에 협력했다는 이유로 중앙아시아로 집단 추방했다.', -7, '민족 전체를 강제 이주시켜 이송과 정착 과정에서 다수가 사망했다.'),
('stalin-8', 'stalin', 1945, '독소전쟁 승리', '베를린을 점령하며 나치 독일과의 전쟁을 승리로 끝냈다.', 8, '나치 독일 패망에 결정적 역할을 했으나 전쟁 초기 대비 실패로 피해가 커졌다.'),
('gorbachev-1', 'gorbachev', 1986, '글라스노스트 추진', '언론과 사회의 비판을 허용하는 개방 정책을 내세웠다.', 6, '검열을 크게 완화해 소련 사회에 표현의 자유를 넓혔다.'),
('gorbachev-2', 'gorbachev', 1986, '체르노빌 사고 초기 은폐', '체르노빌 원전 폭발 사고를 처음 며칠 동안 국내외에 제대로 알리지 않았다.', -3, '주민 대피와 국제 대응이 늦어져 피해를 키웠다.'),
('gorbachev-3', 'gorbachev', 1987, '국영기업법 시행', '국영기업에 자율 경영을 허용하는 경제 개혁을 추진했다.', -4, '계획경제와 시장의 혼란이 겹쳐 물자 부족과 재정 위기가 심해졌다.'),
('gorbachev-4', 'gorbachev', 1987, '중거리핵전력 조약 체결', '미국과 중거리 핵미사일 전체를 폐기하는 조약을 맺었다.', 7, '한 종류의 핵무기를 처음으로 통째로 없애 냉전 긴장을 크게 낮추었다.'),
('gorbachev-5', 'gorbachev', 1989, '아프가니스탄 철군 완료', '10년 가까이 이어진 아프가니스탄 전쟁에서 소련군을 모두 철수시켰다.', 5, '막대한 인명과 재정 손실을 낳던 전쟁을 끝냈다.'),
('gorbachev-6', 'gorbachev', 1989, '인민대표대회 경쟁 선거', '복수 후보가 경쟁하는 인민대표대회 선거를 처음으로 실시했다.', 5, '소련 역사상 처음으로 경쟁 선거를 도입했다.'),
('gorbachev-7', 'gorbachev', 1989, '동유럽 민주화 불개입', '동유럽 국가들의 민주화 혁명에 소련군을 개입시키지 않았다.', 8, '동유럽의 평화적 체제 전환과 냉전 종식을 가능하게 했다.'),
('gorbachev-8', 'gorbachev', 1990, '바쿠 무력 진압', '아제르바이잔 바쿠에 비상사태를 선포하고 군대를 투입해 100명 넘는 민간인이 숨졌다.', -4, '민족 분쟁과 독립 요구에 유혈 진압으로 대응했다.'),
('ramesses-ii-1', 'ramesses-ii', -1278, '셰르덴 해적 격퇴', '나일강 삼각주 연안을 침입한 셰르덴 해적을 물리쳤다.', 3, '연안 지역의 안전을 지키고 일부를 군대에 편입했다.'),
('ramesses-ii-2', 'ramesses-ii', -1274, '카데시 전투', '시리아의 카데시에서 히타이트군과 싸웠으나 결정적 승리 없이 물러났다.', -2, '대규모 원정에도 카데시 확보에 실패했다.'),
('ramesses-ii-3', 'ramesses-ii', -1264, '아부심벨 신전 건설', '누비아의 아부심벨에 바위를 깎아 만든 거대한 신전 건설을 시작했다.', 6, '고대 이집트를 대표하는 건축물로 오늘날까지 인류 유산으로 남았다.'),
('ramesses-ii-4', 'ramesses-ii', -1259, '히타이트와 평화조약', '히타이트 왕 하투실리 3세와 평화조약을 맺었다.', 7, '현존하는 가장 오래된 평화조약 문서 가운데 하나로 두 나라 사이에 오랜 평화를 가져왔다.'),
('ramesses-ii-5', 'ramesses-ii', -1245, '히타이트 공주와 혼인', '하투실리 3세의 딸을 왕비로 맞아 동맹을 다졌다.', 2, '평화조약을 왕실 혼인으로 뒷받침했다.'),
('ashoka-1', 'ashoka', -261, '칼링가 정복', '동부 해안의 칼링가를 정복했으며 스스로 칙령에 10만 명이 죽고 15만 명이 끌려갔다고 기록했다.', -7, '정복 과정에서 막대한 인명이 희생되었다.'),
('ashoka-2', 'ashoka', -257, '담마 칙령 반포', '바위와 석주에 새긴 칙령으로 비폭력, 종교 간 관용, 생명 존중을 통치 원칙으로 알렸다.', 6, '관용과 윤리에 바탕을 둔 통치 이념을 제시해 후대에 오래 기억되었다.'),
('ashoka-3', 'ashoka', -257, '공공 복지 시설 확충', '칙령에 따라 도로변에 나무와 우물을 두고 사람과 동물을 위한 치료 시설을 마련했다.', 4, '백성의 생활 여건을 실질적으로 개선했다.'),
('ashoka-4', 'ashoka', -250, '불교 전법사 파견', '아들 마힌다를 스리랑카에 보내는 등 여러 지역에 불교 전법사를 파견했다.', 7, '불교가 인도 밖 아시아 각지로 퍼지는 계기가 되었다.'),
('genghis-khan-1', 'genghis-khan', 1204, '위구르 문자 도입', '나이만을 정복한 뒤 위구르 문자로 몽골어를 적게 해 몽골 문자의 기원이 되었다.', 4, '몽골에 처음으로 문자 기록과 행정 문서의 기반을 마련했다.'),
('genghis-khan-2', 'genghis-khan', 1206, '몽골 통일과 칸 즉위', '쿠릴타이에서 몽골 여러 부족의 추대를 받아 칭기즈 칸으로 즉위했다.', 8, '분열된 초원 부족을 하나의 국가로 묶어 몽골 민족의 정체성을 형성했다.'),
('genghis-khan-3', 'genghis-khan', 1206, '천호제 편성', '유목민을 부족이 아닌 천호 단위의 군사·행정 조직으로 재편했다.', 5, '부족 간 분열을 줄이고 강력한 군사 국가의 바탕이 되었다.'),
('genghis-khan-4', 'genghis-khan', 1215, '금나라 중도 함락', '금나라 수도 중도(지금의 베이징)를 함락하고 약탈했다.', -5, '화북 지역에 큰 파괴와 인명 피해를 남겼다.'),
('genghis-khan-5', 'genghis-khan', 1221, '호라즘 원정 중 도시 학살', '호라즘 원정에서 니샤푸르·메르브 등 저항한 도시의 주민을 대량 학살했다.', -9, '중앙아시아와 이란의 도시 문명을 파괴하고 막대한 인명을 앗아갔다.'),
('genghis-khan-6', 'genghis-khan', 1227, '서하 멸망', '서하를 공격해 수도를 함락하고 나라를 멸망시켰다.', -6, '정복 과정의 파괴로 탕구트 문화가 크게 쇠퇴했다.'),
('suleiman-i-1', 'suleiman-i', 1521, '베오그라드 점령', '헝가리 왕국의 요새 도시 베오그라드를 점령했다.', 4, '중부 유럽으로 진출하는 거점을 확보했다.'),
('suleiman-i-2', 'suleiman-i', 1526, '모하치 전투 승리', '모하치에서 헝가리군을 격파하고 국왕 러요시 2세가 전사했다.', 5, '헝가리 왕국이 무너지고 오스만이 중부 유럽의 강자로 자리 잡았다.'),
('suleiman-i-3', 'suleiman-i', 1529, '제1차 빈 포위 실패', '합스부르크의 수도 빈을 포위했으나 함락하지 못하고 철수했다.', -3, '큰 원정 비용을 들이고도 목표를 이루지 못했다.'),
('suleiman-i-4', 'suleiman-i', 1534, '바그다드 정복', '사파비 왕조와의 전쟁에서 바그다드를 차지했다.', 4, '메소포타미아를 확보해 제국의 동부 영역을 넓혔다.'),
('suleiman-i-5', 'suleiman-i', 1538, '프레베자 해전 승리', '바르바로스 하이레딘이 이끈 함대가 신성동맹 연합 함대를 물리쳤다.', 4, '이후 수십 년간 동지중해 제해권을 확보했다.'),
('suleiman-i-6', 'suleiman-i', 1553, '장남 무스타파 처형', '반역 의심을 받은 장남 무스타파를 원정 진영에서 처형했다.', -4, '유능한 후계자를 잃고 이후 왕위 계승을 둘러싼 혼란을 키웠다.'),
('suleiman-i-7', 'suleiman-i', 1557, '쉴레이마니예 모스크 완공', '건축가 미마르 시난이 설계한 쉴레이마니예 모스크를 이스탄불에 완공했다.', 5, '오스만 건축의 정점으로 꼽히며 오늘날까지 이스탄불을 대표하는 유산이다.'),
('ataturk-1', 'ataturk', 1922, '독립전쟁 승리', '아나톨리아에 진주한 그리스군을 몰아내고 독립전쟁을 승리로 이끌었다.', 8, '분할 위기에 놓였던 튀르키예의 주권과 영토를 지켜냈다.'),
('ataturk-2', 'ataturk', 1923, '공화국 선포', '로잔 조약으로 국경을 인정받은 뒤 튀르키예 공화국을 선포하고 초대 대통령이 되었다.', 8, '오스만 왕조를 대신하는 근대 국민국가를 세웠다.'),
('ataturk-3', 'ataturk', 1924, '칼리파제 폐지', '오스만 왕조가 이어 온 칼리파 제도를 폐지하고 종교 법정을 없앴다.', 4, '국가와 종교를 분리하는 세속주의 체제의 기초를 놓았다.'),
('ataturk-4', 'ataturk', 1925, '질서유지법과 반대파 탄압', '쿠르드인 셰이크 사이드 반란을 계기로 질서유지법을 만들어 반란을 진압하고 야당과 언론을 폐쇄했다.', -4, '반대 세력을 억눌러 일당 체제를 굳혔다.'),
('ataturk-5', 'ataturk', 1926, '민법 제정', '스위스 민법을 바탕으로 새 민법을 만들어 일부다처제를 폐지하고 여성의 이혼·상속 권리를 인정했다.', 6, '가족과 여성의 법적 지위를 근본적으로 바꾸었다.'),
('ataturk-6', 'ataturk', 1928, '문자 개혁', '아랍 문자 대신 라틴 문자를 바탕으로 한 새 튀르키예 문자를 도입했다.', 7, '문자 학습을 쉽게 해 문맹률을 크게 낮추는 데 기여했다.'),
('ataturk-7', 'ataturk', 1934, '여성 참정권 부여', '여성에게 국회의원 선거권과 피선거권을 부여했다.', 6, '유럽 여러 나라보다 앞서 여성의 정치 참여를 보장했다.'),
('ataturk-8', 'ataturk', 1937, '데르심 진압', '데르심 지역 쿠르드인 봉기를 군대로 진압하는 과정에서 다수의 주민이 학살되고 강제 이주되었다.', -6, '민간인을 포함한 대규모 인명 피해와 강제 이주를 낳았다.'),
('mandela-1', 'mandela', 1993, '과도헌법 협상 타결', '데 클레르크 정부와의 협상 끝에 다인종 선거를 규정한 과도헌법에 합의했다.', 8, '내전 위기 속에서 아파르트헤이트를 평화적으로 끝내는 길을 열었다.'),
('mandela-2', 'mandela', 1994, '첫 다인종 총선과 국민통합정부', '첫 다인종 총선에서 승리해 대통령이 되고 옛 집권당까지 참여하는 국민통합정부를 구성했다.', 7, '인종을 넘어선 권력 공유로 체제 전환을 안정시켰다.'),
('mandela-3', 'mandela', 1994, '재건개발계획 시행', '주택·전기·상수도 보급을 목표로 한 재건개발계획을 시작했다.', 3, '기초 생활 시설을 넓혔으나 빈곤과 불평등 해소에는 한계가 있었다.'),
('mandela-4', 'mandela', 1995, '진실화해위원회 설치', '아파르트헤이트 시기 인권 침해를 조사하는 진실화해위원회를 법으로 설치했다.', 7, '과거 범죄를 드러내면서도 보복을 피하는 이행기 정의의 모델이 되었다.'),
('mandela-5', 'mandela', 1995, '럭비 월드컵 화합 행보', '백인 중심 스포츠였던 럭비 월드컵 결승에 대표팀 유니폼을 입고 나서 우승컵을 건넸다.', 2, '흑백 화합을 상징하는 장면으로 국민 통합에 기여했다.'),
('mandela-6', 'mandela', 1996, '신헌법 공포', '폭넓은 권리장전을 담은 새 헌법을 공포했다.', 8, '평등과 기본권을 보장하는 민주 헌정 질서를 확립했다.'),
('mandela-7', 'mandela', 1999, '단임 후 퇴임', '재선이 가능했으나 한 차례 임기만 마치고 스스로 물러났다.', 4, '평화적 정권 이양의 선례를 남겼다.')
